(1378262, 'Lobang Buaya, 309 Hari Sebelum Tragedi Berdarah', 'Kejahatan', 99, 'NR', 'When a spate of gruesome killings rocks the countryside in East Jakarta, army officer Soegeng is tasked with clearing up rumours about the military’s involvement. Soegeng’s investigation, however, confronts him with the foundations of corruption – a truth too close for comfort.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/eWgVIP4Z3BkgdOSbkO6Sr46ffyt.jpg', 'https://image.tmdb.org/t/p/w1280/mOLtKIvXd1SmobFAaANA1MOuoDk.jpg', 6, 'bxLqGxvjiYQ', '2026-10-01', 4.14, 1, 'tt34548453', null, null, null, 'Kejahatan, Kengerian, Misteri, Cerita Seru', 'Hanung Bramantyo', 'Haqi Achmad, Hanung Bramantyo', 'Shierly Kosasih', 'Adhya Pictures, Dapur Film, EST Studios, JERRYGOOD Company Inc.', '[{"name":"Baskara Mahendra","character":"Soegeng"},{"name":"Carissa Perusset","character":"Arum Wangi"},{"name":"Khiva Iskak","character":"Suradji"},{"name":"Anya Zen","character":"Ningsih"},{"name":"Mathias Muchus","character":"Sukarya / The Great Lord"},{"name":"Abah Qomar","character":"Kyai Soleman"},{"name":"Royhan Hidayat","character":"Supri"},{"name":"\"Tuwek\" Dinmas Herjuna","character":"Suripno"},{"name":"Kurniawan Hasnajaya","character":"Supono"},{"name":"Ari Purnomo","character":"Sumanto"}]'::jsonb, '17+', null),
(1565598, 'Dan Bandung', 'Drama', 120, 'NR', 'Basil, a working-studying Fine Arts student, falls in love with Elma after meeting her at a Persib soccer match. He creates a t-shirt featuring her image that goes viral, leading to their acquaintance and eventual dating. However, their relationship faces opposition from Elma''s father, forcing Basil to fight for his love amidst various obstacles.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/fSK0eQ6toOrjTpRtqB1WoqN50cc.jpg', 'https://image.tmdb.org/t/p/w1280/3W9ipa59TAws4nAbaP0SdksktJG.jpg', 6.2, 'l5GGKpxcCYc', '2026-08-20', 3.861, 3, 'tt43602769', 7.5, 14, null, 'Drama, Percintaan', 'Rudi Soedjarwo', 'Titien Wattimena, Pidi Baiq', 'Titin Suryani', 'Verona Films, TIX ID', '[{"name":"Samo Rafael","character":"Basil"},{"name":"Shanna Shannon","character":"Elma"},{"name":"Keisya Levronka","character":"Susi"},{"name":"Paul Aro","character":"Bimo"},{"name":"Razan Zu","character":"Doni"},{"name":"Theo Supple","character":"Uu"},{"name":"Jenny Zhang","character":"Andini"},{"name":"Donny Damara","character":"Kertawijaya"},{"name":"Arswendy Bening Swara","character":"Nugraha"},{"name":"Nugie","character":"Mang Yadi"}]'::jsonb, '13+', null),
(1420041, 'Memburu Pemangsa', 'Aksi', 115, 'NR', 'Sekelompok jurnalis sedang menginvestigasi kasus pembunuhan anak, namun tiap petunjuk justru membuka teror baru, dan mencari tahu terlalu dalam membuat mereka dalam bahaya yang tak mereka pahami.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/iF8QBPgMvrqv1HEIPH2eIh6Z4eQ.jpg', 'https://image.tmdb.org/t/p/w1280/44fTEcaEtk7PmGFPZUSQEsThGGF.jpg', 5.7, 'PceQZIf1k70', '2026-09-24', 3.429, 3, 'tt35486488', null, null, null, 'Aksi, Kejahatan, Kengerian', 'Umay Shahab', 'Rezy Junio, Umay Shahab, Reka Wijaya', 'Imam Salimy', 'Sinemaku Pictures, Legacy Pictures, NextG Investment, Applause Entertainment', '[{"name":"Laura Basuki","character":"Agnes"},{"name":"Prilly Latuconsina","character":"Cia"},{"name":"Yasamin Jasem","character":"Anya"},{"name":"Taskya Namya","character":"Brina"},{"name":"Teuku Rifnu Wikana","character":"The Predator"},{"name":"Septian Dwi Cahyo","character":"Dudi"},{"name":"Andri Mashadi","character":"Petra"},{"name":"Norman R. Akyuwen","character":"Lara"},{"name":"Jordan Omar","character":"Pandu"},{"name":"Javinada Qeila","character":"Cindy"}]'::jsonb, '17+', null),
(1541802, 'Operasi Pesta Copet', 'Komedi', 113, 'NR', 'In a desperate act to get quick money, Ijal and friends embark on a high-stakes operation: pickpocketing at Indonesia''s biggest music festival, Pestapora.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/q6jhaPlAnzNFuvPDbDXBDbavIXE.jpg', 'https://image.tmdb.org/t/p/w1280/zj0UjmCotGH7BnMRbKEr5ZxQUZE.jpg', 8, 'OB6e0VrfUyQ', '2026-08-27', 3.258, 2, 'tt38201949', 7.9, 71, 'TV-14', 'Komedi, Kejahatan, Musik', 'Edy Khemod', 'Rino Sarjono, Edy Khemod', 'Ernest Prakasa, Dipa Andika, Iqbaal Ramadhan, James Erlangga', 'Imajinari, Angin Segar Production, Boss Creator, Legacy Pictures', '[{"name":"Iqbaal Ramadhan","character":"Ijal"},{"name":"Kristo Immanuel","character":"Adut"},{"name":"Zulfa Maharani","character":"Tia"},{"name":"Kawai Labiba","character":"Melodi"},{"name":"Fauzan Lubis","character":"Silet"},{"name":"Azizah Hanum","character":"Hanum"},{"name":"Ardit Erwandha","character":"Maman"},{"name":"Kiki Narendra","character":"Toni"},{"name":"Mal Jupri","character":"Atot"},{"name":"Rio Dumatubun","character":"Opik"}]'::jsonb, '13+', null),
(1716269, 'Rumah Singgah', 'Drama', 113, 'NR', 'Karla, a talented young runner diagnosed with bone cancer, receives treatment at a halfway house. There, she learns to accept reality through the support of the residents and bu Andin, while together they realize their ultimate dream.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/m3N5NcK4rE7GOaWAuefr0xbncpX.jpg', 'https://image.tmdb.org/t/p/w1280/4WkrOK5DkGO0QIdggzejKoBeDOr.jpg', 7.6, 'B-LKbBHGWa4', '2026-08-27', 3.314, 4, 'tt39060117', null, null, null, 'Drama', 'Dyan Sunu Prastowo', 'Raditya Kurnia, Celvin Jaya Hadi', 'Hans Andreas', 'Mandela Pictures, Limelight Pictures, Senara Films', '[{"name":"Adhisty Zara","character":"Karla"},{"name":"Devano Danendra","character":"Luki"},{"name":"Ciccio Manassero","character":"Toni"},{"name":"Messi Gusti","character":"Pika"},{"name":"Aming Sugandhi","character":"Mang Didu"},{"name":"Dewi Irawan","character":"Bu Andin"},{"name":"Alex Abbad","character":"Ardi"},{"name":"Marthino Lio","character":"Pras"},{"name":"Agnes Naomi","character":"Mayang"},{"name":"Rena Haura","character":"Gadis"}]'::jsonb, 'SU', null),
(1450470, 'Perumahan Laddaland', 'Drama', 99, 'NR', 'Demi memberikan kehidupan yang lebih layak bagi istri dan anak-anaknya, Tomy (Andri Mashadi) memberanikan diri mengambil KPR untuk membeli rumah impian. Kebahagiaan itu tak berlangsung lama. Sejak menempati perumahan baru, keluarganya diteror berbagai kejadian tak wajar. Bisikan misterius, penampakan mengerikan, dan rahasia kelam di balik perumahan tersebut mengancam keselamatan mereka.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/nQvMdF0bUEEM0jDzpWMUcaAkGsH.jpg', 'https://image.tmdb.org/t/p/w1280/mY2iDDJxNJkZ3HWJps7N5MzBjWz.jpg', 4, 'yo7X5ouM-Kg', '2026-08-13', 3.119, 2, 'tt43484979', 6.5, 18, 'TV-MA', 'Drama, Kengerian, Misteri', 'Awi Suryadi', 'Lele Laila', 'Manoj Punjabi', 'MD Pictures', '[{"name":"Titi Kamal","character":"Melissa"},{"name":"Andri Mashadi","character":"Tomy"},{"name":"Anantya Rezky Kirana","character":"Tania"},{"name":"Shakeel Fauzi Aisy","character":"Elvin"},{"name":"Delia Husein","character":"Eneng"},{"name":"Aufa Assegaf","character":"Santoso"},{"name":"Laras Sardi","character":"Astri"},{"name":"Raffan Al Aryan","character":"Hugo"},{"name":"Adjis Doaibu","character":"Parto"},{"name":"Arief Didu","character":"Arif"}]'::jsonb, '17+', null),
(1567791, 'Munafik: Melawan Iblis', 'Kengerian', 103, 'NR', 'Di perjalanan pulang setelah membantu sebuah keluarga mengusir Iblis di tubuh anak mereka, Adam (Arya Saloka) seorang pengajar agama sekaligus praktisi ruqyah mengalami kecelakaan maut yang membuatnya kehilangan Aini, istrinya. Sejak saat itu ia berhenti melakukan ruqyah dan hidup dalam kesedihan berkepanjangan. Sampai suatu hari, ia diminta Anwar (Dimas Aditya) menyelamatkan Fitri (Acha Septriasa) seorang perawat sekaligus putri dari Mansur (Donny Damara), figur yang dihormati di desa tempat Adam tinggal. Adam yang awalnya menolak menemukan alasan untuk kembali melakukan ruqyah karena mengingat pesan mendiang istrinya. Namun, seiring waktu ia menemukan ada rahasia gelap di balik terror gaib yang menimpa Fitri.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/sXrzWnoA14DWSMUqCEY0o0CTxPg.jpg', 'https://image.tmdb.org/t/p/w1280/9W2ZK1AzTE8WIw10gnzDzVLzXEc.jpg', 6.8, 'gkij9R9EV5o', '2026-09-03', 3.684, 2, 'tt38782610', 6.8, 13, 'TV-MA', 'Kengerian, Misteri, Cerita Seru', 'Guntur Soeharjanto', 'M. Ali Ghifari', 'Oswin Bonifanz, Ayu Amirrol, Syamin Yusof', 'Unlimited Production, Skop Productions Sdn. Bhd., AZ Films, Komet Productions', '[{"name":"Arya Saloka","character":"Ustadz Adam"},{"name":"Acha Septriasa","character":"Fitri"},{"name":"Dimas Aditya","character":"Ustadz Anwar"},{"name":"Muhammad Faqih Alaydrus","character":"Amir"},{"name":"Donny Damara","character":"H. Mansyur"},{"name":"Nova Eliza","character":"Hj. Zulfa"},{"name":"Izabel Jahja","character":"Umi Fitri"},{"name":"Widi Dwinanda","character":"Aini"},{"name":"Elvira Devinamira","character":"Hanifah"},{"name":"Oce Permatasari","character":"ART H. Mansyur"}]'::jsonb, '17+', null),
(1716222, 'Paket Santet', 'Kengerian', 98, 'NR', 'Sebuah paket tiba di depan pintu. Tidak ada nama pengirim. Tidak ada alasan mengapa paket itu ditujukan kepada mereka. Namun, sejak paket itu dibuka, hidup penerimanya langsung berubah jadi mimpi buruk. Satu per satu nyawa menjadi taruhan. Kini, pertanyaannya bukan lagi bagaimana cara menghindari paket tersebut, melainkan bagaimana cara terhindar dari kutukan setelah menerimanya.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/ooeIRaAM9N02d8Z4eXPKE5BlBMM.jpg', 'https://image.tmdb.org/t/p/w1280/wP70ACOajhix1Ko845sBxUT9vkG.jpg', 6, 'iAAtCbIbGfU', '2026-08-27', 2.905, 2, 'tt42697813', 7.7, 7, null, 'Kengerian, Misteri, Cerita Seru', 'Dinna Jasanti', 'Obe Karel, Titien Wattimena, Ambaridzki Ramadhantyo', 'Shanty Harmayn, Aoura Lovenson Chandra, Tanya Yuson', 'BASE Entertainment, PK Films, Applause Entertainment, ARENDI', '[{"name":"Fatih Unru","character":"Deva"},{"name":"Yasamin Jasem","character":"Bella"},{"name":"Gabriella Ekaputri","character":"Celia"},{"name":"Fadly Faisal","character":"Ale"},{"name":"Fiki Naki","character":"Firza"},{"name":"Farandika","character":"Glen"},{"name":"Azela Putri","character":"Kiki"},{"name":"Vonny Anggraini","character":"Deva''s Mother"},{"name":"Aida Nurmala","character":"Bella''s Mother"},{"name":"Moh Iqbal Sulaiman","character":"Rizal"}]'::jsonb, '13+', null),
(1747310, 'Ghosthing', 'Komedi', 100, 'NR', 'A stoic mortician endowed with the ability to perceive the deceased finds his quiet existence upended when the dramatic spirit of a high-profile influencer refuses to depart, forcing him into an unauthorized investigation to prove her sudden demise was the result of homicide.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/rJYpSH06tKXoSArz6vDBIyaPf9Q.jpg', 'https://image.tmdb.org/t/p/w1280/cnwrrEcuDTwV5H21H35fZbHRUPE.jpg', null, 'WoL7tTL-hJQ', '2026-10-15', 3.035, 0, 'tt45972746', null, null, null, 'Komedi, Fantasi, Kengerian', 'Arie Azis', 'Evelyn Afnilia', 'Hartawan Triguna', 'Imperial Pictures', '[{"name":"Yasamin Jasem","character":"Maya"},{"name":"Baskara Mahendra","character":"Alfian"},{"name":"Indian Akbar","character":"Nuka"},{"name":"Tanta Ginting","character":"Bang Arip"},{"name":"Chika Waode","character":"Nurse Wanda"},{"name":"Leony Vitria Hartanti","character":"Ci Nat"},{"name":"Siti Fauziah","character":"Mbak Min"},{"name":"Iang Darmawan","character":"Empu Sandung"},{"name":"Reinold Lawalata","character":"Security Guard Tablo"},{"name":"Mathias Muchus","character":"Mirza"}]'::jsonb, null, null),
(1739312, 'Warga Rusun 609', 'Komedi', 103, 'NR', 'The idiosyncratic tenants of a public housing complex must form a unified front to resist an aggressive municipal demolition plan, all while covertly managing a severe supernatural haunting inside Room 609 by an aggrieved spirit demanding an unfulfilled romantic vow.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/d9k5T523oJjvNBEduSIuBJ6rvpR.jpg', 'https://image.tmdb.org/t/p/w1280/7uQrqaL25mCJXCCSYDBPRHfxGEu.jpg', 5, 'HK3qtX_S0FQ', '2026-10-01', 3.412, 2, 'tt43720940', 6.8, 16, null, 'Komedi, Kengerian', 'Herwin Novianto', 'Upi Avianto', 'Gope T. Samtani', 'Rapi Films, Sky Media, Legacy Pictures, Vortera Studios', '[{"name":"Ranty Maria","character":"Bunga"},{"name":"Morgan Oey","character":"Arka Susanto"},{"name":"Gita Bhebhita","character":"Damai Sejahtera boru Sembiring"},{"name":"Tanta Ginting","character":"Terang Tarigan"},{"name":"Sarah Sechan","character":"Wati"},{"name":"Dimas Danang","character":"Wira"},{"name":"Galabby Thahira","character":"Nurjanah"},{"name":"Riyuka Bunga","character":"Tuti"},{"name":"Aming Sugandhi","character":"Anjay"},{"name":"Yono Bakrie","character":"Gugum"}]'::jsonb, '13+', null),
(1727650, 'Ibadah & Cinta', 'Drama', 116, 'NR', 'A secular young man raised in Australia undergoes a profound spiritual awakening after falling in love with the daughter of a prominent Islamic scholar, only for their matrimonial aspirations to be jeopardized by a pre-arranged betrothal mandated by her traditionalist family.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/cQlIFMvnAAUH9MZ7l1UkSD13ddB.jpg', 'https://image.tmdb.org/t/p/w1280/v9pNRRWO5gZ1ybKxmKVeL7yTgSD.jpg', 7, '_k-qM7bnIbg', '2026-09-24', 3.181, 1, 'tt40201329', null, null, null, 'Drama, Percintaan', 'Jastis Arimba', 'Ifan Adriansyah Ismail, Jastis Arimba', 'Rendy Gunawan, Arismuda Irawan', 'Sinemata, Multi Buana Kreasindo', '[{"name":"Achmad Megantara","character":"Rico"},{"name":"Indah Permatasari","character":"Santun"},{"name":"Adhin Abdul Hakim","character":"Ganda"},{"name":"Berlliana Lovel","character":"Nissa"},{"name":"Mathias Muchus","character":"Kyai Umar"},{"name":"Elma Theana","character":"Khadijah"},{"name":"Jamie Aditya","character":"Rico''s Dad"},{"name":"Sita Permata Sari","character":"Desi"},{"name":"Nadzira Shafa","character":"Zira"},{"name":"Stevan Rizky","character":"Ustad Salman"}]'::jsonb, '13+', null),
(1589665, 'Kuasa Gelap: Perjanjian Darah', 'Kengerian', 117, 'NR', 'Following a catastrophic, failed ritual in a remote Indonesian province, two Catholic exorcists are deployed to confront a devastatingly powerful ancient entity unleashed by an ancestral pact for illicit wealth.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/pnr5cn7TJlGw6yUMgbCtDkGRLuQ.jpg', 'https://image.tmdb.org/t/p/w1280/yPeEsPDAsTrYpBNEwaO4xziacuI.jpg', 6.7, 'DKaO7xm7tpo', '2026-10-08', 2.458, 3, 'tt41272731', null, null, 'TV-MA', 'Kengerian', 'Rizal Mantovani', 'Robert Ronny, Andri Cahyadi', 'Robert Ronny, Prima Taufik', 'Paragon Pictures, Ideosource Entertainment, Virtuelines Entertainment, Legacy Pictures', '[{"name":"Jerome Kurnia","character":"Romo Thomas"},{"name":"Lukman Sardi","character":"Romo Rendra"},{"name":"Lydia Kandou","character":"Sister Aloysia"},{"name":"Ferry Salim","character":"Halim"},{"name":"Feby Febiola","character":"Linda"},{"name":"Venly Arauna","character":"Daniel"},{"name":"Sisca Saras","character":"Young Aloysia"},{"name":"Keysha Angelica","character":"Nia"},{"name":"Kiki Narendra","character":"Romo Wicaksana"},{"name":"Faiz Vishal","character":"Bayu"}]'::jsonb, '13+', null),
(1280076, 'Empat Musim Pertiwi', 'Drama', 137, 'NR', 'Pertiwi returns to her hometown after spending two decades in prison to rebuild her life. There, she finds power in things that have been abandoned: discarded electronic devices that mysteriously light up and a community of outcasts living on the fringes of society. But coming home also means confronting the four men who sent her to prison and now rule the village. Together with the outcasts, Pertiwi begins to uncover the darkness that still haunts the place - and the past she thought she had left behind.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/gjDK2E0FNwCxy3B915ODQZfy4QD.jpg', 'https://image.tmdb.org/t/p/w1280/7GtW8tgNMc8iL6nvzkY2vAwNvQs.jpg', 8.3, 'SV4PIdI9JL0', '2026-09-22', 2.497, 3, 'tt36459577', null, null, null, 'Drama, Cerita Seru, Kejahatan', 'Kamila Andini', 'Kamila Andini', 'Ifa Isfansyah', 'Forka Films, Giraffe Pictures, Epicmedia, One Two Films', '[{"name":"Putri Marino","character":"Pertiwi"},{"name":"Christine Hakim","character":"Mak Ira"},{"name":"Arya Saloka","character":"Bisma"},{"name":"Hana Malasan","character":"Niken"},{"name":"Iswadi Pratama","character":"Pertiwi''s Father"},{"name":"Hargi Sundari","character":"Pertiwi''s Mother"},{"name":"Shofia Shireen","character":"Teenage Pertiwi"},{"name":"Nagra Pakusadewo","character":"Jonet"},{"name":"Totos Rasiti","character":"Fajar"},{"name":"Dwika Pradnyana","character":"Kuntet"}]'::jsonb, '17+', null),
(1757007, 'Kuru'' Sumange''', 'Drama', 100, 'NR', 'In a small town in the Bugis region, seven children from diverse backgrounds are brought together for a Regional Children''s Festival. Aisyah, a lonely girl, meets fellow participants who are each grappling with their own personal struggles. The judges group them together to stage a top-notch performance, and a variety of conflicts arise, challenging them to keep the show going in the name of friendship.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/4TP3GC9HpBJKE6ST1W3ZM5M2m3.jpg', null, null, null, '2026-08-30', 2.266, 0, null, null, null, null, 'Drama, Keluarga, Musik', 'Irwandi Irgantara', 'Irwandi Irgantara', 'Irwandi Irgantara', 'Bale Rakko Production', '[{"name":"Aisyah Afiqa","character":"Aisyah"},{"name":"Andi Izzatunnisa","character":"Santi"},{"name":"Gerhana Ayunindya","character":"Kirana"},{"name":"Luthfia Zahra","character":"Yasmin"},{"name":"Andi Atifa Nur Maharani","character":"Nindi"},{"name":"Muh. Fais Rezki","character":"Hendra"},{"name":"Adlin Izzanil","character":"Fahri"}]'::jsonb, 'SU', null),
(1601704, 'Hasut', 'Kengerian', 96, 'NR', 'In the wake of their parents'' tragic decease, a young woman orchestrates a remote wilderness expedition to rehabilitate her estranged sister, only for the group to be terrorized by manipulative supernatural entities exploiting their communication devices.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/wNv9rYd0Nqeq5vWPwyicognSER3.jpg', 'https://image.tmdb.org/t/p/w1280/sRpgypBSBlEqT3PEUIFoouuSUwX.jpg', 6, '6FDtvY6r9uo', '2026-10-08', 2.511, 2, 'tt44686440', 7.8, 9, null, 'Kengerian, Misteri, Cerita Seru', 'Ilya Sigma', 'Priesnanda Dwisatria, Ilya Sigma', 'Siera Tamihardja, John Badalu', 'The United Team of Art, TIX ID, Alunan', '[{"name":"Karina Salim","character":"Vira"},{"name":"Rachel Amanda","character":"Rere"},{"name":"Kevin Ardilova","character":"Derry"},{"name":"Marthino Lio","character":"Dharma"},{"name":"Uti Isworo","character":"The Old Lady"},{"name":"Suryo Sarjito","character":"Dharma''s Father"},{"name":"Skyrania Iris","character":"Young Vira"},{"name":"Ghaniyyah Hafsa Saraswati Hosen","character":"Young Rere"},{"name":"Antonio Da Silva","character":"Derry''s Brother"}]'::jsonb, '17+', null),
(1601709, 'Bapakmu Kiper', 'Komedi', 90, 'NR', 'The story follows an 18-year-old named Ronaldhino Sujatmiko—known as Dino—who harbors anger toward his father, Warto. Warto is a former local soccer star and soccer gambler whom Dino believes is responsible for his mother’s death. Dino’s chance to leave his village comes through the Tarkam Super Cup, a soccer talent search tournament. The conflict comes to a head when Dino’s main team is taken over by another party just before the final. This situation forces his father, Warto, to step in and form a new team made up of veteran players, despite all the limitations they face.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/e91DcxPpBfjAuVf67rP8zVFEjBi.jpg', 'https://image.tmdb.org/t/p/w1280/6dporxDetmS1eYrmIbpZfLdX81D.jpg', 5, 'zDv6_dfI7F8', '2026-09-03', 2.18, 1, 'tt43635381', 2.3, 791, null, 'Komedi, Drama', 'Ody C. Harahap', 'Titien Wattimena, Aaron Hart', 'Patricia Gunadi', 'Entelekey Media, Entelekey Sinema', '[{"name":"Fedi Nuril","character":"Warto"},{"name":"Ali Fikry","character":"Ronaldhino Sujatmiko / Dino"},{"name":"Vidi Bule","character":"Adam Hansip"},{"name":"Tanta Ginting","character":"Ngatiman Bengkel"},{"name":"Augie Fantinus","character":"Hendra"},{"name":"Yanda Djaitov","character":"Supar Kuli"},{"name":"Chrismanto Eka Prastio","character":"Yono Copet"},{"name":"Didi Murs Mahmud","character":"David Bekam"},{"name":"Neysa Chandria","character":"Kristin"},{"name":"M. N. Qomaruddin","character":"Yadi Dukun"}]'::jsonb, '13+', null),
(1735309, 'Istimewa', 'Drama', 119, 'NR', 'Five disabled children embark on a desperate search for their runaway foster father, only to find themselves thrust into the public eye.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/eGqZmMRqVDdtgobGENgUYGAgiOu.jpg', 'https://image.tmdb.org/t/p/w1280/nKx4acOCV1U2EXJUMbIL00xbMlE.jpg', 6.5, 'Fjg4whNQH-Y', '2026-09-17', 2.118, 2, 'tt44688627', 7.5, 12, 'TV-PG', 'Drama', 'Ruben Adrian S.', 'Ruben Adrian S., Abdullah Mansuri, Talitha Abby Johana', 'Yanni Melwani, Abdullah Mansuri', 'Kairos Film', '[{"name":"Mathias Muchus","character":"Mahendra (Dad)"},{"name":"Yanni Melwani","character":"Kinan"},{"name":"Ajil Ditto","character":"Bagas"},{"name":"Agus Kuncoro","character":"Aji"},{"name":"Maxime Mustofa","character":"Mul"},{"name":"Rein","character":"Ken"},{"name":"Zulfadli Aldiansyah","character":"Aldo"},{"name":"Niatus Sholihah","character":"Nita"},{"name":"Bambang Ceper","character":"Bimo"},{"name":"Salsabilla Bella","character":"Ella"}]'::jsonb, 'SU', null),
(1735459, 'Ibu, Bagaimana Aku Tanpamu?', 'Drama', 111, 'NR', 'Confronted with the devastating reality of her mother’s terminal diagnosis, a young woman embarks on a compressed emotional journey to fulfill her mother''s final, unexpressed desires before her imminent decease, forcing a profound reckoning with grief and filial duty.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/zaL5fqcgMlBdkrwRF1g7XLDsbj0.jpg', 'https://image.tmdb.org/t/p/w1280/sLH3yzYvQn2UDWuEqtrsX1MAgB3.jpg', 6, 'Sh6ryxsOHYg', '2026-09-24', 2.903, 3, 'tt44773462', 6.1, 16, 'TV-G', 'Drama, Keluarga', 'Herwin Novianto', 'Alim Sudio', 'Frederica', 'Falcon Pictures', '[{"name":"Marsha Timothy","character":"Stella"},{"name":"Fara Shakila","character":"Rere"},{"name":"Praz Teguh","character":"Daniel Lim"},{"name":"Ivan Gunawan","character":"Prince"},{"name":"Sara Wijayanto","character":"Nita"},{"name":"Kiki Narendra","character":"Rommy"},{"name":"Queen Lubis","character":"Maya"},{"name":"Papham","character":"Hestu"},{"name":"仲川遥香","character":"Julia"},{"name":"Kinaryosih","character":"Deasy"}]'::jsonb, 'SU', null),
(1727665, 'Akal Imitasi', 'Drama', 98, 'NR', 'Set in the year 2029, the story focuses on an AI-based system called PIKO in schools, and how this technology widens the gap and leads to the loss of the true essence of learning.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/lxnXXcHffRvRo3mCKJYqPQCkpfz.jpg', 'https://image.tmdb.org/t/p/w1280/pQoz9HcCaiKIu8wFFuGh1X3M7My.jpg', 4, '6zT_Zjjqj0Y', '2026-09-17', 2.218, 1, 'tt43704631', null, null, null, 'Drama, Cerita Fiksi', 'Zhaddam Aldhy Nurdin', 'Chairul Rijal', 'Suherman Suhari', 'DL Entertainment', '[{"name":"Zaskia Alya Kyla","character":"Ika"},{"name":"Tika Bravani","character":"Teacher Lilis"},{"name":"Teuku Rifnu Wikana","character":"Teacher Damar"},{"name":"Rance Allen Wright","character":"Rafi"},{"name":"Arziqy Herdi Pratama","character":"Neo"},{"name":"Kaysha Varisha Wahab","character":"Alya"},{"name":"Ahmad Hafidz Makkaarennu","character":"Daniel"},{"name":"Mohammad Rannan Tristan","character":"Reyhan"},{"name":"Diva Pancarani","character":"Dewi"},{"name":"Wahyu Mellong","character":"Kevin"}]'::jsonb, 'SU', null),
(1716810, 'Autopsy: Dead Body Can Talk', 'Cerita Seru', 115, 'NR', 'Dr. Sumy Hastry—a sharp, calm, and experienced forensic is intertwined with intuition and supernatural phenomena that are part of her long journey.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/jI82Y6SCWUSUL2aw1Uokomd1Tlu.jpg', 'https://image.tmdb.org/t/p/w1280/l3D5HQv73YCenXfQ3ClXPcEJrRR.jpg', 4, 'LZrKHylvBzk', '2026-09-03', 2.139, 2, null, null, null, null, 'Cerita Seru, Misteri', 'Ouzan Ruz', 'M. Nurman Wardi', 'Marsa Moesa, Fariz Stanzah', 'Karya Kreatif Utama', '[{"name":"Masayu Anastasia","character":"dr. Sumy Hastry"},{"name":"Teuku Rifnu Wikana","character":"Rendra"},{"name":"Ge Pamungkas","character":"Mojo"},{"name":"Riyuka Bunga","character":"Yatna"},{"name":"Samuel Rizal","character":"Hary"},{"name":"Indra Frimawan","character":"Warji"},{"name":"Abdurrahman Arif","character":"Yanto"},{"name":"Nagra Pakusadewo","character":"Aldi"},{"name":"Zidni Hakim","character":""},{"name":"Andrew Suleiman","character":"Choi"}]'::jsonb, '17+', null),
(1469930, 'Tumbal Proyek', 'Kengerian', 106, 'NR', 'While investigating their father’s death inside a major bridge construction company, Yuda and his family attempt to prove that the frequent, deadly workplace accidents are actually human sacrifices.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/wdOa8jWX8u1YNSlWyRvoNCc9y7S.jpg', 'https://image.tmdb.org/t/p/w1280/k3Nc57fdRkzleHjodta45mGJV2C.jpg', 3.9, 'StEBQjJcubs', '2026-05-13', 15.888, 7, 'tt38497679', 6.8, 78, null, 'Kengerian, Cerita Seru', 'Jeropoint', 'Jeropoint', 'Dheeraj Kalwani', 'Dee Company', '[{"name":"Callista Arum","character":"Laras"},{"name":"Kiesha Alvaro","character":"Yuda"},{"name":"Karina Suwandi","character":"Martha"},{"name":"Eduwart Manalu","character":"Sutomo"},{"name":"Fuad Idris","character":"Mbah Tarmo"},{"name":"Agus Firmansyah","character":"Rudi"},{"name":"Adi Sudirja","character":"Yanto"},{"name":"Rendy Khrisna","character":"Bayu"},{"name":"Raffan Al Aryan","character":"Wahyu"},{"name":"Cetul Leatherart","character":"Heru"}]'::jsonb, '17+', null),
(1421155, 'Ikatan Darah', 'Aksi', 119, 'NR', 'A former martial arts athlete must face a network of loan sharks to save her younger brother, who is trapped in online gambling debt and risking their family’s safety.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/lF9amilOGIudUIq6NgDnz2YrPPa.jpg', 'https://image.tmdb.org/t/p/w1280/j5L5e211nYRd8DiLNDXbeGUsx7D.jpg', 6.5, 'Qq2Plb_X0gc', '2026-04-30', 8.568, 12, 'tt38221401', 8.3, 25, null, 'Aksi, Kejahatan, Cerita Seru', 'Sidharta Tata', 'Sidharta Tata, Rifki Ardisha', 'Ryan Santoso', 'Uwais Pictures, Legacy Pictures, KG Pictures, Uwais Team', '[{"name":"Livi Ciananta","character":"Mega"},{"name":"Derby Romero","character":"Bilal"},{"name":"Ismi Melinda","character":"Dini"},{"name":"Lydia Kandou","character":"Lastri"},{"name":"Teuku Rifnu Wikana","character":"Primbon"},{"name":"Abdurrahman Arif","character":"Boris"},{"name":"Rama Ramadhan","character":"Macan"},{"name":"Agra Piliang","character":"Jabrik"},{"name":"Rahmet Ababil","character":"Rico"},{"name":"Reza Nangin","character":"Zakar"}]'::jsonb, '17+', null),
(1590613, 'Cerita Lila', 'Kengerian', 106, 'NR', 'Lila, arwah seorang gadis kecil yang masih terikat pada masa lalunya, terus mencari saudari kembarnya yang hilang, Lili. Kehidupannya berubah saat Nia dan ibunya, Tari, pindah ke rumah tempat Lila berada. Persahabatan yang terjalin antara Lila dan Nia membawa mereka pada pencarian yang perlahan membuka rahasia kelam yang lama terkubur. Ketika kehadiran sosok Rahma mulai mengancam keselamatan mereka, Nia meminta bantuan Sara Wijayanto dan Wisnu untuk mengungkap kebenaran di balik tragedi masa lalu.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/80CcJdrV3ewqPawFMAFGIrldgR5.jpg', 'https://image.tmdb.org/t/p/w1280/9rZVlvA5Nk3SA4GJk1ySUbZLtTg.jpg', 5, '_S9ummr0mjg', '2026-06-18', 5.076, 3, 'tt39400218', null, null, null, 'Kengerian', 'Bobby Prasetyo', 'Erwanto Alphadullah, Gea Rexy, Sara Wijayanto', 'Raam Punjabi', 'MVP Pictures, Folago Pictures, PK Films, Legacy Pictures', '[{"name":"Lutesha","character":"Tari"},{"name":"Shareefa Daanish","character":"Rahma"},{"name":"Myesha Lin","character":"Nia"},{"name":"Firzanah Alya","character":"Lila & Lili"},{"name":"Sara Wijayanto","character":"Sara"},{"name":"Wisnu Hardana","character":"Wisnu"},{"name":"Whani Darmawan","character":"Bimo Tua"},{"name":"Demian Aditya","character":"Demian"},{"name":"Fadi Iskandar","character":"Fadi"},{"name":"Enrico Winaldy","character":"Kenny"}]'::jsonb, '17+', null),
(1322532, 'Cek Khodam', 'Komedi', 110, 'NR', 'Nowadays, people are more afraid of empty wallets, late payments, and the end of the month than ghosts. Ghosts are even used as entertainment through the content Cek Khodam (Hodgkin''s Check) created by three friends, Sakti, Wira, and Bima. Unbeknownst to them, their actions have drastically reduced the Human Fear Score (AKM). To restore the dignity of the supernatural world and raise the human fear score, the Commander of the Khodam is tasked with descending directly into the human world. However, the mission does not go according to plan. The harder the khodam try to scare humans, the more chaos they create.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/o2aUDzJxXJOGxfCyKF6oawHBf2d.jpg', 'https://image.tmdb.org/t/p/w1280/f4P6rDf6FuXe1wtw2ZYJgVtu4G0.jpg', 5, 'D8xsvnUCqp4', '2026-07-16', 3.394, 4, 'tt33702073', null, null, null, 'Komedi, Kengerian', 'Jeropoint', 'Jeropoint', 'Dheeraj Kalwani', 'Dee Company', '[{"name":"Saputra Kori","character":"Wira"},{"name":"Jirayut Afisan","character":"Sakti"},{"name":"Benidictus Siregar","character":"Bima"},{"name":"Angie Williams","character":"Noni Belanda"},{"name":"Adi Sudirja","character":"Genderuwo"},{"name":"Cetul Leatherart","character":"Pocong Karuhun"},{"name":"Fahira Almira","character":"Imah"},{"name":"Mikayla Sofia Mercedes","character":"Stella"},{"name":"Ence Bagus","character":"Sahroji"},{"name":"Rowiena Umboh","character":"Ratih"}]'::jsonb, '13+', null),
(1590909, 'Ibuku', 'Drama', 95, 'NR', 'A destitute widow and former traditional dancer defies social ostracization to embark on a desperate international journey, seeking a final reconciliation with her estranged daughter who faces execution abroad for the murder of an abusive employer.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/zYwxtzF9wIAPybLfU4s7sADX3ZG.jpg', 'https://image.tmdb.org/t/p/w1280/4HnXizTOzGJYc1FaHslow31dzZu.jpg', null, 'ItgV0HrDh9Q', '2026-10-08', 3.538, 0, 'tt38773544', null, null, null, 'Drama', 'Eddie Cahyono', 'Eddie Cahyono', 'Tika Bravani, 山口晋', 'ANP Talenta Media, Memorieslight Pictures, Yasa Buana Film, Chinese Shadows', '[{"name":"Christine Hakim","character":"Sumiati"},{"name":"Ayushita Nugraha","character":"Sri"},{"name":"Landung Simatupang","character":""},{"name":"Tika Bravani","character":""},{"name":"Udik Supriyanta","character":""},{"name":"Sriwidiyanti","character":""},{"name":"Nano Asmorodono","character":""},{"name":"Rendra Bagus Pamungkas","character":""},{"name":"Liek Suyanto","character":""},{"name":"Intan Kemalasari","character":""}]'::jsonb, null, null),
(1575207, 'Dilan ITB 1997', 'Drama', 110, 'NR', 'Dilan is an ITB student who returned from Cuba in March 1997. In the midst of the heated political situation leading up to the Reformation.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/petyKATP9csA38xHWyyJqW1x7Vz.jpg', 'https://image.tmdb.org/t/p/w1280/r9XPwN4o9uZOEmw46fg6d9OIJQ5.jpg', 6.6, 'xzues7Sn_44', '2026-04-30', 3.703, 5, 'tt38873792', 7.9, 42, 'TV-14', 'Drama, Percintaan', 'Fajar Bustomi, Pidi Baiq', 'Pidi Baiq, Adhitya Mulya, Ninit Yunita', 'Frederica', 'Falcon Pictures', '[{"name":"Ariel","character":"Dilan"},{"name":"Niken Anjani","character":"Ancika"},{"name":"Raline Shah","character":"Milea"},{"name":"Wafda Saifan Lubis","character":"Irwan"},{"name":"Rangga Nattra","character":"Nunu"},{"name":"Dany Beler","character":"Dani"},{"name":"Ira Wibowo","character":"Dilan’s mother"},{"name":"Qibil Changcuters","character":"Anwar"},{"name":"Arya Saloka","character":"Herdi"},{"name":"Denny Chandra","character":"Ancika''s father"}]'::jsonb, '13+', null),
(1589713, 'Badut Gendong', 'Aksi', 101, 'NR', 'Darso, a clown busker, lost his wife and unborn child to thug violence. In grief, he brought his wife''s body back to his village. However, the village is in chaos due to a conflict with an evil developer and a curse ritual that summons dark forces. Darso is also caught up in the evil forces connected to the person he loves most.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/kIAltyOVZFIRFFFgBUBABb0HyF7.jpg', 'https://image.tmdb.org/t/p/w1280/aVnrli2pknnbAeGhsjhLBWc5yCL.jpg', 8, 'yPaqYzR_ocI', '2026-05-27', 3.808, 4, 'tt39059815', null, null, null, 'Aksi, Drama, Kengerian, Fantasi, Cerita Seru', 'Charles Gozali', 'Charles Gozali, Asaf Antariksa, Dharma Putra', 'Linda Gozali', 'Magma Entertainment, Legacy Pictures, Komet Productions, Skop Productions Sdn. Bhd.', '[{"name":"Marthino Lio","character":"Darso"},{"name":"Clara Bernadeth","character":"Arini"},{"name":"Derby Romero","character":"Jamil"},{"name":"Dayinta Melira","character":"Darsi"},{"name":"Khiva Iskak","character":"Billy"},{"name":"Vonny Anggraini","character":"Yu Tini"},{"name":"Totos Rasiti","character":"Lik Badrun"},{"name":"Akbar Kobar","character":"Andul"},{"name":"Barry Prima","character":"Ki Kamboja"},{"name":"José Rizal Manua","character":"Mbah Kaum"}]'::jsonb, '17+', null),
(1616674, 'Aku Sebelum Aku', 'Drama', 127, 'NR', 'A young student battling pressure, panic and a demanding father uses a class project to discover that truth — not trophies — might finally set him free.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/xmwPr0YOFS6vC3aydnE85gxp36t.jpg', 'https://image.tmdb.org/t/p/w1280/1QiFfqaAhZi4HMlJNMvJVXOovc6.jpg', 6.7, null, '2026-07-11', 3.842, 22, 'tt39370887', null, null, null, 'Drama', 'Gina S. Noer', 'Gina S. Noer', 'Sigit Pratama, Anna Melani', 'Wahana Kreator Nusantara', '[{"name":"Bimasena","character":"Jati"},{"name":"Ringgo Agus Rahman","character":"Jaya"},{"name":"Widuri Puteri","character":"Asa"},{"name":"Prastiwi Dwiarti","character":"Ambu Asih"},{"name":"Aming Sugandhi","character":"Mr. Juned / Mr. Zai"},{"name":"Ronal Surapradja","character":"Uwa Geni"},{"name":"Ashila Husnia Fitriani","character":"Meranti"},{"name":"Candil","character":"Uwa Yayan"},{"name":"M. Yusuf Ozkan","character":"Echo"},{"name":"Darin Fauzi","character":"Dali"}]'::jsonb, '13+', null),
(1247038, 'Para Perasuk', 'Drama', 119, 'NR', 'In a town where pleasure equals being possessed by spiritual beings, Bayu aspires to be the shaman of a trance party so he can fundraise enough money to prevent an impending eviction.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/ipyK7A2rXwcnHXGVWGK9iJDDT8h.jpg', 'https://image.tmdb.org/t/p/w1280/4DUFiYoX7DBTFGrDSyW7lc8Wgm9.jpg', 7.6, 'TSlkrCZ_hYs', '2026-04-23', 3.512, 9, 'tt31382021', null, null, null, 'Drama', 'Wregas Bhanuteja', 'Wregas Bhanuteja, Alicia Angelina, Defi Mahendra', 'Iman Usman, Siera Tamihardja, Amalia Fitriani', 'Momo Film Co, Rekata Studio, Nathan Studios, Masih Belajar Pictures', '[{"name":"Angga Yunanda","character":"Bayu Laksana"},{"name":"Maudy Ayunda","character":"Laksmi"},{"name":"Anggun","character":"Guru Asri"},{"name":"Chicco Kurniawan","character":"Pawit Arifin"},{"name":"Bryan Domani","character":"Ananto"},{"name":"Indra Birowo","character":"Bayu''s Father"},{"name":"Ganindra Bimo","character":"Fahri"},{"name":"Ivonne Dahler","character":"Mrs. Nana"},{"name":"Aryudha Fasha","character":"Bang Yoga"},{"name":"Alex Suhendra","character":"Guru Bondan"}]'::jsonb, '13+', null),
(1590666, '''Ain', 'Kengerian', 110, 'NR', 'Driven by childhood traumas of neglect and severe body image issues, a prominent beauty influencer''s obsessive pursuit of online validation triggers a devastating spiritual curse, resulting in a gruesome physical deterioration that challenges her vanity.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/6KpPmKMrwjJgSVXqCem5X3xWiZe.jpg', 'https://image.tmdb.org/t/p/w1280/nqDROnbKp52GQEgqz1B7OTs0bOR.jpg', 4, 'sBgu9UAp3Ns', '2026-05-07', 3.646, 3, 'tt40597162', 4.3, 7, null, 'Kengerian, Cerita Seru', 'Archie Hekagery', 'Archie Hekagery', 'Raam Punjabi, Yuda Wirafianto, Pandu Adiputra', 'MVP Pictures, Manara Films', '[{"name":"Fergie Brittany","character":"Joy"},{"name":"Putri Ayudya","character":"Dini"},{"name":"Valentino Peter","character":"Hilman"},{"name":"Clara Kaizer","character":"Teen Joy"},{"name":"Putri Alya","character":"Teen Remaja"},{"name":"Dimas Putra Nurcahyo","character":"Teen Hilman"},{"name":"Iqbal Abdillah","character":"Medical Specialist"},{"name":"Irmahayati Desmod","character":"Clinic Doctor"},{"name":"Agus Firmansyah","character":"Psychiatrist"},{"name":"Amanda Gondowijoyo","character":"Therapist"}]'::jsonb, '17+', null),
(1263904, 'Monster Pabrik Rambut', 'Kengerian', 96, 'NR', 'PUTRI (Rachel Amanda) kehilangan ibunya, yang mati setelah beberapa hari tak tidur karena bekerja siang dan malam. Menurut MARYATI (Didik Nini Thowok), pemilik pabrik, ibunya mati bunuh diri. Awalnya ia percaya, tapi IDA (Lutesha), adiknya, mengatakan bahwa ibu mereka mati karena kesurupan. Untuk membuktikan omongannya, Ida memutuskan untuk lembur, tak tidur berhari-hari, demi melihat sendiri sosok hitam yang merebut tubuh ibunya. BONA (Iqbaal Ramadhan), adik bungsu mereka, memiliki kemampuan spesial. Ia mampu meregenerasi bagian tubuhnya. Sosok hitam berhasil menyandera Bona. Mampukah Putri dan Ida menyelamatkan Bona?', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/fiapXpPfhW3Uqjj0jMIVtaAdGRc.jpg', 'https://image.tmdb.org/t/p/w1280/m7pUxa1AaXjuvpFJsb4hvB25Lv.jpg', 7.2, 'onMcP76Nam8', '2026-06-04', 2.575, 3, 'tt34663597', null, 20, null, 'Kengerian, Fantasi', 'Edwin', 'Eka Kurniawan, Edwin, 松永大司', 'Muhammad Zaidy, Meiske Taurisia', 'Palari Films, Giraffe Pictures, Hassaku Lab, In Good Company', '[{"name":"Rachel Amanda","character":"Putri"},{"name":"Lutesha","character":"Ida"},{"name":"Iqbaal Ramadhan","character":"Bona"},{"name":"Didik Nini Thowok","character":"Maryati"},{"name":"Sal Priadi","character":"Rudi"},{"name":"Kev","character":"Tohar"},{"name":"Alit Aryani Willems","character":"Mrs. Sri"},{"name":"Ricky Cemor","character":"Soni"},{"name":"Kaluna","character":"Mimi"},{"name":"Yeri Mulyono","character":"Abbas"}]'::jsonb, '17+', null),
(1423191, 'Resident Evil', 'Kengerian', 95, 'NR', 'Medical courier Bryan unwittingly finds himself fighting for survival as one fateful, horrifying night collapses around him in chaos.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/i7UyjfPio0VFHB9rBUZSFyhOoM8.jpg', 'https://image.tmdb.org/t/p/w1280/3icyRAqgakNcQn6aDVz9libFmBA.jpg', 7.3, 'mNd1gb19A-c', '2026-09-16', 259.974, 971, 'tt35538033', null, null, 'R', 'Kengerian, Cerita Fiksi, Petualangan', 'Zach Cregger', 'Shay Hatten, Zach Cregger', 'Robert Kulzer, Roy Lee, Miri Yoon, Asad Qizilbash', 'Constantin Film, Subconscious, Vertigo Entertainment, Davis Films', '[{"name":"Austin Abrams","character":"Bryan"},{"name":"Paul Walter Hauser","character":"Paul"},{"name":"Kali Reis","character":"Maxine"},{"name":"Zach Cherry","character":"Carl"},{"name":"Johnno Wilson","character":"Officer Wilson"},{"name":"Shaun W. Loeser","character":"Puker"},{"name":"Zach Cregger","character":"Intercom (voice)"},{"name":"Emily Piggford","character":"Dr. Maria Stokes"},{"name":"Will Merrick","character":"Dave"},{"name":"Zoé Bellas","character":"Birdie"}]'::jsonb, '17+', 3238),
(1058424, 'Hope', 'Cerita Fiksi', 156, 'NR', 'Sebuah penemuan misterius terjadi di pinggiran kota pelabuhan kecil. Para penduduk mendapati diri mereka dalam kondisi perjuangan putus asa untuk bertahan hidup melawan sesuatu yang belum pernah mereka temui sebelumnya.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/ptqlN6mDIAqJjVA86J5eOoG82zc.jpg', 'https://image.tmdb.org/t/p/w1280/ujUwzNV8ZkOzZonvhhHsc9KOKDf.jpg', 6.9, 'OFaJzL83y0Q', '2026-07-15', 294.652, 236, 'tt27369017', 6.9, 4367, 'R', 'Cerita Fiksi, Misteri, Aksi', '나홍진', '나홍진', '나홍진, 김새미, Saerom Kim', 'Forged Films, Plus M Entertainment, Westworld Story', '[{"name":"황정민","character":"Go Bum-seok"},{"name":"조인성","character":"Go Sung-ki"},{"name":"정호연","character":"Lim Sung-ae"},{"name":"Alicia Vikander","character":"J''aur"},{"name":"Michael Fassbender","character":"Ma''veyyo"},{"name":"Taylor Russell","character":"Ai''dovor"},{"name":"Cameron Britton","character":"Va''migere"},{"name":"이상희","character":"Nak-yeon"},{"name":"음문석","character":"Yang-bae"},{"name":"임현식","character":"Hae-sul"}]'::jsonb, '13+', 4762),
(1377237, 'Runner', 'Aksi', 97, 'NR', 'A former soldier is thrown into a brutal race against time when a critical medical delivery makes him and his unlikely partner the targets of a ruthless cartel. As the mission spirals into a deadly manhunt, every detour, delay, and bullet pushes them closer to failure. With betrayal closing in from every side, they must survive the chase and deliver their cargo to save the life of a little girl.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/yBKMAIj7clP42UkFejhGDBBoTpb.jpg', 'https://image.tmdb.org/t/p/w1280/npXZNWjOEYrqdMDPQ11SGBrXqAG.jpg', 8.3, 'B6Z9MM1LhEA', '2026-09-07', 229.569, 619, 'tt31349844', 6.6, 493, 'PG-13', 'Aksi, Komedi', 'Scott Waugh', 'Tommy White, Miles Hubley', 'Todd Garner, Alan Ritchson, Mark Fasano, Jeffrey Greenstein', 'Broken Road Productions, AllyCat Entertainment, Nickel City Pictures, A Higher Standard', '[{"name":"Alan Ritchson","character":"Hank Malone"},{"name":"Owen Wilson","character":"Ben Bishop"},{"name":"Rodrigo Santoro","character":"Damian Zaldivar"},{"name":"Leila George","character":"Kate Baker"},{"name":"Kate Box","character":"Dr. Ainsley"},{"name":"Peta Sergeant","character":"Nurse Julie"},{"name":"Cecilia Toussaint","character":"Donna Zaldivar"},{"name":"Geraldine Hakewill","character":"Monica"},{"name":"Goran D. Kleut","character":"Luke"},{"name":"Scarlett Crabtree","character":"Ellie Baker"}]'::jsonb, '17+', 5160),
(1101412, 'Fall 2: Deadpoint', 'Cerita Seru', 98, 'NR', 'On a perilous climb across Thailand''s Mount Kwan, two climbers become trapped thousands of feet above the ground, where vertigo-inducing heights, sheer exposure, and impossible odds turn every moment into a fight for survival.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/fgSm5ylwiXbIHn8UbUXDjk9RRu4.jpg', 'https://image.tmdb.org/t/p/w1280/nGau0KBOaRILSK5MqFcuTfv7GMl.jpg', 7.3, 'Krs0VDIjhmE', '2026-09-01', 222.564, 565, 'tt31192372', 5.7, 1565, 'PG-13', 'Cerita Seru', 'Michael Spierig, Peter Spierig', 'Jonathan Frank, Scott Mann', 'Mark Lane, James Harris, Christian Mercuri, Scott Mann', 'Tea Shop Productions, Capstone Pictures, Flawless Production, Cousin Jones', '[{"name":"Harriet Slater","character":"Jax Hunter"},{"name":"Arsema Thomas","character":"Luce"},{"name":"Tom Brittney","character":"Jon Platt"},{"name":"Virginia Gardner","character":"Shiloh Hunter"},{"name":"สหจักร บุญธนกิจ","character":"Thai Barman"},{"name":"Korakod Yensuk","character":"Large Woman"},{"name":"Jordan Coleman","character":"Real Luce"},{"name":"Maryna Bennett","character":"Female Teenager"},{"name":"Noen Perez","character":"Male Teenager"},{"name":"Nattapon Sukphiam","character":"Thai Climber 1"}]'::jsonb, '17+', 4122),
(1153576, 'Street Fighter', 'Aksi', 120, 'NR', 'In 1993, estranged Street Fighters Ryu and Ken Masters are thrown back into combat when the mysterious Chun-Li recruits them for the next World Warrior Tournament: a brutal clash of fists, fate, and fury. But behind this battle royale lies a deadly conspiracy that forces them to face off against each other and the demons of their past. And if they don''t, it''s GAME OVER!', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/ccxdepKqORLwccbzvO4eAGkN0IC.jpg', 'https://image.tmdb.org/t/p/w1280/zDE9hd1SG9695YncbZGjSf7Z9Jk.jpg', 6.3, 'U6sbm1OaJb8', '2026-10-13', 209.392, 69, 'tt27419420', 6.2, 1231, 'PG-13', 'Aksi, Fantasi', 'Kitao Sakurai', 'Dalan Musson, Gary Dauberman, T.J. Fixman, Kitao Sakurai', 'Mary Parent, Cale Boyter, Jason Momoa, Takayuki Nakayama', 'Capcom, Legendary Pictures', '[{"name":"Andrew Koji","character":"Ryu"},{"name":"Noah Centineo","character":"Ken Masters"},{"name":"Callina Liang","character":"Chun-Li"},{"name":"David Dastmalchian","character":"M. Bison"},{"name":"Mel Jarnson","character":"Cammy"},{"name":"Cody Rhodes","character":"Guile"},{"name":"विद्युत जामवाल","character":"Dhalsim"},{"name":"Olivier Richters","character":"Zangief"},{"name":"Andrew Schulz","character":"Dan Hibiki"},{"name":"50 Cent","character":"Balrog"}]'::jsonb, '13+', 1813),
(1302904, 'Practical Magic 2', 'Percintaan', 130, 'NR', 'The Owens sisters must confront the dark curse that threatens to unravel their family once and for all.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/ogwQOLbCfncjvBhFb5l0OmQH8KC.jpg', 'https://image.tmdb.org/t/p/w1280/oIglj0Jy9duG4LnrRUpH8n001Pk.jpg', 6.9, 'Ho10_4IX1jE', '2026-09-09', 167.705, 221, 'tt32588798', null, null, 'PG-13', 'Percintaan, Fantasi, Komedi', 'Susanne Bier', 'Akiva Goldsman, Georgia Pritchett, Kelly Marcel, Alice Hoffman', 'Denise Di Novi, Sandra Bullock, Nicole Kidman', 'Di Novi Pictures, Warner Bros. Pictures, Blossom Films, Fortis Films', '[{"name":"Sandra Bullock","character":"Sally Owens"},{"name":"Nicole Kidman","character":"Gillian Owens"},{"name":"Joey King","character":"Kylie"},{"name":"Maisie Williams","character":"Antonia"},{"name":"Xolo Maridueña","character":"Gideon"},{"name":"Lee Pace","character":"Ian Wright"},{"name":"Dianne Wiest","character":"Jet"},{"name":"Stockard Channing","character":"Franny"},{"name":"Solly McLeod","character":"Tom Lockland"},{"name":"Ema Cavolli","character":"Maria Owens"}]'::jsonb, '13+', 4946),
(1400837, 'Other Mommy', 'Kengerian', 93, 'NR', 'Young Bela forms a relationship with a sinister entity in her home that looks uncannily like her own mother, drawing her into a terrifying and increasingly dark world.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/fGRNCssTRrhYZxNzykGGCoMsAVq.jpg', 'https://image.tmdb.org/t/p/w1280/ncm7djsVTHQQMX2HEbEVxMUFchG.jpg', 5.9, '-mnTITqqiT0', '2026-10-07', 129.336, 128, 'tt36586020', null, null, 'R', 'Kengerian', 'Rob Savage', 'Josh Malerman, Nathan Elston', 'James Wan', 'Spin a Black Yarn, Blumhouse Atomic Monster', '[{"name":"Jessica Chastain","character":"Mommy / Other Mommy"},{"name":"Jay Duplass","character":"Daddo"},{"name":"Arabella Olivia Clark","character":"Bela"},{"name":"Karen Allen","character":"Grandma Ruth"},{"name":"Arian Moayed","character":"Uncle Frank"},{"name":"Dichen Lachman","character":"Lois Anthony"},{"name":"Sean Kaufman","character":"Kelvin"},{"name":"Adam Silver","character":"Brian"},{"name":"Alec Secăreanu","character":"Ruiss"},{"name":"Millie Wood","character":"Little Girl"}]'::jsonb, 'R', 1421),
(1248832, 'Digger', 'Komedi', 129, 'NR', 'The most powerful man in the world embarks on a frantic mission to prove he is humanity''s savior before the disaster he''s unleashed destroys everything.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/1ATXKrIPJyKNwnJ6lcG088Sa6zi.jpg', 'https://image.tmdb.org/t/p/w1280/b7t3r39Oll5qPxBKzLZ8eHMBD7l.jpg', 7.5, 'job8V254NAE', '2026-09-28', 91.5, 400, 'tt31450459', null, null, null, 'Komedi, Drama', 'Alejandro G. Iñárritu', 'Alejandro G. Iñárritu, Sabina Berman, Jez Butterworth, Alexander Dinelaris', 'Alejandro G. Iñárritu, Tom Cruise, Mary Parent, Michael Sharp', 'Warner Bros. Pictures, Legendary Pictures, Domain Entertainment', '[{"name":"Tom Cruise","character":"Digger Rockwell"},{"name":"Riz Ahmed","character":"Dr. Nirav Ganesh"},{"name":"John Goodman","character":"President Compson"},{"name":"Sandra Hüller","character":"Emma Rockwell"},{"name":"Michael Stuhlbarg","character":"Vice President Eddie"},{"name":"Jesse Plemons","character":"Kenny"},{"name":"Robert John Burke","character":"General Fitzgerald"},{"name":"Emma D''Arcy","character":"Lina"},{"name":"Burn Gorman","character":"Defense Secretary Amos"},{"name":"Sophie Wilde","character":"Hannah"}]'::jsonb, '17+', 885),
(1263337, 'Heart of the Beast', 'Petualangan', 101, 'NR', 'After a harrowing plane crash, Special Forces officer James Belmont and his combat dog, Odin, find themselves stranded deep in the Alaskan wilderness. Together, they are forced into a brutal fight for survival against the elements.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/1ApfSA8JTqeha3GTFEY8syV4auq.jpg', 'https://image.tmdb.org/t/p/w1280/bicMU6xVD5deVyKP2azpyx7xkmH.jpg', 7.4, 'UkMuGKqAux4', '2026-09-19', 91.97, 309, 'tt7526136', 7.5, 542, 'PG-13', 'Petualangan, Cerita Seru', 'David Ayer', 'Cameron Alexander', 'David Ayer, Olivia Hamilton, Marty Bowen, Brad Pitt', 'Paramount Pictures, Wild Chickens Productions, Temple Hill Entertainment, Domain Entertainment', '[{"name":"Brad Pitt","character":"James Belmont"},{"name":"J.K. Simmons","character":"Watkins"},{"name":"Anna Lambe","character":"Amber"},{"name":"Justin Melnick","character":"Military Soldier"},{"name":"Shaun DeZern","character":"Military Soldier"},{"name":"Uber","character":"Odin"},{"name":"Seeka","character":"Odin"},{"name":"Ryker","character":"Odin"},{"name":"Hondo","character":"Odin"}]'::jsonb, '13+', 1176),
(299534, 'Avengers: Endgame', 'Petualangan', 181, 'NR', 'Terdampar di luar angkasa tanpa persediaan makanan dan minuman, Tony Stark berusaha mengirim pesan untuk Pepper Potts dimana persediaan oksigen mulai menipis. Sementara itu para Avengers yang tersisa harus menemukan cara untuk mengembalikan 50% mahluk di seluruh dunia yang telah dilenyapkan oleh Thanos.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/bR8ISy1O9XQxqiy0fQFw2BX72RQ.jpg', 'https://image.tmdb.org/t/p/w1280/7RyHsO4yDXtBv1zUU3mTpHeQ0d5.jpg', 8.2, 'L2NAh3CIdig', '2019-04-24', 88.851, 29027, 'tt4154796', 8.4, 1497908, 'PG-13', 'Petualangan, Cerita Fiksi, Aksi', 'Joe Russo, Anthony Russo', 'Steve Gan, Jim Starlin, Joe Simon, Keith Giffen', 'Kevin Feige', 'Marvel Studios', '[{"name":"Robert Downey Jr.","character":"Tony Stark / Iron Man"},{"name":"Chris Evans","character":"Steve Rogers / Captain America"},{"name":"Mark Ruffalo","character":"Bruce Banner / Hulk"},{"name":"Chris Hemsworth","character":"Thor"},{"name":"Scarlett Johansson","character":"Natasha Romanoff / Black Widow"},{"name":"Jeremy Renner","character":"Clint Barton / Hawkeye"},{"name":"Josh Brolin","character":"Thanos"},{"name":"Don Cheadle","character":"James Rhodes / War Machine"},{"name":"Paul Rudd","character":"Scott Lang / Ant-Man"},{"name":"Benedict Cumberbatch","character":"Doctor Strange"}]'::jsonb, '13+', 1178),
(1255833, 'Whalefall', 'Cerita Seru', 106, 'NR', 'Following the death of his father, Jay Gardiner goes diving off the central Coast of California in search of his remains, but is swallowed by a massive sperm whale. While trapped inside its belly with only one hour of oxygen left, Jay comes to realize that the hard-earned lessons his father imparted may be the key to his escape.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/vjTYUTgh9nO88i6HZ4YPRhiFL05.jpg', 'https://image.tmdb.org/t/p/w1280/shW2jHkQLZVv4Fko2rJDqTGU0gx.jpg', 6.9, 'Dw-5ZGapGTQ', '2026-10-14', 100.83, 40, 'tt28535715', null, null, null, 'Cerita Seru, Drama, Kengerian', 'Brian Duffield', 'Brian Duffield, Daniel Kraus', 'Brian Grazer, Ron Howard, Allan Mandelbaum, Brian Duffield', 'Imagine Entertainment, 20th Century Studios, Jurassic Party', '[{"name":"Austin Abrams","character":"Jay Gardiner"},{"name":"Josh Brolin","character":"Mitt Gardiner"},{"name":"Elisabeth Shue","character":"Zara Gardiner"},{"name":"John Ortiz","character":"Hewey"},{"name":"Jane Levy","character":"Eva Gardiner"},{"name":"Emily Rudd","character":"Nan Gardiner"},{"name":"Kamy D. Bruder","character":"Whale Watcher Man"},{"name":"Mark Meloro Jr.","character":"Whale Watcher Man"},{"name":"Sam Franich","character":"Jay at 10"},{"name":"Nicholas Gould","character":"US Coast Guard Petty Officer Third Class Whaley"}]'::jsonb, '13+', 630),
(1234139, 'ஜெயிலர் 2', 'Aksi', 163, 'NR', 'When a dangerous syndicate expands its reach to threaten his family''s peace, retired jailer Tiger Muthuvel Pandian goes undercover as a driver. Operating from the shadows, he takes on ruthless new enemies to protect his home.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/upwdEyhhYZ7pT2hD535fr2MGfpx.jpg', 'https://image.tmdb.org/t/p/w1280/zpHTOdRl7GEPqFsDGqsN6Hi9Ylt.jpg', 7.8, null, '2026-10-14', 85.691, 6, 'tt33318732', null, null, null, 'Aksi, Komedi', 'நெல்சன் திலீப்குமார்', 'நெல்சன் திலீப்குமார்', 'Kalanithi Maran', 'Sun Pictures', '[{"name":"ரஜினிகாந்த்","character":"Muthuvel ''Tiger'' Pandian"},{"name":"S. J. Suryah","character":"Bodhi Kalpak"},{"name":"Suraj Venjaramoodu","character":"Dileep"},{"name":"Ramya Krishnan","character":"Vijayalakshmi ''Viji'' Pandian"},{"name":"Vidya Balan","character":"Kantha Kalpak"},{"name":"Namo Narayanan","character":"Moorthi"},{"name":"யோகி பாபு","character":"Vimal"},{"name":"Mirnaa","character":"Swetha Pandian"},{"name":"Rithvik","character":"Rithvik ''Rithu'' Pandian"},{"name":"Hakeem Shajahan","character":"Sharva Kalpak"}]'::jsonb, '21+', null),
(1283515, 'Verity', 'Misteri', 114, 'NR', 'Lowen Ashleigh, hired to ghostwrite for best-selling author Verity Crawford, uncovers Verity''s autobiographical notes, and becomes involved in what may prove to be a lethal conspiracy.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/zPHfsaiMZT1HNz1ZS55iyLKZkFG.jpg', 'https://image.tmdb.org/t/p/w1280/3BoHXmGAfC2qO4wnCpMYV0BzpHD.jpg', 6.3, 'xdPMKhjMSFs', '2026-09-30', 78.166, 217, 'tt32261958', null, null, 'R', 'Misteri, Cerita Seru', 'Michael Showalter', 'Nick Antosca, Colleen Hoover', 'Alex Hedlund, Nick Antosca, Michael Showalter, Jordana Mollick', 'Eat the Cat, Semi-Formal Productions, Somewhere Pictures, Shiny Penny Productions', '[{"name":"Anne Hathaway","character":"Verity Crawford"},{"name":"Dakota Johnson","character":"Lowen Ashleigh"},{"name":"Josh Hartnett","character":"Jeremy Crawford"},{"name":"Brady Wagner","character":"Crew Crawford"},{"name":"Ismael Cruz Cordova","character":"Corey"},{"name":"Ирина Дворовенко","character":"Anna"},{"name":"Sienna Kulovitz","character":"Harper Crawford"},{"name":"K.K. Moggie","character":"Amanda Thomas"},{"name":"Tom Galantich","character":"Barron Stephens"},{"name":"Lou Martini Jr.","character":"Limo Driver"}]'::jsonb, '17+', 1391),
(1281331, 'The Social Reckoning', 'Drama', 113, 'NR', 'Frances Haugen, a young Facebook engineer, enlists the help of Jeff Horwitz, a Wall Street Journal reporter, to go on a dangerous journey that ends up blowing the whistle on the social network''s most guarded secrets.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/7jK6NuxVg1XuEV7UdNa6KO03IgZ.jpg', 'https://image.tmdb.org/t/p/w1280/wXTaGcqX3jvdXSKCJAkl5jZyrKp.jpg', 7, 'R8ANzYpaZaY', '2026-10-07', 58.947, 109, 'tt37510326', null, null, null, 'Drama, Cerita Seru', 'Aaron Sorkin', 'Aaron Sorkin', 'Aaron Sorkin, Todd Black, Peter Rice, Stuart M. Besser', 'Columbia Pictures, Alcon Entertainment, TSG Entertainment', '[{"name":"Mikey Madison","character":"Frances Haugen"},{"name":"Jeremy Allen White","character":"Jeff Horwitz"},{"name":"Jeremy Strong","character":"Mark Zuckerberg"},{"name":"Betty Gilpin","character":"Kris"},{"name":"Bill Burr","character":"Charlie Garrigan"},{"name":"Wunmi Mosaku","character":"Raya"},{"name":"Billy Magnussen","character":"Teddy Marks"},{"name":"Gbenga Akinnagbe","character":"Andy"},{"name":"Anna Lambe","character":"Morgan"},{"name":"Aidan Laprete","character":"Zach"}]'::jsonb, 'R', 724),
(1465063, 'Forgotten Island', 'Animasi', 109, 'NR', 'While celebrating their last night together, high school graduates and best friends Jo and Raissa stumble upon a mysterious portal that transports them to the fantastical island of Nakali. When they discover that the memories of their entire friendship are the price for returning home, Jo and Raissa must race to find a way to leave the island before they forget each other forever.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/myd1K3gefdNAWFsGNRDdMeiK9Qg.jpg', 'https://image.tmdb.org/t/p/w1280/cNICUho5uiAGkfCAQq1ihyaMla4.jpg', 7.9, 'PhgY8cOJiQA', '2026-09-10', 65.945, 77, 'tt36583977', 7.7, 1331, 'PG', 'Animasi, Petualangan, Fantasi, Komedi, Keluarga', 'Januel Mercado, Joel Crawford', 'Joel Crawford, Januel Mercado', 'Mark Swift', 'DreamWorks Animation', '[{"name":"H.E.R.","character":"Jo (voice)"},{"name":"Liza Soberano","character":"Raissa (voice)"},{"name":"Dave Franco","character":"Raww (voice)"},{"name":"Jenny Slate","character":"Batiba (voice)"},{"name":"Manny Jacinto","character":"Bungi (voice)"},{"name":"Lea Salonga","character":"Manang (voice)"},{"name":"Dolly de Leon","character":"Lola Fatima (voice)"},{"name":"Jo Koy","character":"Datu (voice)"},{"name":"Ronny Chieng","character":"King Truffle Wuffle (voice)"},{"name":"Kevin McCann","character":"Prince Mermahn (voice)"}]'::jsonb, '13+', null),
(1400940, 'Clayface', 'Kengerian', 109, 'NR', 'Matt Hagen''s meteoric rise from Gotham street kid to Hollywood leading man is tragically cut short when a local crime boss''s actions leave him horribly disfigured. Abandoned by his team and with nothing left, Matt seeks out a cutting edge treatment that miraculously returns him to his former self… but also unexpectedly affects his grip on reality, spiraling him down a destructive path of all-consuming revenge.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/5jCpQnWPikggmQZoDp1eAi6BI6w.jpg', 'https://image.tmdb.org/t/p/w1280/kVtOcoUJ68chBD2tmERkdWz7lK5.jpg', 8.2, 'f7jlCqdtwdM', '2026-10-21', 54.094, 8, 'tt34890576', null, null, null, 'Kengerian, Cerita Seru, Cerita Fiksi', 'James Watkins', 'Bill Finger, Bob Kane, Mike Flanagan, حسین امینی', 'James Gunn, Peter Safran, Matt Reeves, Lynn Harris', 'DC Studios, Domain Entertainment, 6th & Idaho Motion Picture Company, Troll Court Entertainment', '[{"name":"Tom Rhys Harries","character":"Matt Hagen / Clayface"},{"name":"Naomi Ackie","character":"Caitlyn Corr"},{"name":"Eddie Marsan","character":""},{"name":"Max Minghella","character":"John Borrelli"},{"name":"David Dencik","character":""},{"name":"Francesca Corney","character":""},{"name":"Ruby Sear","character":"Theresa"},{"name":"Wil Coban","character":"Bones"},{"name":"Joshua James","character":"Corey Bowery"},{"name":"Jake Curran","character":"Patches"}]'::jsonb, '17+', null),
(1447853, 'Oasis: Don''t Look Back in Anger', 'Dokumenter', 123, 'NR', 'Experience the meteoric rise of Oasis through rare footage and untold stories as the band reunites for Oasis Live ''25, chronicling their journey from Manchester streets to global rock stardom.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/5XoHhKZ1IROW6f5UlRpADHnTL2l.jpg', 'https://image.tmdb.org/t/p/w1280/7Ud7QIJo21odjCaev6V4md9sK16.jpg', 7.4, 'X9sIYLtgc_s', '2026-09-09', 36.358, 34, 'tt36150957', 8.6, 801, 'R', 'Dokumenter, Musik', 'Dylan Southern, Will Lovelace', 'Steven Knight', 'Sam Bridger, Guy Heeley', 'Magna Studios, Sony Music Vision, Sony Music Entertainment UK', '[{"name":"Liam Gallagher","character":"Self"},{"name":"Noel Gallagher","character":"Self"},{"name":"Paul Arthurs","character":"Self"},{"name":"Gem Archer","character":"Self"},{"name":"Andy Bell","character":"Self"},{"name":"Joey Waronker","character":"Self"},{"name":"Christian Madden","character":"Self"},{"name":"Anaïs Gallagher","character":"Self"},{"name":"Molly Elson","character":"Self"},{"name":"Gary ''Mani'' Mounfield","character":"Self"}]'::jsonb, '13+', null),
(1594914, 'Lucky Strike', 'Aksi', 102, 'NR', 'A wounded American soldier fights to survive behind enemy lines during WWII''s Battle of the Bulge against the Germans, relying on his instinct, spy craft and a hand-radio to evade capture and find his way back to his unit.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/kzRAd7mj39ZY3FGNrDdZjqx56tn.jpg', 'https://image.tmdb.org/t/p/w1280/uujYvxE9s6KY4SbBZ0ZFN3oBJhW.jpg', 6.6, 'vtEnjikCXyA', '2026-06-26', 32.853, 57, 'tt19035928', null, null, null, 'Aksi, Kejahatan', 'Rod Lurie', 'Rod Lurie, Marc Frydman', 'Marc Frydman, Yariv Lerner, Les Weldon, Jonathan Yunger', 'Perfection Hunter Productions, Millennium Media, BondIt Media Capital', '[{"name":"Scott Eastwood","character":"Castle"},{"name":"Colin Hanks","character":"Colonel Neale"},{"name":"Aunjanue Ellis-Taylor","character":"Mrs. Caldwell"},{"name":"Taylor John Smith","character":"Bellingham"},{"name":"Lorne MacFadyen","character":"Major Barrett"},{"name":"Atanas Srebrev","character":"General Lauer"},{"name":"Alfie Stewart","character":"Burt Miller"},{"name":"Jonathan Yunger","character":"Cash"},{"name":"Timothy Blore","character":"Wilhelm"},{"name":"Laurent Maurel","character":"Georges Marsaud"}]'::jsonb, '13+', null),
(1400499, '近畿地方のある場所について', 'Kengerian', 103, 'NR', 'After an editor of an occult magazine suddenly vanishes, his friend Chihiro and his co-worker Yusei set out to discover the reason behind his disappearance.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/4JRRsGFmk1rkifiHErwP2ML96QV.jpg', 'https://image.tmdb.org/t/p/w1280/e0vwcf5R1yU2Uz2mTO4KbCxL5tT.jpg', 6.4, null, '2025-08-08', 26.73, 29, 'tt34969899', 6.3, 836, null, 'Kengerian, Misteri', '白石晃士', '背筋, 白石晃士, 大石哲也', '櫛山慶, 伊藤裕史', 'Warner Bros. Japan, AX-ON, Nippon Television Network Corporation, Yomiuri Telecasting Corporation', '[{"name":"菅野美穂","character":"Seno Chihiro"},{"name":"赤楚衛二","character":"Ozawa Yusei"},{"name":"夙川アトム","character":"Sayama Takeshi"},{"name":"佐藤京","character":"Nagano Haruka"},{"name":"のせりん","character":"Meguro Yuji"},{"name":"木村圭作","character":"Tanemura Eisaku"},{"name":"山田暖絆","character":"Takami Ryo"},{"name":"菅野莉央","character":"Morota Miya"},{"name":"福井裕子","character":"Omori Hideko"},{"name":"久保山智夏","character":"Sasayama Chie"}]'::jsonb, null, null),
(1755291, 'NAZA', 'Dokumenter', 77, 'NR', 'Filmed at night from Tel Aviv rooftops, this investigative documentary examines the civilian casualties of Israel''s military operations in Gaza and the systems behind targeted killings of Palestinians.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/bYfN1EKVyj2O7KXwuWDDCc47B5T.jpg', 'https://image.tmdb.org/t/p/w1280/7EzH0dlEN9OZWWBXBWwT5PbMNUz.jpg', 8.2, '40KW6knYMo4', '2026-09-25', 16.742, 91, 'tt44766123', 7.9, 3173, null, 'Dokumenter, Kejahatan', 'Yuval Abraham, רחל שור', null, 'James Wilson, Lindsay Poulton, Harry Davies', 'The Guardian, JW Films, Placeholder Films, Unseen Hand', '[{"name":"Yuval Abraham","character":"Self"}]'::jsonb, '17+', null),
(1269325, 'दृश्यम: आखिरी हिस्सा', 'Cerita Seru', 148, 'NR', 'Years after outsmarting the police, Vijay Salgaonkar''s past resurfaces when a new evidence threatens to expose his secret. As the investigation reopens, he must outwit the system once again to save his family.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/7T62GSduOWDMB0gGDBs9pmtLTSB.jpg', 'https://image.tmdb.org/t/p/w1280/nq73eRdEooripf3k0XHLtX14zyC.jpg', 7.7, 'MFQFxsDWbA8', '2026-10-02', 16.801, 9, 'tt27050858', null, null, null, 'Cerita Seru, Drama, Misteri, Kejahatan', 'Abhishek Pathak', 'Abhishek Pathak, Aamil Keyan Khan, Parveez Shaikh', 'Kumar Mangat Pathak, Alok Jain, Ajit Andhare, Abhishek Pathak', 'Viacom18 Studios, Panorama Studios, Pen Studios', '[{"name":"Ajay Devgan","character":"Vijay Salgaonkar"},{"name":"Jaideep Ahlawat","character":"SP Rajveer Singh Tomar"},{"name":"Tabu","character":"Meera Deshmukh"},{"name":"శ్రియా శరణ్","character":"Nandini Salgaonkar"},{"name":"Rajat Kapoor","character":"Mahesh Deshmukh"},{"name":"ప్రకాష్ రాజ్","character":"Public Prosecutor Indrajith Shetty"},{"name":"Ishita Dutta","character":"Anju Salgaonkar"},{"name":"Mrunal Jadhav","character":"Anu Salgaonkar"},{"name":"Kamlesh Sawant","character":"Laxmikant Gaitonde"},{"name":"Saurabh Shukla","character":"Murad Ali"}]'::jsonb, 'NR', null),
(1545621, '名探偵コナン ハイウェイの堕天使', 'Aksi', 109, 'NR', 'When a string of deadly highway incidents begin, Conan Edogawa''s investigations point towards an orchestrated plot rather than mere accidents. As he uncovers a conspiracy involving hidden identities and advanced technology, the case escalates into a high-speed race against time to stop a calculating mastermind before more lives are lost.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/l2kfiNoRi6ofM5pSjr1rCloOfpx.jpg', 'https://image.tmdb.org/t/p/w1280/zT5S4GNs8Eu2gIkGORoN6yC1uE2.jpg', 7.4, '-OmZGxr23hY', '2026-04-10', 16.334, 22, 'tt39123115', 6.2, 594, null, 'Aksi, Animasi, Misteri, Kejahatan', '蓮井隆弘', '大倉崇裕', '近藤秀峰, 吉田剛志, 岡田悠平', 'TMS Entertainment, TOHO, Nippon Television Network Corporation, Shogakukan', '[{"name":"高山みなみ","character":"Conan Edogawa (voice)"},{"name":"Wakana Yamazaki","character":"Ran Mouri (voice)"},{"name":"小山力也","character":"Kogoro Mouri (voice)"},{"name":"林原めぐみ","character":"Ai Haibara (voice)"},{"name":"沢城みゆき","character":"Chihaya Hagiwara (voice)"},{"name":"三木眞一郎","character":"Kenji Hagiwara (voice)"},{"name":"神奈延年","character":"Jinpei Matsuda (voice)"},{"name":"横浜流星","character":"Kazuaki Omae (voice)"},{"name":"畑芽育","character":"Minato Tateoki (voice)"},{"name":"大塚明夫","character":"Jyuugo Yokomizo (voice)"}]'::jsonb, '13+', null),
(1706702, 'Daniel and the Fiery Furnace', 'Drama', 108, 'NR', 'During the Jewish exile to Babylon, Daniel and his friends face trials as Babylon''s armies conquer Jerusalem. Under King Nebuchadnezzar, they gain royal favor but make enemies. Their faith is tested at the fiery furnace.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/leE7dixdbzHXUBJdQgW1fFHz0ru.jpg', 'https://image.tmdb.org/t/p/w1280/4EoROOIIvrOLarSmM3EcCVxtaDl.jpg', 6.8, 'FYm_sWSw6Eo', '2026-09-18', 6.98, 5, 'tt37542993', null, null, null, 'Drama', 'Matthew Kooman, Daniel Kooman', 'Matthew Kooman, Daniel Kooman', 'Daniel Kooman, Matthew Kooman, Mena Massoud, Travis Mann', 'Pinnacle Peak Pictures, Unveil Studios, EKKL', '[{"name":"Mena Massoud","character":"Daniel"},{"name":"Elijah Alexander","character":"King Nebuchadnezzar"},{"name":"Sophia Decaro","character":"Susanna"},{"name":"Vladimir Angelove","character":"Hilkiah"},{"name":"Zaki Ali","character":"Azariah"},{"name":"Oncel Camci","character":"Hananiah (Son of Azzur)"},{"name":"Sunjay Midda","character":"Hananiah"},{"name":"Edward J. Marsh","character":"Yuval"},{"name":"Adam Lahraoui","character":"Mishael"},{"name":"Jazz Lintott","character":"Zaid"}]'::jsonb, '13+', null),
(1394740, '타짜: 벨제붑의 노래', 'Kejahatan', 130, 'NR', 'Jang Taeyoung, who believes he has everything after building a successful online casino business, loses it all to his former best friend and namesake, Park Taeyoung. The two reunite on the international poker circuit for a high-stakes battle of revenge.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/ueigb5zra1tj6FTK9yhh2P33P9B.jpg', 'https://image.tmdb.org/t/p/w1280/w5OX3u2SpMVRU0sol0mtIaf4LSI.jpg', 7, 'gDgTGFltqBw', '2026-09-23', 6.721, 3, 'tt39233100', null, null, null, 'Kejahatan, Drama', '최국희', '최국희, 김현', '조혜정, 이진욱', 'Sidus, MCMC', '[{"name":"변요한","character":"Jang Taeyoung"},{"name":"노재원","character":"Park Taeyoung"},{"name":"三吉彩花","character":"Kaneko"},{"name":"조우진","character":"Kwak Dongwook"},{"name":"윤경호","character":"Cho Joonghwan"},{"name":"스윙스","character":"Abraham"},{"name":"스테파니 리","character":"Linda Park"},{"name":"김민호","character":"Hippo"},{"name":"임세미","character":"Jang Taehee"},{"name":"伊原剛志","character":"Sasaki"}]'::jsonb, '17+', null),
(730251, 'HAPPYEND', 'Drama', 113, 'NR', 'In a near-future Japanese city bracing for a devastating earthquake, a group of teenage friends navigate personal struggles and fractured bonds amid rising tension.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/uaSmMj7kBP6elOp4CnpTsrF2AyL.jpg', 'https://image.tmdb.org/t/p/w1280/shWIpYYqbgpUUefpPj1VrYbPonE.jpg', 6.8, '8gWKm5eFo44', '2024-10-04', 6.511, 46, 'tt29279903', 6.8, 2304, null, 'Drama, Cerita Fiksi', '空音央', '空音央', 'Albert Tholen, Aiko Masubuchi, Alex C. Lo, 陳哲藝', 'Cineric Creative, Cinema Inutile, Zakkubalan, K-Garage', '[{"name":"栗原颯人","character":"Yūta"},{"name":"Yukito Hidaka","character":"Kō"},{"name":"林裕太","character":"Ata-chan"},{"name":"Shina Peng","character":"Ming"},{"name":"Arazi","character":"Tomu"},{"name":"祷キララ","character":"Fumi"},{"name":"中島歩","character":"Okada"},{"name":"矢作優","character":"Taira"},{"name":"PUSHIM","character":"Fukuko"},{"name":"渡辺真起子","character":"Yoko"}]'::jsonb, '13+', null),
(961214, '부활남: 더 레드', 'Aksi', 102, 'NR', 'Despite unwavering support from his best friend Young-ha and the unwavering support of his younger sister Ye-rin, job seeker Seok Hwan just can''t seem to land a job, repeatedly failing interviews. One night, after yet another disastrous interview, he returns home only to be attacked by a group of strangers and killed. But 72 hours after his death, Seok Hwan suddenly opens his eyes as if nothing happened. He soon discovers that he possesses a special ability: no matter how many times he dies, he comes back to life. But there''s little time to process his extraordinary new power before a mysterious figure known as Black, who has discovered Hwan''s existence, begins hunting him down. Yet with each resurrection, Seok Hwan grows stronger, unleashing powers beyond anything he could have imagined!', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/nLsyRK3SmtdIftozpCd8sGQMRGD.jpg', 'https://image.tmdb.org/t/p/w1280/kiDd05NykJBIoEvJPSG5SOd7qc6.jpg', 5, null, '2026-09-30', 6.105, 1, 'tt29452783', null, null, null, 'Aksi, Fantasi', '백종열', '강선주, 박성신', '임승용', 'Yong Film, Superfiction, YLAB, STUDIO NU:NGIL', '[{"name":"구교환","character":"Seok Hwan / Red"},{"name":"신승호","character":"Black"},{"name":"강기영","character":"Young-ha"},{"name":"김시아","character":"Cha Ye-rin"},{"name":"김성령","character":"Mi-joo"},{"name":"김인우","character":"Cha Hyeong-seok"},{"name":"김지율","character":""},{"name":"Justin Harvey","character":""},{"name":"김승범","character":"Bully 1"},{"name":"황근형","character":"Bully 4"}]'::jsonb, '17+', null),
(1103857, 'Juliet & Romeo', 'Drama', 122, 'NR', 'Set at the dawn of the fourteenth century, a revisionist adaptation of history''s most celebrated star-crossed lovers rejects classical iambic pentameter in favor of a contemporary pop music score, charting their efforts to alter the course of their tragic destiny and expose a political truth crucial to the future of the Empire.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/4spOdjLgRAbIYO7mu22DQ2iInz7.jpg', 'https://image.tmdb.org/t/p/w1280/5vkYsIN0BpDlATvHCjufG5SimkU.jpg', 6, 'HLOfwe_0YsA', '2025-05-09', 5.317, 14, 'tt26597666', 3.9, 696, 'PG-13', 'Drama, Percintaan, Musik', 'Timothy Scott Bogart', 'Timothy Scott Bogart', 'Andrea Iervolino, Timothy Scott Bogart, Jessica Martins, Brad Bogart', 'Iervolino & Lady Bacardi Entertainment, Voltage Pictures, Hero Entertainment Partners', '[{"name":"Clara Rugaard","character":"Juliet Capulet"},{"name":"Jamie Ward","character":"Romeo Montague"},{"name":"Jason Isaacs","character":"Lord Montague"},{"name":"Dan Fogler","character":"The Apothecary"},{"name":"Rebel Wilson","character":"Lady Capulet"},{"name":"Rupert Everett","character":"Lord Capulet"},{"name":"Derek Jacobi","character":"The Friar"},{"name":"Lidia Vitale","character":"Lady Montague"},{"name":"Ferdia Walsh-Peelo","character":"Tybalt"},{"name":"Nicholas Podany","character":"Mercutio"}]'::jsonb, '13+', null),
(1552493, 'Khadam', 'Drama', 118, 'NR', 'Forced to inherit her family''s legacy, a mother races against time to save her daughter from a dark entity gradually taking control of her life.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/elwBj5UKnGNSzLIQLNbGgsW5g3J.jpg', 'https://image.tmdb.org/t/p/w1280/3wZmVqOrmHOB8j83LmpAbyNwWnE.jpg', 6.7, 'T8OpDWG9rUs', '2026-06-11', 5.757, 6, 'tt38267329', null, null, null, 'Drama, Kengerian, Cerita Seru', 'Shamyl Othman', 'Fariza Azlina', 'Ayu Amirrol', 'Komet Productions, Magma Entertainment, Applause Entertainment, Sil-Metropole Organisation', '[{"name":"Aghniny Haque","character":"Melor"},{"name":"Remy Ishak","character":"Awang"},{"name":"Siti Khadijah Halim","character":"Manis"},{"name":"Zarra Zaff","character":"Puteh"},{"name":"Karl El","character":"Hitam"},{"name":"June Lojong","character":"Nek Mak"}]'::jsonb, '17+', null),
(1388805, 'LINKIN PARK: UNSHATTER', 'Musik', 108, 'NR', 'After a seven-year hiatus following the devastating loss of their beloved bandmate Chester Bennington, LINKIN PARK''S remaining members struggled to find their way forward. Their shared history and enduring friendship, combined with the fresh perspective of two new band members Emily Armstrong and Colin Brittain spark a renewed creative energy that leads them on a transformative journey of artistic reinvention. Following the band from intimate 2022 studio sessions through their explosive FROM ZERO album release and concert in São Paulo, this documentary weaves together rare vault footage, electrifying performances from sold-out shows, and candid interviews with band members and fans—capturing the raw, honest story of what it means to start over.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/kHNrz7DBVPrtyMhJxmBm2poS2l9.jpg', 'https://image.tmdb.org/t/p/w1280/uL1HCc4wmcFcSr1zS3kXX3CNUeE.jpg', 9.3, 'K9Lpxc7bVTM', '2026-09-30', 3.945, 12, 'tt43442522', 8.6, 875, null, 'Musik, Dokumenter', 'Joe Hahn', 'Igor Kovalik', 'Joe Hahn, Igor Kovalik, WL Boyd', 'CJ 4DPLEX, CJ 4DPLEX America, hungryman', '[{"name":"Mike Shinoda","character":"Self"},{"name":"Emily Armstrong","character":"Self"},{"name":"Joe Hahn","character":"Self"},{"name":"Dave Farrell","character":"Self"},{"name":"Colin Brittain","character":"Self"},{"name":"Alex Feder","character":"Self"},{"name":"Brad Delson","character":"Self"},{"name":"Mark Hoppus","character":"Self"}]'::jsonb, 'SU', null),
(1319525, 'จีบซ้ำซ้ำ เฮนรี่จำไม่ได้', 'Komedi', 115, 'NR', 'Lucy, a woman who''s living her first date on repeat with Henry, a good-natured, animal-loving guy with a bizarre condition: every time he wakes up, he can''t remember anything from the day before.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/qlw9WtySGW6AUdbkwgWUltvIAf3.jpg', 'https://image.tmdb.org/t/p/w1280/luQZKJZmp92kiwUZeXOpp0SrinL.jpg', 6, 'q1xP2WQyn-E', '2026-09-17', 3.854, 2, 'tt37846333', null, null, null, 'Komedi, Percintaan', 'เมษ ธราธร', 'Benjamaporn Srabua, เมษ ธราธร, ทศพล ทิพย์ทินกร', 'วรรณฤดี พงษ์สิทธิ์ศักดิ์, เมษ ธราธร', 'GDH 559, Sony Pictures International Productions', '[{"name":"ณเดชน์ คูกิมิยะ","character":"Henry"},{"name":"มินนี่","character":"Lucy"},{"name":"เกียรติ กิจเจริญ","character":"Dad"},{"name":"เบิ้ล ปทุมราช","character":"Kanoon"},{"name":"ทิพากร ไชยประสิทธิ์","character":"Auntie Su"}]'::jsonb, null, null),
(1257942, '魔方小姐', 'Komedi', 107, 'NR', 'At the age of seventy, a fiercely non-conformist grandmother partners with a lethargic, underachieving young prodigy to navigate the highly competitive and eccentric subculture of speedcubing, defying familial skepticism and generational expectations.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/qvTiG4LSu6wFCfXjg2KTiqHeQBF.jpg', 'https://image.tmdb.org/t/p/w1280/bLxfaYqA9YlVuXbU9eK1E2u3MLI.jpg', 6.2, 'V9ctZj2mEC0', '2026-06-19', 3.166, 5, 'tt36130077', null, null, null, 'Komedi, Drama', 'Bai Xue', 'Yizhou Xu, Bai Xue, Yan Sun', 'Michelle Yeoh, 刘明轶, 高山', 'Media Asia Films, Shanghai Maoyan Film 上海猫眼影业, 梦将军（上海）影业有限公司', '[{"name":"Michelle Yeoh","character":"Zhao Yanhong"},{"name":"刘昊然","character":"Wu Youwei"},{"name":"萨日娜","character":"Shuzhen"},{"name":"白客","character":"Dong Dawei"},{"name":"韓童生","character":"Old Wan"},{"name":"齐溪","character":"Man Ting"},{"name":"刘旸","character":"Mr. Hu"},{"name":"田雨","character":"Headmaster Zheng"},{"name":"黄尧","character":"Zhao Yanhong (Youth)"},{"name":"陈哈琳","character":"Zhao Yanhong (Child)"}]'::jsonb, '13+', null),
(1215889, 'दायरा', 'Kejahatan', 141, 'NR', 'Raman, who has had a shady record with staged encounters and police brutality, finds himself cornered as Ajooni challenges him on every step.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/qQ6ORv3AfsV6m1ERL8Muk5jKpbu.jpg', 'https://image.tmdb.org/t/p/w1280/rbwmf04kpX1o3zbbOS6Y7woF2Ku.jpg', null, null, '2026-09-18', 3.58, 0, 'tt32634611', null, null, null, 'Kejahatan, Drama', 'Meghna Gulzar', 'Meghna Gulzar, Yash Keswani, Sima Agarwal', 'Vineet Jain, Jayantilal Gada, Dhaval Jayantilal Gada', 'Junglee Pictures, Pen Studios', '[{"name":"करीना कपूर खान","character":"DCP Ajooni Kohli"},{"name":"പൃഥ്വിരാജ് സുകുമാരൻ","character":"DCP Raman Kumar"},{"name":"Pragati Mishra","character":"Ragini"},{"name":"Prammod Sanghi","character":"Abhinandan Basu"},{"name":"Sumali Khaniwale","character":"NGO Head"},{"name":"Upendra Chauhan","character":"Inspector Vishal Mishra"},{"name":"Jitendra Joshi","character":"Inspector Karad"},{"name":"Kanwaljit Singh","character":"Judge Kohli"},{"name":"Kshitee Jog","character":"Parvati"},{"name":"Trupti Khamkar","character":"SI Jyoti"}]'::jsonb, null, null),
(1148365, 'Matchbox the Movie', 'Aksi', 127, 'NR', 'Ketika sekelompok mantan teman masa kecil bertemu kembali, reuni mereka menjadi kacau saat tak sengaja menemukan konspirasi internasional yang berbahaya dan kini mereka harus menyelamatkan dunia.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/lFKA4GMz36dImEy3DQPdPF7G4V9.jpg', 'https://image.tmdb.org/t/p/w1280/jdJsnhHfkIi3J7jwfiCFT4gXNx5.jpg', 7.8, '7xfqITrMDcI', '2026-10-05', 366.191, 385, 'tt28498219', null, null, 'PG-13', 'Aksi, Komedi, Petualangan', 'Sam Hargrave', 'David Coggeshall', 'David Ellison, Dana Goldberg, Don Granger, Robbie Brenner', 'Mattel Studios, Skydance Media', '[{"name":"John Cena","character":"Sean"},{"name":"Jessica Biel","character":"Aimee"},{"name":"Arturo Castro","character":"Ted"},{"name":"Sam Richardson","character":"Crosby"},{"name":"Teyonah Parris","character":"Charmaine"},{"name":"Danai Gurira","character":"Helen"},{"name":"گلشیفته فراهانی","character":"Robbie"},{"name":"Corey Stoll","character":"Mosier"},{"name":"Daniel Bernhardt","character":"Falko"},{"name":"Randeep Hooda","character":"Mustafa"}]'::jsonb, '17+', 8904),
(1368337, 'The Odyssey', 'Petualangan', 173, 'NR', 'Odysseus, raja legendaris Yunani dari Ithaca, memulai perjalanan panjang dan berbahaya untuk pulang setelah Perang Troya, yang mengisahkan perjumpaannya dengan makhluk-makhluk mitologis seperti Cyclops Polyphemus, para Siren, dan penyihir-dewi Circe.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/5rhTDKUhPYvpdQIijFIs5VoWsON.jpg', 'https://image.tmdb.org/t/p/w1280/nVBzWBqHTB3XD0iqWiJLfKLo5fq.jpg', 8, 'AyIZ9tiiN8I', '2026-07-15', 345.136, 4158, 'tt33764258', 8.4, 477953, 'R', 'Petualangan, Aksi, Fantasi', 'Christopher Nolan', 'Christopher Nolan', 'Christopher Nolan, Emma Thomas', 'Universal Pictures, Syncopy', '[{"name":"Matt Damon","character":"Odysseus"},{"name":"Tom Holland","character":"Telemachus"},{"name":"Anne Hathaway","character":"Penelope"},{"name":"Robert Pattinson","character":"Antinous"},{"name":"Himesh Patel","character":"Eurylochus"},{"name":"Charlize Theron","character":"Calypso"},{"name":"John Leguizamo","character":"Eumaeus"},{"name":"Travis Scott","character":"Bard"},{"name":"Corey Hawkins","character":"Polybus"},{"name":"Jarreth J. Merz","character":"Leodes"}]'::jsonb, '13+', 1563),
(1236045, 'Animals', 'Cerita Seru', 109, 'NR', 'Saat putra mereka diculik, seorang kandidat wali kota LA dan istrinya kalang kabut mengumpulkan tebusan sambil membuat keputusan yang bisa menghancurkan hidup mereka.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/iISM36voS1E8gX9BM0DVK0kgi3E.jpg', 'https://image.tmdb.org/t/p/w1280/tzoarEu7TsG959upiELyYPm5kO9.jpg', 7.1, 'ZkN2M4ODdys', '2026-10-09', 242.509, 453, 'tt31049299', null, null, 'R', 'Cerita Seru, Drama', 'Ben Affleck', 'Billy Ray, Ben Affleck, Connor O. McIntyre', 'Ben Affleck, Matt Damon, Dani Bernfeld, Brad Weston', 'Artists Equity, Makeready, Fifth Season', '[{"name":"Ben Affleck","character":"Mark Kimball"},{"name":"Kerry Washington","character":"Abigail Kimball"},{"name":"Gillian Anderson","character":"Dayle Burton"},{"name":"Steven Yeun","character":"Sam Allison"},{"name":"Adriana Paz","character":"Cecilia Trujillo"},{"name":"Luis Gerardo Méndez","character":"Ramon"},{"name":"Christopher Woodley","character":"Denny Kimball"},{"name":"Jacob Estrada","character":"Hector"},{"name":"Ray Fisher","character":"Ron Sperling"},{"name":"Taylor Cooper","character":"Hannah"}]'::jsonb, 'R', 9850),
(1228834, 'The Fix', 'Aksi', 142, 'NR', 'Disillusioned by the end of the war in Afghanistan, a group of disgraced, war-torn ex-CIA operatives set out to Tehran to take down a life-changing score.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/jlP8XDjZN89GrpM3je5Uf8Grqx8.jpg', 'https://image.tmdb.org/t/p/w1280/dJTWIecL2vxsCRl5G0lRhPsfrhc.jpg', 6.7, 'l5Luvr9TRRc', '2026-09-10', 230.119, 65, 'tt9601292', null, null, null, 'Aksi, Cerita Seru', 'Guy Moshe', 'Mark Bacci, Guy Moshe', 'Wendy Hinton Sweetmore, Jai Khanna, Matthew G. Zamias, Marina Grasic', 'Astral Future, Dreamtime Entertainment, Oakhurst Entertainment, BondIt Media Capital', '[{"name":"Zachary Levi","character":"Tucker"},{"name":"Liam Neeson","character":"Larry"},{"name":"Wes Chatham","character":"Alex"},{"name":"Titus Welliver","character":"James"},{"name":"Navid Negahban","character":"Qasim"},{"name":"Annet Mahendru","character":"Sophie"},{"name":"Grant Harvey","character":"Matt"},{"name":"Augusto Aguilera","character":"Bruce"},{"name":"Numan Acar","character":"Nadir"},{"name":"Elnaaz Norouzi","character":"Zara"}]'::jsonb, 'R', 1305),
(1561726, 'Masterplan', 'Aksi', 110, 'NR', 'Saat seorang pencuri legendaris mengincar Mona Lisa, dia merekrut dua orang asing: Chiara, pakar kejahatan siber asal Italia, dan Jay, ahli bahan peledak asal Prancis. Dia lalu mengaku sebagai ayah mereka. Terjebak dalam reuni keluarga yang kacau, keluarga baru ini harus belajar bekerja sama dan berusaha tak saling bunuh demi melancarkan pencurian terbesar abad ini.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/5xmXVd7nCK3tAo34XkO58SxUCip.jpg', 'https://image.tmdb.org/t/p/w1280/dgUDj84BWtW6EZzee8BkgKnjDhh.jpg', 7.2, 'gc0t8AfMP6k', '2026-10-16', 189.829, 50, 'tt38672588', null, null, null, 'Aksi, Cerita Seru', 'Thomas Vincent', 'Giacomo Durzi, Alessandro Fabbri, Alberto Vignati, Thomas Vincent', 'Marco Rosini', 'Amazon MGM Studios, Gaumont', '[{"name":"Stanley Tucci","character":"Roger"},{"name":"Simona Tabasco","character":"Chiara"},{"name":"Victor Belmondo","character":"Jay"},{"name":"Eliott Margueron","character":""},{"name":"Bruno Bilotta","character":"Scary Big Roman"},{"name":"Barbara Lo Gaglio","character":"Professor"},{"name":"Etienne Guillou-Kervern","character":"French Spook Officer"},{"name":"Srbo Markovic","character":"Bruno''s Bodyguard"},{"name":"Julia Messina","character":"TV Reporter"}]'::jsonb, 'R', 1646),
(1389172, 'रिपोर्टिंग लाइव', 'Kejahatan', 116, 'NR', 'A young reporter and her reluctant cameraman chase a story, only to get entangled in an illegal sand-mining racket run by a ruthless syndicate.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/72ETmrsQGk8guVo1GV8Sf7EygOe.jpg', 'https://image.tmdb.org/t/p/w1280/faJB8DXU0LXwq5ebMLj5drz8S4N.jpg', 7.9, 'GgGNG9XEJds', '2026-10-09', 134.197, 5, 'tt47657999', null, null, null, 'Kejahatan, Cerita Seru', 'Dhruv Tripathi', 'Dhruv Tripathi, Mihir Jadhav', 'Joshua Shirsath, Partha Thakur', 'Old Monk Entertainment', '[{"name":"Parineeti Chopra","character":"Sandhya"},{"name":"Deven Bhojani","character":"Vinod"},{"name":"आदिल हुसैन","character":""},{"name":"Shekhar Suman","character":""},{"name":"Amol Palekar","character":""},{"name":"Nassar","character":""},{"name":"गीता अग्रवाल शर्मा","character":""},{"name":"Saswata Chatterjee","character":""},{"name":"Prachee Shah","character":"Pooja"},{"name":"Pitobash","character":""}]'::jsonb, 'PG-13', null),
(1204680, 'Coyote vs. Acme', 'Komedi', 103, 'NR', 'After Acme products fail him one too many times in his dogged pursuit of the Roadrunner, Wile E. Coyote decides to hire a billboard lawyer to sue the Acme Corporation.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/kYDCl2y0VPvhT5eYWbMRInPoB03.jpg', 'https://image.tmdb.org/t/p/w1280/viZqGq9TNvQ5uXSD4ahg2RpRONT.jpg', 7.5, 'kMsiD1Nky5I', '2026-08-20', 127.527, 757, 'tt1756855', 7.6, 18537, 'PG', 'Komedi, Petualangan, Keluarga', 'Dave Green', 'Samy Burch', 'Christopher DeFaria, James Gunn', 'Troll Court Entertainment, Keylight Pictures, Warner Animation Group, Warner Bros. Pictures', '[{"name":"Will Forte","character":"Kevin Avery"},{"name":"Lana Condor","character":"Paige Avery"},{"name":"John Cena","character":"Buddy Crane"},{"name":"Tone Bell","character":"Sal Maltese"},{"name":"Martha Kelly","character":"Dottie Jones"},{"name":"Luis Guzmán","character":"Judge Troppogrosso"},{"name":"P.J. Byrne","character":"Bill Pellicanos"},{"name":"John Early","character":"Henry Heslop"},{"name":"Nancy Linehan Charles","character":"Cherry"},{"name":"Kenneth Choi","character":"Oscar Jeon"}]'::jsonb, 'PG', 3760),
(1339713, 'Obsession', 'Kengerian', 109, 'NR', 'Setelah menghancurkan "One Wish Willow" yang misterius untuk memenangkan hati gebetannya, seorang romantis yang putus asa menemukan dirinya mendapatkan apa yang dia minta tetapi segera menemukan bahwa beberapa keinginan datang dengan harga yang gelap dan menyeramkan.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/bRwnj8WEKBCvmfeUNOukJPwB43K.jpg', 'https://image.tmdb.org/t/p/w1280/5lTZyuBTNOfawsfPT8Q0cIg6qAF.jpg', 8.2, 'gMC8kkwbIQQ', '2026-05-13', 121.272, 6160, 'tt37287335', 7.8, 392842, 'R', 'Kengerian, Cerita Seru', 'Curry Barker', 'Curry Barker', 'James Harris, Christian Mercuri, Haley Nicole Johnson, Roman Viaris-de-Lesegno', 'Tea Shop Productions, Under the Shell, Capstone Pictures, Blumhouse Productions', '[{"name":"Michael Johnston","character":"Bear"},{"name":"Inde Navarrette","character":"Nikki"},{"name":"Cooper Tomlinson","character":"Ian"},{"name":"Megan Lawless","character":"Sarah"},{"name":"Andy Richter","character":"Carter"},{"name":"Haley Fitzgerald","character":"Viola"},{"name":"Darin Toonder","character":"Harry"},{"name":"Anthony Pavone","character":"Reggie"},{"name":"Justice","character":"Joe"},{"name":"Anthony Casabianca","character":"Chris"}]'::jsonb, '17+', 2486),
(1751701, 'After Impact', 'Cerita Fiksi', 95, 'NR', 'After losing his father, Ethan Nichols inherits one of the largest greenhouses in the country, just as the world faces a devastating threat from an approaching asteroid. As society begins to unravel, Ethan grapples with personal betrayal, overwhelming loneliness, and the growing fear that survival may come at the cost of his humanity. Seeking refuge in his family’s bunker, Ethan endures the harsh aftermath of the impact, wrestling with physical injury and emotional despair. When a faint voice crackles over his radio, Ethan discovers he''s not as alone as he believed.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/yzDuAQCY2n6zzOlBkn6JzhLhY3k.jpg', 'https://image.tmdb.org/t/p/w1280/k22XyPbce7zvzzf5OnT4uaY8ZD1.jpg', 5.8, 'Af8D6sRDyxo', '2026-09-15', 81.598, 28, 'tt36809539', null, null, null, 'Cerita Fiksi, Drama, Cerita Seru', 'Michiel Rensen, Liam Carter', 'Michiel Rensen', 'Michiel Rensen', 'PWA Media Ltd', '[{"name":"Michiel Rensen","character":"Ethan"},{"name":"Maxie Li","character":"Jessie"},{"name":"Riki Antonievich","character":"Jack"},{"name":"Will Clague","character":"Connor"},{"name":"Stephanie Ramlose","character":"Elle"},{"name":"Lee-Ann Dirks","character":"Sophie"},{"name":"James Crompton","character":"Religious Member"},{"name":"Moehau Hodges-Tai","character":"Desmond"},{"name":"Lisa Zhang","character":"Madeline"},{"name":"Karlton Laing","character":"Phillip"}]'::jsonb, 'NR', null),
(1514026, 'Buddy', 'Kengerian', 96, 'NR', 'A magical, singing orange unicorn holds his cast hostage in a surreal TV-show dimension, as he becomes more and more demented.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/1BdZbNvl1SfrrX8J9X5tQzN6Ivu.jpg', 'https://image.tmdb.org/t/p/w1280/ytoLEl5yDaxB8AtZ52uKWjaQ9ql.jpg', 7.3, null, '2026-08-27', 143.764, 133, 'tt37281055', 7.1, 5019, 'R', 'Kengerian, Komedi, Fantasi', 'Casper Kelly', 'Casper Kelly, Jamie King', 'Tyler Davidson, J.D. Lifshitz, Raphael Margules, Drew Sykes', 'BoulderLight Pictures, Low Spark Films, SIPUR, Substance', '[{"name":"Keegan-Michael Key","character":"Buddy / Dark Buddy (voice)"},{"name":"Cristin Milioti","character":"Grace"},{"name":"Delaney Quinn","character":"Freddy"},{"name":"Caleb Williams","character":"Wade"},{"name":"Madison Skyy Polan","character":"Hannah"},{"name":"Tristan Borders","character":"Oliver"},{"name":"Patton Oswalt","character":"Strappy (voice)"},{"name":"Jimmica Collins","character":"Betty Bunny / Scared Flower (voice)"},{"name":"Eric Bauza","character":"Mr. Mailbox / Worry Well / Couchy / Trashy / Pee Flower (voice)"},{"name":"Topher Grace","character":"Ben"}]'::jsonb, 'R', 4033),
(1375161, 'Don''t Move', 'Kengerian', 94, 'NR', 'A church group''s annual retreat turns deadly when they wander into the wrong part of the Ozark wilderness, and something starts picking them off one by one. Suspicion falls on Ricky, the troublemaker of the group. But the real threat is far worse. Deep in the forest, wrapped in a labyrinth of webs, the group is pursued by a terrifying prehistoric arachnid that hunts by vibration. When every step could be their last, they only have one choice: Don''t Move. It''s up to Megan to hold what''s left of the group together and get them out alive.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/uh0ZSdM8iOQgHwnUlhhanP8Dkl6.jpg', 'https://image.tmdb.org/t/p/w1280/1b0RrVxLAMhfT0vQXfWtDLwg1ke.jpg', 5.2, 'FwoYYKyJo1g', '2026-09-11', 132.129, 20, 'tt29630464', 6.7, 34, null, 'Kengerian, Cerita Seru', 'Maclain Nelson', 'Maclain Nelson, James Murray, Darren Wearmouth', 'James Murray, David M. Wulf, Ethan Berman', 'Impractical Productions, Redline Entertainment', '[{"name":"Lyndsy Fonseca","character":"Megan Forrester"},{"name":"Russ","character":"Ricky Vargas"},{"name":"Tom Cavanagh","character":"Pastor Rizzo"},{"name":"Hunter King","character":"Emma Rizzo"},{"name":"Joseph Lee Anderson","character":"Ryan Stark"},{"name":"Rob Riggle","character":"Paul DeLuca"},{"name":"Brian Quinn","character":"Ranger Wright"},{"name":"Matt Biedel","character":"Mike Forrester"},{"name":"James Murray","character":"D. Chiggins"},{"name":"Dee Freeman","character":"Maryanne Winston"}]'::jsonb, null, 823),
(1232569, 'Pinocchio: Unstrung', 'Kengerian', 82, 'NR', 'Influenced by a sinister Cricket and created by Geppetto, Pinocchio launches a violent crusade to carve himself into a real boy like his brother James, one piece at a time.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/hJNdizFlxOW89edX3Rzr6OliSFI.jpg', 'https://image.tmdb.org/t/p/w1280/7RsPdXLDNugDIlwXPVeeprNfMx.jpg', 6.5, 'Y4lZewE6JMI', '2026-07-22', 107.966, 136, 'tt30887701', 5.4, 4534, 'R', 'Kengerian, Fantasi, Misteri', 'Rhys Frake-Waterfield', 'Carlo Collodi, Rhys Frake-Waterfield', 'Scott Chambers, Rhys Frake-Waterfield', 'Jagged Edge Productions', '[{"name":"Jude Evan Lloyd","character":"Pinocchio (voice)"},{"name":"Cameron Bell","character":"James"},{"name":"Richard Brake","character":"Geppetto"},{"name":"Jessica Balmer","character":"Mia"},{"name":"Jack Art Gray","character":"Dudley"},{"name":"Robert Englund","character":"Cricket (voice)"},{"name":"Emma Tate","character":"Woodmother (voice)"},{"name":"Toni Olabanji","character":"Trey"},{"name":"Luca Marandola","character":"Logan"},{"name":"Karolina Ugrenyuk","character":"Amanda"}]'::jsonb, 'R', null),
(1288445, 'Mutiny', 'Aksi', 96, 'NR', 'After witnessing his billionaire boss'' murder and being framed for the crime, Cole Reed boards a cargo ship on a one-man crusade to avenge his boss'' death only to discover an international conspiracy.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/pu2VxGlpGwffOx292w18b1tv96j.jpg', 'https://image.tmdb.org/t/p/w1280/e2QAGrEmbpmZpMymDRkDisJkvg9.jpg', 7.6, '2Iqvbe98Gb4', '2026-08-19', 109.181, 905, 'tt32338669', 5.7, 17192, 'R', 'Aksi, Cerita Seru', 'Jean-François Richet', 'Lindsay Michel, J.P. Davis', 'Jason Statham, Marc Butan', 'Punch Palace Productions, MadRiver Pictures', '[{"name":"Jason Statham","character":"Cole Reed"},{"name":"Annabelle Wallis","character":"Angie Ellis"},{"name":"Roland Møller","character":"Captain Marko Madsen"},{"name":"Ramon Tikaram","character":"Tibu Campallo"},{"name":"Arnas Fedaravičius","character":"Mateo Pineda"},{"name":"Jason Wong","character":"Taran"},{"name":"Adrian Lester","character":"Captain Adam Spencer"},{"name":"Chaneil Kular","character":"Kameron Campallo"},{"name":"Andrew John Tait","character":"BK Lobby Businessman"},{"name":"Simon Kluth","character":"Jaran Daniles"}]'::jsonb, '17+', 1191),
(1284046, 'Onslaught', 'Aksi', 92, 'NR', 'When a rogue squad of genetically engineered super soldiers break loose in the desert, a badass Army sniper must unleash hell to protect her young daughter.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/cOGtvhc6Ij9KvzM6jZsfQyg0B0O.jpg', 'https://image.tmdb.org/t/p/w1280/clePZhqOSzNyjfuFBpOrziLEFzb.jpg', 5.7, 'AMLCbpM1fRQ', '2026-09-02', 101.059, 113, 'tt32268691', 6.2, 1404, 'R', 'Aksi, Kengerian, Cerita Seru', 'Adam Wingard', 'Simon Barrett, Adam Wingard', 'Alexander Black, Aaron Ryder, Simon Barrett, Andrew Swett', 'A24, Ryder Picture Company, Lyrical Media, Breakaway Civilization', '[{"name":"Adria Arjona","character":"Celeste"},{"name":"Dan Stevens","character":"Hans Kammler"},{"name":"Eric Wareheim","character":"Kovacks"},{"name":"Reginald VelJohnson","character":"Josiah"},{"name":"Michael Biehn","character":"Baylor"},{"name":"Blake Kennedy","character":"Daisy"},{"name":"Alex Pereira","character":"The Butcher"},{"name":"Drew Starkey","character":"Cyrus"},{"name":"Rebecca Hall","character":"Hanna Kammler"},{"name":"Jacob Scipio","character":"Griffin"}]'::jsonb, 'R', 1684),
(1275779, 'Disclosure Day', 'Cerita Fiksi', 146, 'NR', 'Jika Anda mengetahui bahwa kita tidak sendirian, jika seseorang menunjukkannya kepada Anda, membuktikannya kepada Anda, apakah itu akan membuat Anda takut?', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/AnJ8IQJI23hNpYXVNaythu061Ru.jpg', 'https://image.tmdb.org/t/p/w1280/1e0KDRYKRPHiVNj8yQKYuU2jVyQ.jpg', 7.4, 'icDuEHSxE-w', '2026-06-10', 112.221, 3717, 'tt15047880', 6.4, 164418, 'PG-13', 'Cerita Fiksi, Cerita Seru', 'Steven Spielberg', 'Steven Spielberg, David Koepp', 'Kristie Macosko Krieger, Steven Spielberg', 'Universal Pictures, Amblin Entertainment', '[{"name":"Emily Blunt","character":"Margaret Fairchild"},{"name":"Josh O''Connor","character":"Dr. Daniel Kellner"},{"name":"Colin Firth","character":"Noah Scanlon"},{"name":"Eve Hewson","character":"Jane Blakenship"},{"name":"Colman Domingo","character":"Hugo Wakefield"},{"name":"Wyatt Russell","character":"Jackson"},{"name":"Henry Lloyd-Hughes","character":"Casper Boyd"},{"name":"Elizabeth Marvel","character":"Sister Maura"},{"name":"Hettienne Park","character":"Serena"},{"name":"Tommy Martinez","character":"Santiago"}]'::jsonb, '13+', 2325),
(1742441, 'V/H/S/Mixtape', 'Kengerian', 98, 'NR', 'V/H/S/MIXTAPE cranks the volume on horror with a blood-soaked collection of cursed music videos, terrifying performances, and found footage. Press play. Pray it stops.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/uS8yoiA6NfsuYeOTbVfpem8Ib9.jpg', 'https://image.tmdb.org/t/p/w1280/mpB4pgtUcc7rCLxvlknzCbAQQEE.jpg', 4.8, 'GrIouRKyPDw', '2026-10-09', 96.985, 27, 'tt43739386', 6.7, 73, null, 'Kengerian, Musik, Cerita Seru', 'David Moreau, Renee Zhan, RZA', 'Zoe Cooper, RZA, Ernest R. Dickerson, David Moreau', 'Brad Miska, Michael Schreiber, Roy Lee, Steven Schneider', 'Spooky Pictures, Image Nation Studios, Be Afraid Media, Speed Demon Productions', '[{"name":"Mike Derks","character":"BalSac the Jaws o'' Death (segment \"Frame Narrative\")"},{"name":"Michael Bishop","character":"Blothar the Berserker (segment \"Frame Narrative\")"},{"name":"Brad Roberts","character":"Jizmak Da Gusha (segment \"Frame Narrative\")"},{"name":"Casey Orr","character":"Beefcake the Mighty (segment \"Frame Narrative\")"},{"name":"Bob Gorman","character":"Bonesnapper the Cave Troll (segment \"Frame Narrative\")"},{"name":"Josh Willis","character":"George (segment \"Dance, Dance, Dance, Dance\")"},{"name":"Christopher Romero Sosa","character":"Sam (segment \"Dance, Dance, Dance, Dance\")"},{"name":"Barbara Crampton","character":"Vanessa (segment \"Dance, Dance, Dance, Dance\")"},{"name":"Erin Griff","character":"Daisy (segment \"Dance, Dance, Dance, Dance\")"},{"name":"Zach Jobe","character":"Chris (segment \"Dance, Dance, Dance, Dance\")"}]'::jsonb, 'NR', 675),
(977942, 'The Uprising', 'Aksi', 128, 'NR', 'As war and plague devastate 14th-century England, a humble peasant ignites a rebellion, uniting an army of commoners to defy the King’s might in a desperate fight for justice and survival.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/7TUl15TOsIvndKlgMWTtLgtEzZP.jpg', 'https://image.tmdb.org/t/p/w1280/y0reRTsewsPh0ePtgvDeLIsb5Wk.jpg', 7.9, 'lyhCxZN4Ro8', '2026-09-10', 101.966, 332, 'tt36983905', null, null, 'R', 'Aksi, Drama, Sejarah', 'Paul Greengrass', 'Paul Greengrass', 'Jason Blum, Paul Greengrass, Gregory Goodman, Joanna Kaye', 'Supernix, Thank You Pictures, Electric Shadow Company, FilmNation Entertainment', '[{"name":"Andrew Garfield","character":"Ploughman"},{"name":"Jamie Bell","character":"John Ball"},{"name":"Stephen Dillane","character":"Archbishop Sudbury"},{"name":"Woody Norman","character":"King Richard II"},{"name":"Tom Hollander","character":"Treasurer Hales"},{"name":"Cosmo Jarvis","character":"Wat Tyler"},{"name":"Thomasin McKenzie","character":"Alyce"},{"name":"Jonny Lee Miller","character":"Mayor Walworth"},{"name":"Katherine Waterston","character":"Countess"},{"name":"Stanley Townsend","character":"Chief Justice Bealknap"}]'::jsonb, 'R', 2894),
(1381078, 'Love of Your Life', 'Percintaan', 109, 'NR', 'Disutradarai Rachel Morrison, LOVE OF YOUR LIFE mengikuti Maya, yang pertemuannya dengan Charlie memicu kisah cinta luar biasa dan masa depan di luar bayangannya. Saat masa depan itu berubah, Maya dihadapkan pada kehidupan baru yang tak terduga, memaksanya memahami siapa dirinya, apa yang diinginkannya, dan cara mencintai lagi.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/dL3Tcv4FU2K85bgnGRBgLjFSrLr.jpg', 'https://image.tmdb.org/t/p/w1280/mqYqKvrKTgMvK50VtEDZlYFsnHz.jpg', 6.9, 'HzGx48E64Xg', '2026-10-07', 93.552, 65, 'tt34384900', null, null, 'R', 'Percintaan, Drama', 'Rachel Morrison', 'Julia Cox', 'Ryan Gosling, Jessie Henderson', 'Amazon MGM Studios, Open Invite Entertainment', '[{"name":"Margaret Qualley","character":"Maya"},{"name":"Aaron Pierre","character":"Felix"},{"name":"Patrick Schwarzenegger","character":"Jason"},{"name":"Gabriel Basso","character":"Charlie"},{"name":"Catherine Keener","character":"Ruth"},{"name":"Tamara Lawrance","character":"Kali"},{"name":"Corey Johnson","character":"Kerry"},{"name":"Michael Shelford","character":"Colin"},{"name":"Adam Woodward","character":"Matt"},{"name":"Gayané Kaligian","character":"Armenian Family Member"}]'::jsonb, 'R', 1717),
(9479, 'The Nightmare Before Christmas', 'Fantasi', 76, 'NR', 'Tired of scaring humans every October 31 with the same old bag of tricks, Jack Skellington, the spindly king of Halloween Town, kidnaps Santa Claus and plans to deliver shrunken heads and other ghoulish gifts to children on Christmas morning. But as Christmas approaches, Jack''s rag-doll girlfriend, Sally, tries to foil his misguided plans.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/oQffRNjK8e19rF7xVYEN8ew0j7b.jpg', 'https://image.tmdb.org/t/p/w1280/dSfrsjhqC6lYe7LYDYnzWeXZmEl.jpg', 7.8, 'IoYahD_xNR0', '1993-10-09', 98.931, 10740, 'tt0107688', 7.9, 416592, 'PG', 'Fantasi, Animasi, Keluarga', 'Henry Selick', 'Caroline Thompson, Tim Burton', 'Tim Burton, Denise Di Novi, Don Hahn', 'Touchstone Pictures, Skellington Productions', '[{"name":"Danny Elfman","character":"Jack Skellington (singing) / Barrel / Clown with the Tear away Face (voice)"},{"name":"Chris Sarandon","character":"Jack Skellington (voice)"},{"name":"Catherine O''Hara","character":"Sally / Shock (voice)"},{"name":"William Hickey","character":"Dr. Finkelstein (voice)"},{"name":"Glenn Shadix","character":"Mayor (voice)"},{"name":"Paul Reubens","character":"Lock (voice)"},{"name":"Ken Page","character":"Oogie Boogie (voice)"},{"name":"Edward Ivory","character":"Santa Claus (voice)"},{"name":"Susan McBride","character":"Big Witch / WWD. (voice)"},{"name":"Debi Durst","character":"Corpse Kid / Corpse Mom / Small Witch (voice)"}]'::jsonb, 'PG', 777),
(1280300, 'The Whistler', 'Misteri', 97, 'NR', 'Reeling from their daughter''s loss, Nicole and Sebastian come into possession of a secluded Venezuelan farm, unaware of the dark forces they''re about to face.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/sX8tqkFR1aqZaLQ4Jgb8jEMB4RN.jpg', 'https://image.tmdb.org/t/p/w1280/qz8m7DGpuhc4RJmCbHsdueQKkTg.jpg', 5.2, '8PNnVN8NSHk', '2026-09-24', 88.128, 5, 'tt1776340', null, null, null, 'Misteri, Kengerian, Cerita Seru', 'Diego Velasco', 'Esteban Orozco, Diego Velasco, Carolina Paiz', 'Margaret Miller, Diego Velasco, Trevor O''Neil', 'Hideout Pictures, Open Studios, 64A Films, Sundance Institute', '[{"name":"Juan Pablo Raba","character":"Sebastian Castillo"},{"name":"Diane Guerrero","character":"Nicole Castillo"},{"name":"Indhira Serrano","character":"Petra"},{"name":"Laureano Olivares","character":"Laureano Silverio Moré"},{"name":"Laura Sofía Domínguez","character":"Greisy Moré"},{"name":"Diego Landaeta","character":"Nixon"},{"name":"Carlos Velasquez","character":"Aroa"},{"name":"Norberto Rivera","character":"Ruben"},{"name":"Ernesto Campos","character":"Dario"},{"name":"Rodrigo Valencia","character":"Erwin"}]'::jsonb, 'R', null),
(1476746, 'The Florist', 'Aksi', 99, 'NR', 'A quiet horticulturalist harboring a secret life as a lethal assassin finds his true identity jeopardized when he forms an unlikely friendship with a witnesses to police corruption.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/4tnRvIiWMzVA2Tw9c7INLo4sfo0.jpg', 'https://image.tmdb.org/t/p/w1280/jpH1VRw74w0vvPTY0ryKEtMIXc.jpg', 6.3, 'LNmIdALXoKo', '2026-09-24', 91.536, 24, 'tt33214716', null, null, null, 'Aksi, Cerita Seru', 'Babak Najafi', 'Eran Creevy, Scott Windhauser', 'Ellen S. Wander, Ceasar Richbow, Latavius Powell, Jordan Dykstra', 'CaliWood Pictures, BondIt Media Capital, Buffalo 8, Volcanic Films', '[{"name":"Dennis Quaid","character":"Carl Rikker"},{"name":"Jean Reno","character":"Charlie"},{"name":"Sky Katz","character":"Layla"},{"name":"Jim Klock","character":"Deckard"},{"name":"Leonidas Gulaptis","character":"Woodrock"},{"name":"Elsa Mollien","character":"Rebecca"},{"name":"Gabriel ''G-Rod'' Rodriguez","character":"Jason"},{"name":"Dominick LaRuffa Jr.","character":"Lloyd"},{"name":"Anna Schafer","character":""}]'::jsonb, null, 1238),
(1375646, '군체', 'Kengerian', 123, 'NR', 'Professor Se-jeong is thrust into a bloody nightmare when a rapidly mutating virus is released during a biotech conference causing authorities to seal the facility. Trapped inside with no escape, Se-jeong along with a small group of survivors must fight to stay alive while the infected undergo horrific transformations.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/hDPGsJxo8xX0OyqcMB8xI3RdaF3.jpg', 'https://image.tmdb.org/t/p/w1280/pGxUbJ1vKuMYeEjKDokFI7DNbSG.jpg', 8.1, 'LW6dpj1uCK8', '2026-05-21', 82.078, 1168, 'tt34385135', 6.5, 18328, 'R', 'Kengerian, Aksi, Cerita Fiksi', '연상호', '연상호, 최규석', '김연호', 'Wow Point, Smilegate Entertainment, Midnight Studio', '[{"name":"전지현","character":"Kwon Se-jeong"},{"name":"구교환","character":"Seo Young-cheol"},{"name":"지창욱","character":"Choi Hyun-seok"},{"name":"김신록","character":"Choi Hyun-hee"},{"name":"신현빈","character":"Kong Seol-hee"},{"name":"고수","character":"Han Kyu-seong"},{"name":"이중옥","character":"Lee Bong-seok"},{"name":"김종태","character":"Kang Woo-cheol"},{"name":"황재열","character":"Citizen"},{"name":"이담희","character":"Lee So-eun"}]'::jsonb, '13+', 920),
(1765072, 'You Can See Everything', 'Dokumenter', 175, 'NR', 'Thirty-four days before she''s sent to prison, notorious Silicon Valley founder Elizabeth Holmes invites a skeptical film crew to document her every move. What begins as an intimate portrait of an enigmatic felon becomes a mind-bending three-year journey into the abyss.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/Ap8QwmKfSjYbWC4XIP8w9pdn72O.jpg', 'https://image.tmdb.org/t/p/w1280/nhIL3O4W9h5V5JbNQm7yjoDk3So.jpg', 8.3, 'IEx8D1Wb__U', '2026-10-16', 78.283, 14, 'tt45368240', 7.9, 165, 'R', 'Dokumenter', 'Nathan Fielder, Lance Oppenheim', null, 'Lance Oppenheim, Nathan Fielder, Tatiana Bears, Maggie Ambrose', 'A24, Blow Out Productions, To Be Formed', '[{"name":"Elizabeth Holmes","character":"Self"},{"name":"Nathan Fielder","character":"Self"},{"name":"Billy Evans","character":"Self"},{"name":"Amanda Seyfried","character":"Self / Elizabeth Holmes"},{"name":"Christopher Abbott","character":"Self / Billy Evans"},{"name":"Lance Oppenheim","character":"Self"},{"name":"Christian Rasmus Holmes IV","character":"Self"},{"name":"Noel Anne","character":"Self"}]'::jsonb, 'R', null),
(1273221, 'Scary Movie', 'Komedi', 96, 'NR', 'Twenty-six years after outrunning a suspiciously familiar masked killer, the Core Four are back in the killer''s crosshairs and no horror movie IP is safe.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/znHT8peERZRWG1ME3r0Db0EV8k8.jpg', 'https://image.tmdb.org/t/p/w1280/xWBiXclrRmTggQHMRsIn84YHavs.jpg', 6.3, 'cGgWAHXuTKc', '2026-06-03', 80.248, 2038, 'tt32093575', 4.8, 61113, 'R', 'Komedi', 'Michael Tiddes', 'Marlon Wayans, Shawn Wayans, Keenen Ivory Wayans, Rick Alvarez', 'Keenen Ivory Wayans, Marlon Wayans, Rick Alvarez, Shawn Wayans', 'Wayans Bros. Entertainment, Miramax, Paramount Pictures', '[{"name":"Anna Faris","character":"Cindy"},{"name":"Regina Hall","character":"Brenda"},{"name":"Marlon Wayans","character":"Shorty / ''Joe'' / ''Tiffany'' / Count Brolock"},{"name":"Shawn Wayans","character":"Ray"},{"name":"Olivia Rose Keegan","character":"Sara"},{"name":"Cameron Scott Roberts","character":"Jack"},{"name":"Savannah Lee Nassif","character":"Tuesday"},{"name":"Sydney Park","character":"DEI"},{"name":"Gregg Wayans","character":"Brad"},{"name":"Benny Zielke","character":"Jess"}]'::jsonb, '17+', 689),
(980431, 'Avatar Aang: The Last Airbender', 'Animasi', 99, 'NR', 'Avatar Aang, the world''s last Airbender, learns of an ancient power that could save his culture from extinction. With the help of his friends, he embarks on a global quest to find it before it falls into the wrong hands and threatens to upend the peace they sacrificed everything to achieve.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/3sgnSfNT27Bx5O5ukr7B26mhEQq.jpg', 'https://image.tmdb.org/t/p/w1280/ezbrL1dMymKQZw7mDEWa2ZTzN7d.jpg', 9.1, '7b20GRFZBFE', '2026-07-24', 77.328, 1341, 'tt18259538', null, null, 'PG', 'Animasi, Petualangan, Fantasi, Aksi', 'Lauren Montgomery', 'Tim Hedrick, Christopher L. Yost, Bryan Konietzko, Michael Dante DiMartino', 'Latifa Ouaou, Maryann Garger, Dagan Potter, Bryan Konietzko', 'Nickelodeon Movies, Paramount Pictures, Flying Bark Productions, Studio Mir', '[{"name":"Eric Nam","character":"Aang (voice)"},{"name":"Dave Bautista","character":"Tagah (voice)"},{"name":"Jessica Matten","character":"Katara (voice)"},{"name":"Román Zaragoza","character":"Sokka (voice)"},{"name":"Steven Yeun","character":"Zuko (voice)"},{"name":"Dionne Quan","character":"Toph (voice)"},{"name":"Dee Bradley Baker","character":"Appa / Momo (voice)"},{"name":"Freida Pinto","character":"Avatar Sonam (voice)"},{"name":"Ke Huy Quan","character":"Avatar Xian (voice)"},{"name":"Taika Waititi","character":"Gorillavark (voice)"}]'::jsonb, 'PG', 736),
(1083381, 'Backrooms', 'Kengerian', 111, 'NR', 'Setelah pasien seorang terapis menghilang ke dimensi di luar realitas, dia harus menjelajah ke tempat yang tidak dikenal untuk menyelamatkannya.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/rhGx6E3qRNMgj3i5su2oukNHwIQ.jpg', 'https://image.tmdb.org/t/p/w1280/dqmMWNWfLnExDRpMtIMqI97GQFR.jpg', 7, '0HjdiohVOik', '2026-05-27', 76.978, 3767, 'tt26657236', 6.7, 221583, 'R', 'Kengerian, Misteri, Cerita Fiksi', 'Kane Parsons', 'Will Soodik', 'Shawn Levy, Dan Cohen, Dan Levine, James Wan', 'Atomic Monster, 21 Laps Entertainment, A24, Phobos', '[{"name":"Chiwetel Ejiofor","character":"Clark"},{"name":"Renate Reinsve","character":"Mary"},{"name":"Finn Bennett","character":"Bobby"},{"name":"Lukita Maxwell","character":"Kat"},{"name":"Mark Duplass","character":"Phil"},{"name":"Avan Jogia","character":"Naren Warne"},{"name":"Robert Bobroczkyi","character":"Pirate Clark"},{"name":"Ember Ambrose","character":"Young Mary"},{"name":"Krista Kosonen","character":"Nora"},{"name":"Philip Granger","character":"Meterman"}]'::jsonb, '17+', 2097),
(3933, 'Corpse Bride', 'Percintaan', 77, 'NR', 'Aksinya berlangsung di sebuah desa Eropa pada abad ke-19. Tokoh utama, seorang pemuda bernama Victor, diseret ke dunia bawah oleh kekuatan kegelapan dan dinikahkan di sana dengan Pengantin Mayat yang misterius, sementara pengantin perempuannya yang sebenarnya, Victoria, menanti pengantin prianya di dunia orang hidup. Meskipun kenyataan bahwa tinggal di Kerajaan Orang Mati ternyata jauh lebih menarik daripada gaya hidup Victoria yang biasa ia jalani, Victor memahami bahwa ia tidak akan menukar satu-satunya cintanya dengan apa pun di dunia alternatif mana pun...', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/3RAoVTxUk1OzZClscAsynuu670p.jpg', 'https://image.tmdb.org/t/p/w1280/v23fWgJUEt8EMmvn19btIacxP8E.jpg', 7.6, 'BgwJEpmPKk8', '2005-09-12', 73.741, 10511, 'tt0121164', 7.4, 333077, 'PG', 'Percintaan, Fantasi, Animasi', 'Tim Burton, Mike Johnson', 'John August, Caroline Thompson, Pamela Pettler, Tim Burton', 'Allison Abbate, Tim Burton', 'Tim Burton Productions, Patalex Productions, Warner Bros. Pictures, LAIKA', '[{"name":"Johnny Depp","character":"Victor Van Dort (voice)"},{"name":"Helena Bonham Carter","character":"Corpse Bride (voice)"},{"name":"Emily Watson","character":"Victoria Everglot (voice)"},{"name":"Tracey Ullman","character":"Nell Van Dort / Hildegarde (voice)"},{"name":"Paul Whitehouse","character":"William Van Dort / Mayhew / Paul the Head Waiter (voice)"},{"name":"Joanna Lumley","character":"Maudeline Everglot (voice)"},{"name":"Albert Finney","character":"Finis Everglot (voice)"},{"name":"Richard E. Grant","character":"Barkis Bittern (voice)"},{"name":"Christopher Lee","character":"Pastor Galswells (voice)"},{"name":"Michael Gough","character":"Elder Gutknecht (voice)"}]'::jsonb, 'PG', null),
(1607127, 'One Last Shot', 'Aksi', 98, 'NR', 'Navy Seal Jake Harris must stop a team of mercenaries, led by his disillusioned former comrade, from disabling the US missile defense network.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/niQ4NBh2jqAf1hDZP5m6ReWFAb7.jpg', 'https://image.tmdb.org/t/p/w1280/7AArZYRp6zGtbvSbbqoHn9xFp0L.jpg', 7.4, '8PAy3i9uU0A', '2026-09-22', 74.4, 133, 'tt37971717', null, null, 'R', 'Aksi, Cerita Seru', 'James Nunn', 'Jamie Russell', null, 'Sky Cinema, Signature Films', '[{"name":"Scott Adkins","character":"Jake Harris"},{"name":"Steven Cree","character":"Elliot Carter"},{"name":"Hannah Ware","character":"Elena Torres"},{"name":"Dolph Lundgren","character":"Admiral Mulholland"},{"name":"ケイン・コスギ","character":"Lee"},{"name":"Neil Linpow","character":"Long"},{"name":"Ray Fearon","character":"Robinson"},{"name":"Tom Dunne","character":"Greene"},{"name":"Michel Curiel","character":"Perez"},{"name":"Tom Leigh","character":"Jericho"}]'::jsonb, 'R', null),
(1590723, 'Laut Bercerita', 'Drama', 133, 'NR', 'Set during the volatile final months of Indonesia’s New Order regime, the narrative chronicles a young student activist''s perilous commitment to pro-democracy underground movements and his family''s subsequent, grueling quest for justice following his forced disappearance.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/8FqJSSMPaKJzqq2VVxVmdHUozLY.jpg', 'https://image.tmdb.org/t/p/w1280/dibjzvhuz4FiF0Af9BkcMDHRSCD.jpg', null, 'Crx2f2CvUpc', '2026-10-29', 3.843, 0, 'tt39073337', null, null, 'TV-MA', 'Drama, Sejarah', 'Yosep Anggi Noen', 'Leila S. Chudori, Yosep Anggi Noen', 'Gita Fara, Budi Setyarso, Leila S. Chudori', 'Pal8 Pictures, Visual Media Studio, Jagartha, Lynx Films', '[{"name":"Reza Rahadian","character":"Biru Laut"},{"name":"Yunita Siregar","character":"Asmara Jati"},{"name":"Christine Hakim","character":"Mrs. Wibisana / Laut''s Mother"},{"name":"Arswendy Bening Swara","character":"Mr. Arya Wibisana / Laut''s Father"},{"name":"Eva Celia","character":"Ratih Anjani"},{"name":"Dian Sastrowardoyo","character":"Kasih Kinanti"},{"name":"Yoga Pratama","character":"Arifin Bramantyo"},{"name":"Ben Nugroho","character":"Alex Perazon"},{"name":"Kevin Julio","character":"Daniel Tumbuan"},{"name":"Dewa Dayana","character":"Sunu Dyantoro"}]'::jsonb, '17+', null),
(1450848, 'Dua Hati Ibu', 'Drama', 102, 'NR', 'Two childless married couples raise an unexpected son from an illicit affair between the two households. Amidst the chaos that follows a paternity reveal, the two wives take parenting into their own hands.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/ugFHOSdCSk2I4FbTz9pXPqxrq9H.jpg', 'https://image.tmdb.org/t/p/w1280/yW9RjrPketD2Kz3Y6q3eIpIC2I2.jpg', null, null, '2026-10-23', 3.543, 0, 'tt38773553', null, null, null, 'Drama', 'Luhki Herwanayogi', 'Luhki Herwanayogi, Devina Sofiyanti', 'Iqbal Mohammad Hamdan, Giovanni Rahmadeva', 'Qun Films, Catchlight Pictures, Aview Images, Arungi Films', '[{"name":"Raihaanun","character":""},{"name":"Della Dartyan","character":""},{"name":"Iedil Putra","character":""},{"name":"Ariyo Wahab","character":""},{"name":"Farrell Rafisqy","character":""}]'::jsonb, '13+', null),
(1590752, 'Pulang Kampung', 'Musik', 100, 'NR', 'Dalam rangka menjadi Caleg sesuai perintah ayahnya, Daniel, pemuda Batak kelahiran Jakarta, terpaksa pulang kampung untuk belajar budaya Batak ditemani Uli, sepupunya yang tinggal di Danau Toba. Masalah muncul ketika Daniel ternyata bukan cuma jatuh cinta pada budaya Batak, tapi juga pada Uli.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/wsipU0tvTmrSTsBh7pe6r8pk58z.jpg', null, null, 'JkiJTQXe8Lo', '2026-11-26', 3.553, 0, 'tt39073352', null, null, null, 'Musik, Drama, Komedi', 'Bene Dion Rajagukguk', 'Bene Dion Rajagukguk', 'Ernest Prakasa, Dipa Andika', 'Imajinari, Jagartha, Trinity Entertainment Network, Miles Films', '[{"name":"Axelo Nababan","character":"Daniel"},{"name":"Vanessa Zee","character":"Uli"},{"name":"Lea Simanjuntak","character":"Daniel''s Mom"},{"name":"Paulus Simangunsong","character":"Daniel''s Father"},{"name":"Judika Sihotang","character":"Uli''s Father"},{"name":"Rita Matumona","character":"Oppung Dio"},{"name":"Indra Jegel","character":""},{"name":"Boris Bokir","character":""},{"name":"Oki Rengga","character":""},{"name":"David Saragih","character":""}]'::jsonb, null, null),
