(1763612, 'Orang Sebelah', 'Kengerian', 100, 'NR', 'This film is based on one of the well-known, spine-chilling myths circulating around the IPB University campus area that haunts the students living in the campus dorms.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/kmM5kbjlD46Hon1oUG3I0BbTFxz.jpg', null, null, null, '2026-11-26', 3.808, 0, null, null, null, null, 'Kengerian', 'Chiska Doppert', 'Erik Supit', 'Jhony Fam, Maya Savitri', 'Avantgarde Production', '[{"name":"Cassandra Sheryl Lee","character":""},{"name":"Esta Pramanita","character":""},{"name":"Luna Fathia","character":""},{"name":"Sadiya Aisye","character":""},{"name":"Ryuken Lie","character":""},{"name":"Yando Adrian","character":""},{"name":"Monique Henry","character":""},{"name":"Arry Febrian","character":""},{"name":"Ananda George","character":""},{"name":"Turaekhan Roy","character":""}]'::jsonb, null, null),
(1604413, 'Banyak Anak Banyak Rejeki yang Harus Dicari', 'Drama', 100, 'NR', 'Gravedigger Babe Rojali lives in poverty with his wife Siti Juleha and their three children. During a heavy rain, as he was busy bailing out water from his leaky house, a neighborhood watchman arrived and asked him to dig a grave that night, at the request of the neighborhood head. Reluctantly, he set out, accompanied by his younger brother Abdul. While digging the grave, Babe Rojali prayed and asked God to make him rich. That prayer seemed to be answered because he later found a lump of gold in the ground of the grave he had dug. From that moment on, Babe Rojali’s life changed completely.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/aPEkDioPBXdv1mtilWpFS7JcrvT.jpg', null, null, null, '2027-01-14', 2.992, 0, null, null, null, null, 'Drama, Komedi', 'Tyas Asko', 'Kaka Endi', null, 'Black White Pictures', '[{"name":"Opie Kumis","character":"Babe Rojali"},{"name":"Fadli Fuad","character":"Hendrik Rojali"},{"name":"Elina Joerg","character":"Ningsih Beethoven"},{"name":"Elvy Sukaesih","character":"Siti Juleha"},{"name":"Revaldo","character":"Ari Rojali"},{"name":"Mandy Edenia","character":"Laila Rojali"},{"name":"Ali Gohom","character":"Abdul"},{"name":"Hanif MZ","character":"Little Hendrik"},{"name":"Hafi Badali","character":"Little Ari"},{"name":"Noia Oren","character":"Little Laila"}]'::jsonb, 'SU', null),
(1058588, 'The Invisible Guest', 'Misteri', 121, 'NR', 'Accused of murdering her lover, a young businesswoman hires a brilliant lawyer. With only three hours left, they must uncover what really happened.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/z3ZQXbY05pfeDwbozfxdbj7yQjM.jpg', 'https://image.tmdb.org/t/p/w1280/thKVLeS5rgEJzT40FiYFBRl0r3t.jpg', null, '97WFftAdjfE', '2026-08-07', 2.592, 0, 'tt17497130', null, null, null, 'Misteri, Drama, Cerita Seru', 'Danial Rifki', null, null, 'Falcon Pictures', '[{"name":"Reza Rahadian","character":"Reza"},{"name":"Mawar Eva De Jongh","character":"Mawar"},{"name":"Arifin Putra","character":"Yoshi"},{"name":"Putri Ayudya","character":"Salma"},{"name":"Willem Bevers","character":"Donny"},{"name":"Gusti Rayhan","character":"Dito"},{"name":"Whani Darmawan","character":"Jagawana"},{"name":"Vonny Anggraini","character":"Widya"},{"name":"Edo Borne","character":"Aditya"},{"name":"Rania Putrisari","character":"Camel"}]'::jsonb, null, null),
(1763585, 'Lagi Probation: Kerja Ngejar Apa Sih?', 'Komedi', 100, 'NR', 'Bintang harus cari kerjaan untuk hidupin keluarga dan dirinya sendiri. Setelah berjuang sana-sini, kesempatan langka akhirnya datang: Bintang diterima jadi anak probation alias magang di perusahaan bumbu dapur besar, bersama Bima si Cumlaude, Velma si Asbun, Damai si Cari Muka, Mika si Pewaris, dan Claudia si Robot Korporat. Tapi, baru juga bonding sama teman-teman barunya, eh ternyata cuma satu yang akan lolos probation dan jadi karyawan tetap. Seketika, teamwork berubah jadi team-war, teman jadi saingan, kolaborasi jadi kompetisi. 6 orang, 1 posisi. Siapa yang akan berhasil?', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/4glDFxFmu3GyX9N50EtiLk0k8zp.jpg', 'https://image.tmdb.org/t/p/w1280/olkdII9tRfrQ84ne8d44h7LrXbz.jpg', null, 'QA8NwVVZguw', '2026-11-12', 2.542, 0, 'tt46594641', null, null, null, 'Komedi, Drama', 'Archie Hekagery', 'Archie Hekagery, Rifki Ardisha', 'Shanty Harmayn, Aoura Lovenson Chandra, Tanya Yuson', 'BASE Entertainment, Laspro, ARENDI', '[{"name":"Aurora Ribero","character":"Bintang"},{"name":"Rey Bong","character":"Bima"},{"name":"Gabriella Ekaputri","character":"Claudia"},{"name":"Daffa Wardhana","character":"Mika"},{"name":"Arafah Rianti","character":"Velma"},{"name":"Lutfi Afansyah","character":"Damai"},{"name":"Wafda Saifan Lubis","character":"Chandra"},{"name":"Abirama Putra Andresta","character":"Bintang''s Little Brother"},{"name":"Indra Birowo","character":"Bintang''s Father"},{"name":"Lolox","character":""}]'::jsonb, null, null),
(1398505, 'Desember Jani', 'Drama', 101, 'NR', 'Sepuluh hari setelah Julia pergi dari rumah tanpa pamit, Jani (13 tahun) cuma ingin kakaknya itu pulang. Ia tahu ibunya, Winnie, adalah penyebab Julia pergi. Hubungan mereka makin renggang, sementara Winnie sibuk bekerja untuk menutupi rasa bersalahnya. Hanya Oma yang bisa menghibur Jani. Diam-diam, Jani masih berhubungan dengan Julia. Selama empat hari di bulan Desember, Jani harus memilih: tetap diam atau menghadapi ibunya.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/rmF3JezLg5ZpFmvOXy50gTwGaWE.jpg', null, null, '9eQFxRmw9g8', '2026-12-10', 2.213, 0, 'tt39673642', null, null, 'TV-G', 'Drama, Keluarga', 'Ariani Darmawan', 'Cyntha Hariadi, Ariani Darmawan', 'Meiske Taurisia, Muhammad Zaidy', 'Palari Films', '[{"name":"Chempa Puteri","character":"Jani"},{"name":"Sigi Wimala","character":"Winnie"},{"name":"Tutie Kirana","character":"Oma"},{"name":"Hyori Mika","character":"Julia"}]'::jsonb, 'SU', null),
(1691495, 'Hajatan Setan', 'Kengerian', 100, 'NR', 'A young woman returns to her hometown after being away for years. However, her homecoming reopens old wounds and triggers a series of strange events that slowly engulf the villagers in suspicion and fear.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/eJvErXsnBM2PgfmXsvdCVmKDJH6.jpg', 'https://image.tmdb.org/t/p/w1280/kOtozhUgLfjPeCTit6X4hMVzaq4.jpg', null, null, '2026-12-03', 2.647, 0, null, null, null, null, 'Kengerian', 'Bambang Drias, Eko Kristianto', 'Andhy Pulung, B.W. Purbanegara, Vidya Talisa Ariestya, Novia Anggi', null, 'Multi Buana Kreasindo, Drias Production', '[{"name":"Ari Irham","character":""},{"name":"Luna Maya","character":""},{"name":"Alika Jantinia","character":""},{"name":"Gisellma Firmansyah","character":""},{"name":"Tanta Ginting","character":""},{"name":"Indra Birowo","character":""},{"name":"Asri Welas","character":""},{"name":"Bima Zeno","character":""},{"name":"Karina Suwandi","character":""},{"name":"Sita Permata Sari","character":""}]'::jsonb, null, null),
(1551036, 'Seporsi Mie Ayam Sebelum Mati', 'Drama', 125, 'NR', 'If today were your last day, what one small thing would you really want to do? For Ale, the answer is simple: enjoy a bowl of his favorite chicken noodles before he truly gives up on life. But when his regular food cart is closed, that situation leads him into a series of unexpected encounters.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/wqfi1Cicqj1Y6sDxQYSaRihw6IJ.jpg', 'https://image.tmdb.org/t/p/w1280/rQD4rMpygqw3z9ZJMSkz6h6tSJ4.jpg', null, 'yESY1GP1mfQ', '2026-11-12', 2.495, 0, 'tt45292829', null, null, null, 'Drama', 'Kuntz Agus', 'Brian Khrisna, Alim Sudio, Kuntz Agus', 'Philip Lesmana, Ardina Atles', 'Sinergi Pictures, Ben Film, AZ Films, Nuon', '[{"name":"Benidictus Siregar","character":"Ale"},{"name":"Teuku Rifnu Wikana","character":"Murad"},{"name":"Zulfa Maharani","character":"Juleha"},{"name":"Tika Panggabean","character":"Mami Louise"},{"name":"Fajar Nugra","character":"Ipul"},{"name":"Chicco Kurniawan","character":"Pram"},{"name":"Jourdy Pranata","character":"Gilang"},{"name":"Pangeran Lantang","character":"Bima"},{"name":"Alex Abbad","character":""},{"name":"Ence Bagus","character":""}]'::jsonb, '17+', null),
(1757259, 'Rambut Sewu: Satu Langkah Getih', 'Kengerian', 100, 'NR', 'Wulan (Wavi Zihan) moves to a village with her mother, Ratih (Ruth Marini). After working at a tea factory, they move into an old house owned by the company. From then on, Wulan begins to experience strange dreams and mysterious events, eventually losing control of herself. The villagers attribute these disturbances to Marni (Taskya Namya), a former resident of the house whose story has remained a mystery for decades. When Wulan’s story spreads on social media, Damar (Yusuf Mahardika), a reporter and native son of the village, arrives to investigate. Suradi (Donny Alamsyah), who is aware of the powers of the past, comes to help. Together, they try to sever Wulan’s connection to Marni and the power of Dhandhang Gendhing.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/n2j1EDgh818ZYRVZeasJul2Pbmk.jpg', null, null, null, '2026-11-05', 2.204, 0, null, null, null, null, 'Kengerian, Misteri, Drama', 'Hanny R. Saputra', 'Vera Rasyidin, Rebecca Maruska Bath', 'Zakir Rasyidin', 'Mika Entertainment', '[{"name":"Taskya Namya","character":"Marni"},{"name":"Wavi Zihan","character":"Wulan/Sundari"},{"name":"Ruth Marini","character":"Ratih"},{"name":"Yusuf Mahardika","character":"Damar"},{"name":"Donny Alamsyah","character":"Suradi"},{"name":"Sadana Agung","character":"Tedjo"},{"name":"Yewen","character":"Pieter"},{"name":"Bonar Manalu","character":"Bonar"},{"name":"Elissa Knapp","character":""},{"name":"Ivonne Dahler","character":"Minarti"}]'::jsonb, null, null),
