(1774839, 'Uniform: Cinta di Balik Seragam', 'Drama', 101, 'NR', 'Young officer Jason must face a bitter reality. Lara, his girlfriend, has been murdered in a staged accident. Noticing numerous inconsistencies, he asks the Commander to join the investigation. A series of events reveals facts linking a criminal syndicate to the tragedy that befell his girlfriend.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/d1cVaOhujM0rKnL5X5z8fRQt0gR.jpg', null, null, null, '2026-10-22', 2.107, 0, null, null, null, null, 'Drama', 'Joseph Selvakumar', 'Deepak Annathurai', 'Deepak Annathurai', 'Jas Films', '[{"name":"Yama Carlos","character":"Commander"},{"name":"Kevin Faulky","character":"Jason"},{"name":"Aline Fauziah","character":"Lara"},{"name":"Rivaldo Delanov","character":""},{"name":"Randy Gavrilla","character":""},{"name":"Jo Tampubolon","character":""},{"name":"Angelique Philpott","character":""},{"name":"Alexandra Cita","character":""},{"name":"Muhamad Yadi Lie","character":""},{"name":"Zahid Haydar Ali","character":""}]'::jsonb, '13+', null),
(1707669, 'Festival Hantu Lapar', 'Kengerian', 100, 'NR', 'After inadvertently violating a sacred ancestral taboo during the Hungry Ghost Festival, an adopted young man and his friends must break a relentless supernatural curse before the spiritual gates close permanently.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/xQo2xIQFKYq46iYEq4vByTPUK9s.jpg', 'https://image.tmdb.org/t/p/w1280/wa39eElPw7UWDZeQrzm8qglbqN0.jpg', null, '5XcAn0TLlGY', '2026-11-26', 1.935, 0, 'tt43611167', null, null, null, 'Kengerian, Komedi', 'Imam Darto', 'Celvin Jaya Hadi, Imam Darto, Warman Nasution', 'Raam Punjabi', 'MVP Pictures, PK Films, Show Token', '[{"name":"Endy Arfian","character":"Raka"},{"name":"Aci Resti","character":""},{"name":"Fajar Nugra","character":""},{"name":"Jenny Zhang","character":""},{"name":"Augie Fantinus","character":""},{"name":"Sarah Beatrix","character":""},{"name":"Rizky Inggar","character":""},{"name":"Alvin Adam","character":""},{"name":"Oki DM","character":""},{"name":"Arla Ailani","character":""}]'::jsonb, null, null),
(1627840, 'Zona Merah', 'Aksi', 100, 'NR', 'Two weeks after a devastating zombie outbreak destroys their home, a resilient young woman and her band of refugees flee to a neighboring safe zone, only to be hunted by paranoid locals convinced the outsiders are harboring the lethal virus.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/92IINdZ9toPh8Yf6Oq1NEqPLbjj.jpg', null, null, null, '2027-01-14', 2.53, 0, 'tt39555302', null, null, null, 'Aksi, Fantasi, Kengerian, Cerita Seru', 'Sidharta Tata, Fajar Martha Santosa', 'Dinda Putri Anjani, Sidharta Tata', 'Wicky V. Olindo', 'Screenplay Films, Emtek Media, Surya Citra Media, Rapi Films', '[{"name":"Aghniny Haque","character":"Maya"},{"name":"Andri Mashadi","character":"Risang"},{"name":"Devano Danendra","character":"Adi"},{"name":"Maria Theodore","character":"Ella"},{"name":"Myesha Lin","character":"Olivia"},{"name":"Bryan Domani","character":"Omar"},{"name":"Shindy Huang","character":"Hana"},{"name":"Luna Maya","character":"Jenny"},{"name":"Lukman Sardi","character":"Zaenal Effendi"},{"name":"Derby Romero","character":"Tommy"}]'::jsonb, null, null),
(1263153, 'Forza', 'Drama', 90, 'NR', 'An impoverished thirteen-year-old adolescent from the slums of Bali finds his aspirations of professional football within reach after forming an unlikely partnership with a veteran athlete on the verge of retirement, culminating in an unprecedented trial with the AC Milan Youth Academy in Italy.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/2zdJXARQ5hACMuNXKRPrtRLzMwl.jpg', 'https://image.tmdb.org/t/p/w1280/gMxec0LJrphjAkfv0iCyikqzOs3.jpg', null, null, '2026-10-25', 1.708, 0, 'tt31411099', null, null, null, 'Drama, Keluarga', 'Marco Balsamo', 'Marco Balsamo', 'Marco Balsamo, Tara Sibel', 'RIVA Studios, Adhya Pictures, Laser Film, Coevolution', '[{"name":"Teuku Rifnu Wikana","character":"Soleh"},{"name":"Atiqah Hasiholan","character":"Indah"},{"name":"Arie Kriting","character":"Heri"},{"name":"Yoriko Angeline","character":"Dewi"},{"name":"Ruth Marini","character":"Annisa"},{"name":"Oka Antara","character":""},{"name":"Ghazi Alhabsy","character":"Bima"},{"name":"Marco Balsamo","character":"Marco"},{"name":"Tio Pakusadewo","character":"Arief"},{"name":"Tara Sibel","character":"Sibel"}]'::jsonb, 'SU', null),
(1776255, 'Merah Sebelum Fajar', 'Drama', 113, 'NR', 'Amidst the volatile dawn of Indonesian independence, five individuals from starkly contrasting socio-political backgrounds must navigate a heavily fractured nation to deliver a critical state document, confronting severe hostility and paranoia from the very revolutionary factions they seek to serve.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/vfl94mcCkdkWX1VtyNPO7Tas7mC.jpg', 'https://image.tmdb.org/t/p/w1280/aeUIdBATp09Omnz0OLE2OP07uxE.jpg', null, null, '2026-10-27', 2.482, 0, null, null, null, null, 'Drama, Sejarah, Cerita Seru', 'Garin Nugroho', 'Dirmawan Hatta, Garin Nugroho', 'Nicholas Saputra', 'Imajinari, Jagartha, Springboard Entertainment, Laspro', '[{"name":"Nicholas Saputra","character":""},{"name":"Laura Basuki","character":""},{"name":"Bront Palarae","character":""},{"name":"Tissa Biani Azzahra","character":""},{"name":"Nagra Pakusadewo","character":""}]'::jsonb, null, null),
(1381071, 'ゴジラ-0.0', 'Cerita Fiksi', 135, 'NR', 'War reduced Japan to zero, and Godzilla plunged it into minus. Two years have passed since then, and the country has faced agonizing struggles to achieve recovery and finally reclaim its daily life. Just as humanity managed to cling to a hard-won peace, a new threat strikes, crushing hope in an instant.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/zpcoFlZwyLnBt7bb5wmvGDCdg06.jpg', 'https://image.tmdb.org/t/p/w1280/oqrYIDH4tvfEzPe1yqT4jzmAWHQ.jpg', null, 'pWJjYoqVSjQ', '2026-11-04', 20.193, 0, 'tt34384661', null, null, null, 'Cerita Fiksi, Kengerian, Aksi', 'Takashi Yamazaki', 'Takashi Yamazaki', '岸田一晃, 守屋圭一郎, 阿部豪', 'TOHO, Robot Communications, TOHO Studios', '[{"name":"神木隆之介","character":"Koichi Shikishima"},{"name":"浜辺美波","character":"Noriko Oishi"},{"name":"山田裕貴","character":"Shiro Mizushima"},{"name":"Kuranosuke Sasaki","character":"Seiji Akitsu"},{"name":"Jun Kunimura","character":""},{"name":"田中美央","character":"Captain Tatsuo Hotta"},{"name":"安藤サクラ","character":"Sumiko Ota"},{"name":"長澤まさみ","character":"Aoyama"},{"name":"田中泯","character":"Kanji Murakami"},{"name":"吉岡秀隆","character":"Kenji Noda"}]'::jsonb, 'R', null),
(656908, 'रामायण', 'Fantasi', 208, 'NR', 'An ancient epic follows a young prince and princess whose marriage and subsequent exile mark the beginning of a legendary journey. Their story of love, duty and destiny sets the stage for greater challenges ahead.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/gOWnXaBxqT6k2y40hKfYU6c0Ym.jpg', 'https://image.tmdb.org/t/p/w1280/ks72NqTPhpupk207NXiqmZIQQVI.jpg', null, 'AYkPRN874m8', '2026-11-06', 15.402, 0, 'tt27988879', null, null, null, 'Fantasi, Aksi, Petualangan', 'Nitesh Tiwari', 'Shridhar Raghavan, Nitesh Tiwari', 'Namit Malhotra', 'Monster Mind Creations, Prime Focus Studios, DNEG', '[{"name":"रणबीर कपूर","character":"Ram / Parshuram / Vishnu"},{"name":"Yash","character":"Ravana"},{"name":"Sai Pallavi","character":"Sita"},{"name":"Ravi Dubey","character":"Lakshman"},{"name":"अरुण गोविल","character":"Dashrath"},{"name":"Rakul Preet Singh","character":"Shurpanakha"},{"name":"लारा दत्ता","character":"Kaikeyi"},{"name":"इंदिरा कृष्णन","character":"Kaushalya"},{"name":"కాజల్ అగర్వాల్","character":"Mandodari"},{"name":"Sheeba Chaddha","character":"Manthara"}]'::jsonb, 'PG-13', null),
(1433568, '粽邪4：坤蒂拉娜', 'Cerita Seru', 120, 'NR', 'When a forbidden Indonesian exorcism is broadcast live online, it unleashes a legendary demonic entity across Asia, forcing the grieving son of a Taiwanese victim to trace the curse back to its ancient, blood-soaked roots in rural Indonesia before it consumes everyone in its digital wake.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/6u8F23BammMeCWLvWITbFM2Nwbe.jpg', 'https://image.tmdb.org/t/p/w1280/2VDV1ZBHV1PKKBcWjRRCydZO1YR.jpg', null, null, '2026-10-23', 10.59, 0, 'tt38633224', null, null, null, 'Cerita Seru, Misteri, Kengerian', '廖士涵', '高鳴晟, 黃致凱', '鄒介中', 'WOWING Entertainment Group', '[{"name":"陳博正","character":""},{"name":"許安植","character":"Jia-min"},{"name":"陳雪甄","character":"Yu-Lan"},{"name":"劉國劭","character":"A-Guai"},{"name":"胡語恆","character":""},{"name":"Ferry Salim","character":""},{"name":"Rana Audi Marissa","character":""},{"name":"Fandy Christian","character":""},{"name":"Dito Darmawan","character":""},{"name":"Andovi da Lopez","character":""}]'::jsonb, null, null),
(607833, '인턴', 'Drama', 133, 'NR', 'A story about what happens when Seon-wu, the CEO of a fashion company who is more passionate than anyone when it comes to work, hires Ki-ho, who has a wealth of life experience, as a silver intern.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/9PX4rGgP1pXRlGcHkxzRsgvll8f.jpg', 'https://image.tmdb.org/t/p/w1280/OroFBNgB2RBzj2X65CweVhhQQG.jpg', 7, 'XMp9ietHc8A', '2026-10-30', 3.018, 3, 'tt43741215', 5.7, 59, null, 'Drama, Komedi', '김도영', '김도영, 왕혜지', '최재원, 송순호', 'Anthology Studios, Warner Bros. Korea', '[{"name":"최민식","character":"Kim Ki-ho"},{"name":"한소희","character":"Lee Seon-wu"},{"name":"김준한","character":"Young-hwan"},{"name":"류혜영","character":"Choi Min-ah"},{"name":"김금순","character":"Hee-sook"},{"name":"김요한","character":"Ju-seong"},{"name":"박예니","character":"Yu-jin"},{"name":"윤상정","character":"Yoon-hee"},{"name":"강태오","character":"Min-wook"},{"name":"한지은","character":"Lu-da"}]'::jsonb, null, null),
(1688795, '투모로우바이투게더 월드 투어 ‘액트 : 투모로우''', 'Musik', 97, 'NR', 'Like shining stars, TOMORROW X TOGETHER’s fourth world tour ''ACT : TOMORROW'' unfolds as a dazzling journey toward the tomorrow they promised together. From its beautiful storytelling to the stunning production and powerful live performances that captivated MOA around the world, experience the immersive energy of TOMORROW X TOGETHER’s spectacular world tour on the big screen!', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/aRoPHxYzfQjCLxSp4H4sJANNmou.jpg', 'https://image.tmdb.org/t/p/w1280/35hGgrsbnpuex4XpdAlnQG1ssvk.jpg', null, 'q0XKUFGn_M4', '2026-10-24', 2.137, 0, 'tt46658752', null, null, null, 'Musik, Dokumenter', 'Taehwan Yum', null, null, 'HYBE', '[{"name":"수빈","character":"Self"},{"name":"연준","character":"Self"},{"name":"범규","character":"Self"},{"name":"태현","character":"Self"},{"name":"휴닝카이","character":"Self"}]'::jsonb, 'NR', null),
(969681, 'Spider-Man: Brand New Day', 'Cerita Fiksi', 145, 'NR', 'Empat tahun setelah peristiwa Spider-Man: No Way Home, Peter Parker sudah tidak ada lagi dan Spider-Man kini berada di puncak kemampuannya dalam menjaga Kota New York tetap aman. Semuanya berjalan dengan baik hingga serangkaian kejahatan yang tidak biasa menyeret Spider-Man ke dalam jaring misteri yang lebih besar dari apa pun yang pernah ia hadapi sebelumnya. Untuk menghadapi apa yang akan datang, Spider-Man tidak hanya harus berada dalam kondisi fisik dan mental terbaiknya, tetapi juga harus siap menghadapi konsekuensi dari masa lalunya!', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/bjiS5ipwxb9JFy3XRRN4OAilSeX.jpg', 'https://image.tmdb.org/t/p/w1280/subj7knTn4DeS6KS7qI66EQKe9i.jpg', 8.5, 'P3uI5sLosKU', '2026-07-29', 663.5, 5645, 'tt22084616', 8, 327986, 'PG-13', 'Cerita Fiksi, Aksi, Petualangan', 'Destin Daniel Cretton', 'Steve Ditko, Stan Lee, Erik Sommers, Chris McKenna', 'Kevin Feige, Amy Pascal, Rachel O''Connor, Avi Arad', 'Marvel Studios, Columbia Pictures, Pascal Pictures, TSG Entertainment', '[{"name":"Tom Holland","character":"Peter Parker / Spider-Man"},{"name":"Sadie Sink","character":"Jean Grey"},{"name":"Tramell Tillman","character":"William ''Bill'' Metzger"},{"name":"Zendaya","character":"MJ"},{"name":"Jacob Batalon","character":"Ned Leeds"},{"name":"Jon Bernthal","character":"Frank Castle / Punisher"},{"name":"Mark Ruffalo","character":"Bruce Banner / Hulk"},{"name":"Florence Pugh","character":"Yelena Belova / Black Widow"},{"name":"Liza Colón-Zayas","character":"Detective Jean DeWolff"},{"name":"Marisa Tomei","character":"May Parker"}]'::jsonb, '13+', 19819),
(1288069, 'Tenzing', 'Drama', 126, 'NR', 'Seorang pria yang gigih memulai misi berisiko tinggi, dan menaklukkan rintangan yang tampak mustahil, demi mewujudkan impiannya menjadi orang pertama yang mencapai puncak Gunung Everest.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/eI0QW02PYqhnmIvLRdn9vrfVVP7.jpg', 'https://image.tmdb.org/t/p/w1280/6GXqVvL20Y0MpyVP30WoI2NPK69.jpg', 8.3, 'KkYCY5YR12U', '2026-10-09', 88.413, 48, 'tt6262770', 7.7, 289, 'PG', 'Drama, Sejarah', 'Jennifer Peedom', 'Luke Davies, Jennifer Peedom', 'Emile Sherman, Luke Davies, Iain Canning, Jennifer Peedom', 'Cross City Films, See-Saw Films, Apple Studios', '[{"name":"更登彭措","character":"Tenzing Norgay"},{"name":"Tom Hiddleston","character":"Ed Hillary"},{"name":"Willem Dafoe","character":"John Hunt"},{"name":"Samdrup Dorje Lama","character":"Boy Tenzing (9 Yrs)"},{"name":"Bhuchung Kata","character":"Sherpa"},{"name":"Johnny Flynn","character":"George Mallory"},{"name":"Lhakpa Tsamchoe","character":"Kinzom"},{"name":"Jampa Kalsang Tamang","character":"Mingma"},{"name":"Elizabeth Blackmore","character":"Mrs Ingram"},{"name":"Brandon McClelland","character":"Mr Ingram"}]'::jsonb, '13+', 1401),
(1291595, 'Insidious: Out of the Further', 'Kengerian', 106, 'NR', 'Gemma, a young mother raising her daughter in the house she grew up in, discovers she can travel into The Further, where she possesses an ability to bring what lives there back to the real world.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/4tTrW9dXCByS5wt2pXVWb58zNjz.jpg', 'https://image.tmdb.org/t/p/w1280/p40lmrdI4blcAPZQMTPaiy5v5Ym.jpg', 7.7, 'gXjurDkYnEM', '2026-08-19', 362.286, 789, 'tt32393988', 6.2, 13228, 'PG-13', 'Kengerian, Cerita Seru', 'Jacob Chase', 'Leigh Whannell, Jacob Chase, David Leslie Johnson-McGoldrick', 'Jason Blum, James Wan, Leigh Whannell, Oren Peli', 'Screen Gems, Stage 6 Films, Atomic Monster, TSG Entertainment', '[{"name":"Amelia Eve","character":"Gemma Hall"},{"name":"Island Austin","character":"Maya Hall"},{"name":"Brandon Perea","character":"Nick Mendoza"},{"name":"Lin Shaye","character":"Elise Rainier"},{"name":"Maisie Richardson-Sellers","character":"Clare"},{"name":"Sam Spruell","character":"Cyrus Lam"},{"name":"Joseph Lopez","character":"Lester"},{"name":"Robina Beard","character":"Edna"},{"name":"Susan Gray","character":"Patsy"},{"name":"Laura Gordon","character":"Ingrid Lilith Hall"}]'::jsonb, '13+', 5132),
(1101383, 'The End of Oak Street', 'Cerita Fiksi', 100, 'NR', 'After a mysterious cosmic event rips Oak Street from suburbia and transports their neighborhood to someplace unknown, the Platt family soon discovers that their very survival depends on them sticking together as they navigate their now unrecognizable surroundings.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/nlC0I1cCemzfNLYPnAhdydpOYOi.jpg', 'https://image.tmdb.org/t/p/w1280/b9q9VmbXDvJmTziRqkwdEmFdwhr.jpg', 7.1, 'u4tgctWuHc0', '2026-08-12', 141.698, 2096, 'tt27165187', 6.5, 39062, 'PG-13', 'Cerita Fiksi, Misteri, Cerita Seru', 'David Robert Mitchell', 'David Robert Mitchell', 'Hannah Minghella, Matt Jackson, David Robert Mitchell, J.J. Abrams', 'Warner Bros. Pictures, Domain Entertainment, Bad Robot, Jackson Pictures', '[{"name":"Anne Hathaway","character":"Denise Platt"},{"name":"Ewan McGregor","character":"Greg Platt"},{"name":"Maisy Stella","character":"Audrey Platt"},{"name":"Christian Convery","character":"Brian Platt"},{"name":"Jordan Alexa Davis","character":"Jeannette Christiansen"},{"name":"P.J. Byrne","character":"Mel Jacobs"},{"name":"Hudson Meek","character":"Kaden Tucker"},{"name":"Anne Gee Byrd","character":"Mrs. Huddleston"},{"name":"Emily Kuroda","character":"Mrs. Valcourt"},{"name":"Simms May","character":"Zachary"}]'::jsonb, '13+', 4149),
(1032863, 'Hipotesis Cinta', 'Percintaan', 112, 'NR', 'Berdasarkan novel laris New York Times, Hipotesis Cinta menceritakan Olive, calon Ph.D. yang spontan mencium profesor paling galak di departemennya, Adam Carlsen. Kebutuhan bersama mereka untuk hubungan palsu berubah menjadi eksperimen kecocokan yang mungkin memecahkan masalah cinta.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/jQol5xRU1e0JOL0ki4kDioj66Ah.jpg', 'https://image.tmdb.org/t/p/w1280/o7Oy9Gbx1CCyaweL8xUhtMW4Puq.jpg', 8, 'xwdamnfS6IM', '2026-09-23', 67.969, 619, 'tt22526100', null, null, 'R', 'Percintaan, Komedi', 'Claire Scanlon', 'Sarah Rothschild, Ali Hazelwood', 'Elizabeth Cantillon', 'MRC, Amazon MGM Studios, The Cantillon Company', '[{"name":"Lili Reinhart","character":"Olive Smith"},{"name":"Tom Bateman","character":"Dr. Adam Carlsen"},{"name":"Rachel Marsh","character":"Anh Pham"},{"name":"Jaboukie Young-White","character":"Malcolm Browne"},{"name":"Nicholas Duvernay","character":"Jeremy Langley"},{"name":"Arty Froushan","character":"Dr. Thomas Benton"},{"name":"Jeananne Goossen","character":"Dr. Juliet Aslan"},{"name":"Aladeen Tawfeek","character":"Dr. Eugene Fastuca"},{"name":"Kenny Wong","character":"McConnell"},{"name":"Daniel Brochu","character":"Dr. Hargrave"}]'::jsonb, 'R', 2706),
(687163, 'Project Hail Mary', 'Cerita Fiksi', 157, 'NR', 'Science teacher Ryland Grace wakes up on a spaceship light years from home with no recollection of who he is or how he got there. As his memory returns, he begins to uncover his mission: solve the riddle of the mysterious substance causing the sun to die out. He must call on his scientific knowledge and unorthodox ideas to save everything on Earth from extinction.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/iOb2fjXLbpJgyQXe46n1WtGCnaa.jpg', 'https://image.tmdb.org/t/p/w1280/8Tfys3mDZVp4tNoH2ktm06a0Tau.jpg', 8.6, 'NKYea63tQmI', '2026-03-15', 101.034, 8345, 'tt12042730', 8.2, 570200, 'PG-13', 'Cerita Fiksi, Petualangan', 'Phil Lord, Christopher Miller', 'Andy Weir, Drew Goddard', 'Rachel O''Connor, Ryan Gosling, Amy Pascal, Christopher Miller', 'Lord Miller, Amazon MGM Studios, Pascal Pictures, Open Invite Entertainment', '[{"name":"Ryan Gosling","character":"Ryland Grace"},{"name":"Sandra Hüller","character":"Eva Stratt"},{"name":"James Ortiz","character":"Rocky (voice)"},{"name":"Lionel Boyce","character":"Carl"},{"name":"Milana Vayntrub","character":"Olesya Ilyukhina"},{"name":"Ken Leung","character":"Yao"},{"name":"Priya Kansara","character":"Mary (voice)"},{"name":"Mia Soteriou","character":"Dr. Browne"},{"name":"Annelle Olaleye","character":"Olivia"},{"name":"Maya Eva Hosein","character":"Rekha"}]'::jsonb, '13+', 1897),
(1492640, 'UNABOMBER', 'Cerita Seru', 101, 'NR', 'Di drama yang terinspirasi kisah nyata ini, jalan Ted Kaczynski dari seorang genius dan objek percobaan di Harvard sampai menjadi Unabomber terkuak saat FBI memburunya.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/39aMkR8Y5vhCG9dTkjiqRl8AVqp.jpg', 'https://image.tmdb.org/t/p/w1280/58D9nalUYW5L5K0guw7hcpsEJBH.jpg', 6.6, 'B3tR6qQjbgI', '2026-09-25', 41.487, 475, 'tt6933238', 6.2, 10808, 'R', 'Cerita Seru, Drama, Kejahatan', 'Janus Metz', 'Sam Chalsen, Nelson Greaves', 'Sophie Cassidy', 'MRC, 2.0 Entertainment', '[{"name":"Russell Crowe","character":"Henry Murray"},{"name":"Jacob Tremblay","character":"Ted Kaczynski"},{"name":"Shailene Woodley","character":"Joanne Miller"},{"name":"Annabelle Wallis","character":"Christiana Morgan"},{"name":"Alexander Ludwig","character":"Leo Driver"},{"name":"Marc Menchaca","character":"Eddie Turrell"},{"name":"Steven Ogg","character":"Dean Kaplan"},{"name":"Mark Camacho","character":"Bill Ford"},{"name":"David Webster","character":"Roy"},{"name":"Bruce Ramsay","character":"Turk Kaczynski"}]'::jsonb, 'R', 2754),
(1084244, 'Toy Story 5', 'Animasi', 102, 'NR', 'When Bonnie receives a Lilypad tablet as a gift and becomes obsessed, Buzz, Woody, Jessie and the rest of the gang''s jobs become exponentially harder when they have to go head to head with the all-new threat to playtime.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/sfQtVlIHljToOwYjhe21KPGzZWK.jpg', 'https://image.tmdb.org/t/p/w1280/qjTqY5coNiz6sVtPng40IzltsoN.jpg', 8.3, 'QftAW9TTmuQ', '2026-06-17', 158.503, 2644, 'tt29355505', 7.4, 81658, 'PG', 'Animasi, Keluarga, Komedi, Petualangan', 'Andrew Stanton', 'Andrew Stanton, Kenna Harris', 'Lindsey Collins, Jessica Choi', 'Pixar', '[{"name":"Joan Cusack","character":"Jessie (voice)"},{"name":"Tom Hanks","character":"Woody (voice)"},{"name":"Tim Allen","character":"Buzz Lightyear (voice)"},{"name":"Conan O''Brien","character":"Smarty Pants (voice)"},{"name":"Scarlett Spears","character":"Bonnie (voice)"},{"name":"Greta Lee","character":"Lilypad (voice)"},{"name":"Shelby Rabara","character":"Snappy (voice)"},{"name":"Mykal-Michelle Harris","character":"Blaze (voice)"},{"name":"Craig Robinson","character":"Atlas (voice)"},{"name":"Jay Hernandez","character":"Bonnie’s Dad (voice)"}]'::jsonb, 'SU', 2047),
(1137844, 'Mayday', 'Aksi', 111, 'NR', 'Saat seorang pilot Angkatan Laut AS dalam misi rahasia selama Perang Dingin terjebak di belakang garis musuh, satu-satunya peluang untuk bertahan hidup adalah menjalin aliansi dengan seorang mantan agen KGB eksentrik.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/hVXjX1jLZ1ljFSNGXpjJfbTUOa7.jpg', 'https://image.tmdb.org/t/p/w1280/g7Ccid5kuD7A8hXWlsQiNfwOxaD.jpg', 7.9, 'om5Un9X720M', '2026-09-03', 26.003, 967, 'tt28014327', 6.9, 9404, 'PG-13', 'Aksi, Komedi', 'Jonathan Goldstein, John Francis Daley', 'John Francis Daley, Jonathan Goldstein', 'David Ellison, Dana Goldberg, Don Granger, Ashley Fox', 'Skydance Media, Maximum Effort, GoldDay', '[{"name":"Ryan Reynolds","character":"Troy Kelly"},{"name":"Kenneth Branagh","character":"Nikolai Ustinov"},{"name":"Marcin Dorociński","character":"Alexander Volkov"},{"name":"Мария Бакалова","character":"Anna Ustinov"},{"name":"David Morse","character":"Harold Kelly"},{"name":"Clark Johnson","character":"CDR Keith Hardwick"},{"name":"Wendy Crewson","character":"Assistant Director Karen Meadows"},{"name":"Louis Cancelmi","character":"Maj Pete Sanders"},{"name":"Josh Hamilton","character":"Consul General Dan Hennessy"},{"name":"Alex Mallari Jr.","character":"Danny ''Longshot'' Bowers"}]'::jsonb, '17+', 2023),
(950028, 'The Invite', 'Komedi', 107, 'NR', 'Joe and Angela''s marriage is on thin ice. When they invite their enigmatic upstairs neighbors for a dinner party, the night spirals into unexpected places. Have they reignited the spark or lit the match that burns it all down?', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/b7Dr8Chzse8VagexAporUu2RtLx.jpg', 'https://image.tmdb.org/t/p/w1280/lEwqBGNR65KZv6Ej5ufcmhZu2y2.jpg', 7.2, 'nelkiuezJxg', '2026-06-25', 31.283, 814, 'tt14173636', 7.5, 68555, 'R', 'Komedi, Drama, Percintaan', 'Olivia Wilde', 'Rashida Jones, Will McCormack', 'David Permut, Megan Ellison, Ben Browning, Saul Germaine', 'Annapurna Pictures, FilmNation Entertainment, Permut Presentations', '[{"name":"Olivia Wilde","character":"Angela"},{"name":"Seth Rogen","character":"Joe"},{"name":"Penélope Cruz","character":"Piña"},{"name":"Edward Norton","character":"Hawk"}]'::jsonb, 'R', 1385),
(1632981, 'Haciendo amigos', 'Komedi', 110, 'NR', 'Antonio and Félix, small-time thieves fleeing police after a jewelry heist, meet Eva, a theater group monitor. She mistakes Félix for Ángel, a new member. They use the confusion to hide, unaware they''ll spend a week with the group.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/aOEKqiRldd6pvNNopdDUsMfnlmJ.jpg', 'https://image.tmdb.org/t/p/w1280/rR0PEHlQU7pZEKxV1E9JYk7copr.jpg', 6.6, null, '2026-07-10', 18.291, 11, 'tt41801352', null, null, null, 'Komedi', 'David Marqués', 'Marta González de Vega', 'Santiago Segura', 'Sony Pictures Entertainment Iberia, Bowfinger, Esto También Pasará, Glow', '[{"name":"Quim Gutiérrez","character":"Félix"},{"name":"Antonio Resines","character":"Antonio"},{"name":"Megan Montaner","character":"Eva"},{"name":"Marta González de Vega","character":""},{"name":"Daniel Fez","character":"Teto"},{"name":"Giovani Florido","character":"Quijano"},{"name":"Raquel Cortés","character":"Raquel"},{"name":"Juan Fernández","character":"Juanillo"},{"name":"Sayago Ayuso","character":"Tejada"},{"name":"Curro Fire","character":"Ángel"}]'::jsonb, null, null),
(1284186, 'Sacrifice', 'Petualangan', 100, 'NR', 'During a star-studded charity gala brimming with celebrities, billionaires and empty speeches, a movie star in the midst of an existential crisis is taken hostage by a radical warrior and her devoted followers. As the night descends into chaos, both an inward journey and an outward adventure ensue, where the line between performance and belief, salvation and sacrifice, begins to blur.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/nLKejp8AUnvcxDPPuWxecvEqeZJ.jpg', 'https://image.tmdb.org/t/p/w1280/dslA1EcpHDHKXcQmUopjEfO4jPf.jpg', 5.5, 'u5qW1gMMSVI', '2026-04-09', 70.792, 46, 'tt32268992', 5.7, 552, 'R', 'Petualangan, Komedi, Aksi', 'Romain Gavras', 'Will Arbery, Romain Gavras', 'Romain Gavras, Robert Walak, Gregory Jankilevitsch, Klaudia Śmieja-Rostworowska', 'Mid March Media, Heretic, Iconoclast, Film4 Productions', '[{"name":"Chris Evans","character":"Mike Tyler"},{"name":"Anya Taylor-Joy","character":"Joan"},{"name":"Vincent Cassel","character":"Ben Bracken"},{"name":"Salma Hayek Pinault","character":"Gloria Bracken"},{"name":"John Malkovich","character":"Gunnar"},{"name":"Charli xcx","character":"Mother Nature"},{"name":"Sam Richardson","character":"Oliver"},{"name":"Zarene Dallas","character":"Freyja"},{"name":"Yung Lean","character":"Arthur"},{"name":"Jade Croot","character":"Louise"}]'::jsonb, 'R', null),
(1315772, 'Minions & Monsters', 'Petualangan', 90, 'NR', 'This is the rambunctious, ridiculous and totally true story of how the Minions conquered Hollywood, became movie stars, lost everything, unleashed monsters onto the world and then banded together to try and save the planet from the mayhem they had just created.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/4LwvU9SZc8QQzW1X1FAPhNbXnEU.jpg', 'https://image.tmdb.org/t/p/w1280/kkcwhgSFd81QDlXo8ytrpHPQjhy.jpg', 7.6, 'V-O-uBaHk3c', '2026-06-24', 96.016, 1283, 'tt32890033', 6.3, 31007, 'PG', 'Petualangan, Animasi, Komedi, Keluarga, Fantasi', 'Pierre Coffin', 'Brian Lynch, Pierre Coffin', 'Chris Meledandri, William Ryan', 'Universal Pictures, Illumination', '[{"name":"Pierre Coffin","character":"The Minions (voice)"},{"name":"Trey Parker","character":"Goomi (voice)"},{"name":"Christoph Waltz","character":"Max (voice)"},{"name":"Allison Janney","character":"Olivia (voice)"},{"name":"Jesse Eisenberg","character":"Dort (voice)"},{"name":"Jeff Bridges","character":"Frank / Elwood (voice)"},{"name":"Zoey Deutch","character":"Debbie (voice)"},{"name":"Bobby Moynihan","character":"Phillips (voice)"},{"name":"Phil LaMarr","character":"Howard (voice)"},{"name":"George Lucas","character":"George Lucas (voice)"}]'::jsonb, 'SU', 1063),
(1212763, 'Evil Dead Burn', 'Kengerian', 110, 'NR', 'After her husband''s abrupt death, Alice seeks solace with his remaining family — descendants of a leading researcher on demonic possession. As her in-laws transform one by one into creatures that feed on fear, she comes to discover that the vows she took in life survive even in death.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/uRxrNXQWkHoENm3nwVOZDYSCx2F.jpg', 'https://image.tmdb.org/t/p/w1280/o0jkkpcN81QqSl8DMLScBCXyUH9.jpg', 7.6, 'RddZObTlmA8', '2026-07-07', 51.802, 1750, 'tt31170389', 6.3, 46156, 'R', 'Kengerian', 'Sébastien Vaniček', 'Sébastien Vaniček, Florent Bernard', 'Robert Tapert, Sam Raimi', 'New Line Cinema, Screen Gems, Ghost House Pictures', '[{"name":"Souheila Yacoub","character":"Alice"},{"name":"Tandi Wright","character":"Susan"},{"name":"Hunter Doohan","character":"Joseph"},{"name":"Luciane Buchanan","character":"Thya"},{"name":"Erroll Shand","character":"Edgar"},{"name":"Maude Davey","character":"Polly"},{"name":"George Pullar","character":"Will"},{"name":"Greta van den Brink","character":"Jessica"},{"name":"Keanu Karim","character":"Jared"},{"name":"Victory Ndukwe","character":"Leo"}]'::jsonb, '21+', 1112),
