(1457866, 'THE FURTHER MIS-ADVENTURES OF CLIFF BOOTH', 'Drama', 100, 'NR', 'Eight years after the events of Once Upon a Time in... Hollywood, Cliff Booth returns to a changing Los Angeles. Now working as a fixer in the shadows of the Hollywood studio system, Cliff finds himself entangled in a dangerous web of secrets, crimes and betrayals that will test everything he knows about loyalty and survival.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/nuNOKDt0mVWhwq2HZ9ytczuUFSf.jpg', 'https://image.tmdb.org/t/p/w1280/aRO4TuqF8dkRCb5tPlsSlpJbmQD.jpg', null, 'RjEZaUBbUvU', '2026-11-25', 7.056, 0, 'tt36408401', null, null, null, 'Drama, Komedi, Cerita Seru', 'David Fincher', 'Quentin Tarantino', 'David Heyman, Shannon McIntosh, Stacey Sher, Quentin Tarantino', 'Heyday Films, Netflix, Plan B Entertainment', '[{"name":"Brad Pitt","character":"Cliff Booth"},{"name":"Elizabeth Debicki","character":"Karen Crosby"},{"name":"Scott Caan","character":"Charlie Peters"},{"name":"Carla Gugino","character":"Toni Peters"},{"name":"Yahya Abdul-Mateen II","character":"Roderick ''Hot Rod'' Harrison"},{"name":"Peter Weller","character":"Gus Booth"},{"name":"Matt Groove","character":"Mr. Verdusco"},{"name":"JB Tadena","character":"Mr. Verdusco"},{"name":"Corey Fogelmanis","character":""},{"name":"Karren Karagulian","character":""}]'::jsonb, null, null),
(1306322, 'Spaceballs: The New One', 'Komedi', 100, 'NR', 'Forty years after the events of the first Spaceballs, the galaxy is once again under threat. A threat so evil, so unstoppable, so completely lacking in any original ideas, that it has vowed to bring back the past... every last bit of it. With Lone Starr in hiding, Queen Vespa on the throne, and the Schwartz stretched thinner than a franchise releasing TV episodes theatrically, the only hope for the galaxy is Vespa''s undisciplined son, Prince Starburst, and a mysterious Palace advisor named Destiny. Together, they must find Lone Starr, Yogurt, and any other iconic legacy characters fans are demanding before they discover the hard way that, while some threats you can fight, the reboot is not one of them.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/9usPcpMm8GhzkHIXqiklhPrflY3.jpg', 'https://image.tmdb.org/t/p/w1280/6dOmk6RoedeTSelTj2b473xThZH.jpg', null, null, '2027-04-22', 4.133, 0, 'tt32659463', null, null, null, 'Komedi, Cerita Fiksi, Petualangan', 'Josh Greenbaum', 'Benji Samit, Josh Gad, Dan Hernandez', 'Josh Gad, Brian Grazer, Jeb Brody, Mel Brooks', 'Brooksfilms, Imagine Entertainment, Amazon MGM Studios', '[{"name":"Bill Pullman","character":"Lone Starr"},{"name":"Rick Moranis","character":"Dark Helmet"},{"name":"Lewis Pullman","character":"Starburst"},{"name":"Daphne Zuniga","character":"Queen Vespa"},{"name":"Mel Brooks","character":"President Skroob / Yogurt"},{"name":"George Wyner","character":"Colonel Sandurz"},{"name":"Keke Palmer","character":"Destiny"},{"name":"Michael Winslow","character":"Radar Technician"},{"name":"Josh Gad","character":""},{"name":"Anthony Carrigan","character":""}]'::jsonb, null, null),
(791523, 'Wildwood', 'Animasi', 132, 'NR', 'Prue and her classmate Curtis are drawn into a magical forest filled with enchanted creatures, loyal allies, and formidable adversaries as they embark on a desperate quest to rescue Prue''s abducted baby brother from a murder of crows led by a mysterious woman named Alexandra.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/snFM00mpNAfUzUtkdEW0uDEvXA0.jpg', 'https://image.tmdb.org/t/p/w1280/sl5NJ1vtyhP9Vr88bB4blULsJYp.jpg', null, 'bJQGtSeLPII', '2026-10-19', 16.366, 0, 'tt2056785', null, null, null, 'Animasi, Petualangan, Fantasi', 'Travis Knight', 'Chris Butler, Colin Meloy', 'Travis Knight, Arianne Sutner, Samuel Wilson', 'LAIKA', '[{"name":"Peyton Elizabeth Lee","character":"Prue McKeel (voice)"},{"name":"Jacob Tremblay","character":"Curtis Mehlberg (voice)"},{"name":"Carey Mulligan","character":"Alexandra (voice)"},{"name":"Mahershala Ali","character":"Brenden (voice)"},{"name":"Angela Bassett","character":"The General (voice)"},{"name":"Awkwafina","character":"Septima (voice)"},{"name":"Jake Johnson","character":"Mr. McKeel (voice)"},{"name":"Charlie Day","character":"Dmitri (voice)"},{"name":"Amandla Stenberg","character":"Niamh (voice)"},{"name":"Jemaine Clement","character":"Roger Swindon (voice)"}]'::jsonb, 'PG-13', null),
(1078446, 'Violent Night 2', 'Aksi', 110, 'NR', 'When Santa forgets the true meaning of Christmas, he finds himself in the heart of a lively mall community in desperate need of his help. Sapped of his magic, he’ll need another way to take on the goons threatening the mall, and time is running out. Santa has to rediscover his faith in goodness and call in some last-minute reinforcements from the one person no baddie wants to tangle with: Mrs. Claus.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/7HPvgItDw9NgW3iy4tFRRuGNbuN.jpg', 'https://image.tmdb.org/t/p/w1280/78dChJs7doULSEhIiOvGUcXQRGU.jpg', null, 'FmM2giDwLAE', '2026-12-02', 8.672, 0, 'tt32432428', null, null, null, 'Aksi, Komedi', 'Tommy Wirkola', 'Pat Casey, Josh Miller', 'David Leitch, Kelly McCormick', '87North Productions, Universal Pictures', '[{"name":"David Harbour","character":"Santa Claus"},{"name":"Kristen Bell","character":"Mrs. Claus"},{"name":"Daniela Melchior","character":""},{"name":"Jared Harris","character":""},{"name":"Joe Pantoliano","character":""},{"name":"Maxwell Jacob Friedman","character":""},{"name":"Andrew Bachelor","character":""},{"name":"Maggie Robertson","character":"Duff"},{"name":"David Lawrence Brown","character":""},{"name":"Sarah Luby","character":"Lexi"}]'::jsonb, '17+', null),
(1437511, 'How to Rob a Bank', 'Aksi', 122, 'NR', 'A crew of social media-savvy bank robbers broadcasts their daring heists, unaware that their growing viral fame has put them in the crosshairs of a veteran FBI agent and a brilliant software engineer. Despite the unlikely duo closing in, the crime ring pushes past their limits, putting everything on the line for their most ambitious heist yet.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/fC7om9keWj3U0vJvZ0XiDQmlLVe.jpg', 'https://image.tmdb.org/t/p/w1280/xghtLO90cQPybH85aw1C3bZ2P3.jpg', null, 'MVvWKh336m4', '2026-11-11', 8.056, 0, 'tt35866986', null, null, 'R', 'Aksi, Kejahatan, Cerita Seru', 'David Leitch', 'Mark Bianculli', 'Kelly McCormick, David Leitch, Brian Grazer, Jeb Brody', '87North Productions, Imagine Entertainment, Amazon MGM Studios', '[{"name":"Nicholas Hoult","character":"Ryan"},{"name":"Zoë Kravitz","character":"Reagan Gardner"},{"name":"Anna Sawai","character":""},{"name":"Rhenzy Feliz","character":""},{"name":"Pete Davidson","character":"Vince"},{"name":"John C. Reilly","character":"Agent West"},{"name":"Christian Slater","character":"Walton"},{"name":"Tati Gabrielle","character":"Skyler"},{"name":"Young Mazino","character":""},{"name":"Michael Gandolfini","character":""}]'::jsonb, 'R', null),
(1538497, 'Hexed', 'Petualangan', 99, 'NR', 'An impulsive and unconventional teenage girl named Billie discovers secret magical abilities which, once unleashed, hurtle her into a spectacle-filled journey out of suburbia and into a vast witch realm called Hexe. Forced to team up with her cautious mother, Alice, they uncover family mysteries that could change the world of witches forever.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/yykeYKbDBM9eUMJUucaaDo2mi1p.jpg', 'https://image.tmdb.org/t/p/w1280/wZ9Me7OndzgBOEAa8nSBNPu3Sl4.jpg', null, 'KXO21xZdUaM', '2026-11-25', 22.872, 0, 'tt38077943', null, null, null, 'Petualangan, Animasi, Keluarga, Fantasi, Komedi', 'Jason Hand, ฝน วีระสุนทร', 'Dana Ledoux Miller, Jared Bush', 'Roy Conli, Yvett Merino', 'Walt Disney Animation Studios', '[{"name":"Hailee Steinfeld","character":"Billie Doe (voice)"},{"name":"Rashida Jones","character":"Alice Doe (voice)"},{"name":"Jodie Foster","character":"Queen Celeste (voice)"},{"name":"Walton Goggins","character":"Beef Roger Crummchuk (voice)"},{"name":"Tracey Ullman","character":"Ms. Quill (voice)"},{"name":"Stephen Fry","character":"Elias Quire (voice)"},{"name":"Henry Winkler","character":"Nigel (voice)"},{"name":"Dan Stevens","character":"Hieronymous (voice)"},{"name":"Brett Gelman","character":"(voice)"},{"name":"Samson Kayo","character":"(voice)"}]'::jsonb, 'PG', null),
(1523140, 'Man of Tomorrow', 'Aksi', 100, 'NR', 'Superman and Lex Luthor find themselves forced to work together—to a certain degree—against a much, much bigger threat when Brainiac sets his sights on Earth.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/tYLgfKk3cEk7LskgxWyW37Nty01.jpg', 'https://image.tmdb.org/t/p/w1280/lX2TpAZxdIus6cnMCDBOrs96NBY.jpg', null, null, '2027-07-07', 5.306, 0, 'tt37833661', null, null, null, 'Aksi, Cerita Fiksi, Petualangan', 'James Gunn', 'James Gunn, Joe Shuster, Jerry Siegel', 'Peter Safran, James Gunn', 'DC Studios, Troll Court Entertainment, The Safran Company', '[{"name":"David Corenswet","character":"Superman"},{"name":"Nicholas Hoult","character":"Lex Luthor"},{"name":"Rachel Brosnahan","character":"Lois Lane"},{"name":"Lars Eidinger","character":"Brainiac"},{"name":"Frank Grillo","character":"Rick Flag Sr."},{"name":"Isabela Merced","character":"Hawkgirl"},{"name":"Aaron Pierre","character":"John Stewart"},{"name":"Skyler Gisondo","character":"Jimmy Olsen"},{"name":"Sara Sampaio","character":"Eve Teschmacher"},{"name":"María Gabriela de Faría","character":"The Engineer"}]'::jsonb, null, null),
(1567605, 'Ebenezer', 'Fantasi', 120, 'NR', 'An elderly miser embarks on a supernatural journey after visits from the ghost of his former business partner and the Spirits of Christmas Past, Present, and Yet to Come force him to confront his past and fight for a second chance at happiness.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/6H2N59jJW1hZEzn2ZdrMvJw5vNI.jpg', 'https://image.tmdb.org/t/p/w1280/bG8uwYAq5Y9bPDaoxq2eHjopA9T.jpg', null, 'l_Ozo1xUgbU', '2026-11-11', 14.576, 0, 'tt38773219', null, null, null, 'Fantasi, Komedi', 'Ti West', 'Nathaniel Halpern, Charles Dickens', 'Emma Watts', 'Paramount Pictures, Domain Entertainment, Wattsco, IN.2 FILM', '[{"name":"Johnny Depp","character":"Ebenezer Scrooge"},{"name":"Rupert Grint","character":"Bob Cratchit"},{"name":"Daisy Ridley","character":"Emily Cratchit"},{"name":"Andrea Riseborough","character":"Ghost of Christmas Past"},{"name":"Tramell Tillman","character":"Ghost of Christmas Present"},{"name":"Ian McKellen","character":"Jacob Marley"},{"name":"Sam Claflin","character":"Fred"},{"name":"Charlie Murphy","character":""},{"name":"Arthur Conti","character":"Young Ebenezer"},{"name":"Alfie Buck","character":"Child Ebenezer"}]'::jsonb, null, null),
(1300926, 'The Angry Birds Movie 3', 'Animasi', 96, 'NR', 'Red faces his greatest challenge yet - surviving fatherhood - while saving the world.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/oxaW6X3xohnzdFSBKCrCjRDckMe.jpg', 'https://image.tmdb.org/t/p/w1280/ieAytQ8YcWEZGQpbBy7vHVddwd.jpg', null, 'a9DB_aUMzME', '2026-12-23', 9.415, 0, 'tt32557122', null, null, null, 'Animasi, Komedi, Keluarga', 'John Rice', 'Thurop Van Orman', 'John Cohen, Carla Connor, Dan Chuba, Namit Malhotra', 'Rovio Animation, SEGA of America, Flywheel Media, One Cool Films', '[{"name":"Jason Sudeikis","character":"Red (voice)"},{"name":"Josh Gad","character":"Chuck (voice)"},{"name":"Danny McBride","character":"Bomb (voice)"},{"name":"Rachel Bloom","character":"Silver (voice)"},{"name":"Emma Myers","character":"June (voice)"},{"name":"Walker Scobell","character":"Glider (voice)"},{"name":"Psalm West","character":"Olly (voice)"},{"name":"James Austin Johnson","character":"Fuzzy (voice)"},{"name":"Tim Robinson","character":"Porkchop (voice)"},{"name":"Lily James","character":"(voice)"}]'::jsonb, null, null),
(858035, 'Klara and the Sun', 'Cerita Fiksi', 117, 'NR', 'An Artificial Friend named Klara finds a deep bond with a troubled young girl, bringing light and hope to a grieving family through her unwavering devotion and innocent wonder.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/xqovj2p6HRsgHxN81qYAYF4StgM.jpg', 'https://image.tmdb.org/t/p/w1280/s4E7NDJCOG3wqc5psv2RLr9QfUm.jpg', null, 'wixzainceAE', '2026-10-21', 16.12, 0, 'tt14371256', null, null, null, 'Cerita Fiksi, Drama, Komedi', 'Taika Waititi', 'Dahvi Waller, Taika Waititi', 'Garrett Basch, David Heyman, Taika Waititi', '3000 Pictures, Heyday Films, Defender Films, TSG Entertainment', '[{"name":"Jenna Ortega","character":"Klara"},{"name":"Mia Tharia","character":"Josie"},{"name":"Amy Adams","character":"Chrissie"},{"name":"Natasha Lyonne","character":"Manager"},{"name":"Aran Murphy","character":"Rick"},{"name":"Rachel House","character":"Melania"},{"name":"Steve Buscemi","character":""},{"name":"Davida McKenzie","character":"Simone"},{"name":"Harry Greenwood","character":""},{"name":"Anastasiia Aksiuta","character":"AF-1"}]'::jsonb, 'PG-13', null),
(891621, 'Wild Horse Nine', 'Komedi', 117, 'NR', 'Shortly before the 1973 Chilean coup, CIA agents Chris and Lee are dispatched from Santiago to Easter Island by their bureau chief, MJ. Amongst the Island''s iconic statues, and as the longtime partners wrestle with their dark pasts and present conspiracies, Chris''s newfound bond with a pair of rebellious students threatens to send everyone’s trip to this remote paradise sideways.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/dNJFRtVg3xLQ7dbNIQ55cmmIniD.jpg', 'https://image.tmdb.org/t/p/w1280/b17UWf3LqHgKolQkXckne32qv0.jpg', null, 'kqxuamKxRTo', '2026-10-30', 12.551, 0, 'tt15799564', null, null, null, 'Komedi, Kejahatan, Cerita Seru', 'Martin McDonagh', 'Martin McDonagh', 'Martin McDonagh, Graham Broadbent, Peter Czernin, Anita Overland', 'Searchlight Pictures, Blueprint Pictures, Film4 Productions, TSG Entertainment', '[{"name":"John Malkovich","character":"Chris"},{"name":"Sam Rockwell","character":"Lee"},{"name":"Steve Buscemi","character":"MJ"},{"name":"Mariana di Girolamo","character":"Monica"},{"name":"Ailín Salas","character":"Alicia"},{"name":"Tom Waits","character":""},{"name":"Parker Posey","character":"Marge"},{"name":"Paola Giannini","character":""},{"name":"Samuel Wayt","character":"Teenage Kid"}]'::jsonb, 'R', null),
(1195803, 'Wicker', 'Percintaan', 105, 'NR', 'On the outskirts of a village by the sea, lives a Fisherwoman; smelly, single and perpetually ridiculed. One day, fed up with her stuffy, small-minded neighbours, she commissions herself a husband to be made from wicker. In an otherwise conservative town, this unconventional romance sparks outrage, jealousy and chaos.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/6FcBZOKvyrLCKGCyBG0ySCR4okt.jpg', 'https://image.tmdb.org/t/p/w1280/xVh1ypMoVkMf5IB7y3hnRplJ14c.jpg', null, 'UVAki9SGrlg', '2026-11-05', 15.217, 0, 'tt29611136', 7.4, 376, 'R', 'Percintaan, Fantasi, Komedi', 'Eleanor Wilson, Alex Huston Fischer', 'Eleanor Wilson, Alex Huston Fischer', 'Justin Lothrop, Ed Sinclair, Brent Stiefel, Olivia Colman', 'Topic Studios, Tango Entertainment, South of the River Pictures, Votiv Films', '[{"name":"Olivia Colman","character":"Fisherwoman"},{"name":"Alexander Skarsgård","character":"Wicker Husband"},{"name":"Peter Dinklage","character":"Basket Weaver"},{"name":"Elizabeth Debicki","character":"Tailor’s Wife"},{"name":"Marli Siu","character":"Basket Weaver''s Sister"},{"name":"Nabhaan Rizwan","character":"Tailor"},{"name":"Richard E. Grant","character":"Doctor"},{"name":"Kiell Smith-Bynoe","character":""},{"name":"Gustav Lindh","character":""},{"name":"Ella Bruccoleri","character":"Bakerwoman"}]'::jsonb, 'R', null),
(1497464, 'Gatto', 'Animasi', 100, 'NR', 'After years of maneuvering the canal-ridden, superstitious city of Venice, Italy, a scrappy black cat named Nero begins to question whether he’s lived the right lives. Indebted to Rocco, a ruthless local feline mob boss, Nero finds himself in a quandary and is forced to forge a truly unexpected friendship that may finally lead him to his purpose — unless Venice gets the better of him first.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/bgt6dSrwkJCMqdKWRpN4ZTAd1kL.jpg', 'https://image.tmdb.org/t/p/w1280/etB2OT0nUknOAPZV7EgbEbt6HJh.jpg', null, null, '2027-03-03', 22.794, 0, 'tt26443610', null, null, null, 'Animasi, Komedi, Kejahatan, Keluarga', 'Enrico Casarosa', null, 'Andrea Warren', 'Pixar', '[{"name":"Mark Ruffalo","character":"Nero (voice)"},{"name":"Laurence Fishburne","character":"Rocco (voice)"},{"name":"Enrico Casarosa","character":"Saverio (voice)"}]'::jsonb, null, null),
(1286656, 'I Play Rocky', 'Drama', 128, 'NR', 'The electrifying true story about an unknown actor with an unshakable belief that he wasn''t just meant to write Rocky—he was meant to be Rocky Balboa. Told "no" at every turn, Sylvester Stallone bets everything on himself, holding the line on playing the lead against seemingly impossible odds.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/xE5tY3lppZUyG7WKKThsuYHuAHr.jpg', 'https://image.tmdb.org/t/p/w1280/1lnnjBCRLZzKRhQipK5zm61YkPe.jpg', null, 'Kpc4o2J28QE', '2026-11-06', 7.109, 0, 'tt11995650', null, null, null, 'Drama, Sejarah', 'Peter Farrelly', 'Peter Gamble', 'Toby Emmerich, Christian Baha, Peter Farrelly, Michele Weiss', 'Eden Rock Media, Baha Productions, Fireside Films, FilmNation Entertainment', '[{"name":"Anthony Ippolito","character":"Sylvester Stallone"},{"name":"AnnaSophia Robb","character":"Sasha Czack"},{"name":"Stephan James","character":"Carl Weathers"},{"name":"Matt Dillon","character":"Frank Stallone Sr."},{"name":"P.J. Byrne","character":"Irwin Winkler"},{"name":"Jay Duplass","character":"John Avildsen"},{"name":"Kiki Seto","character":"Talia Shire"},{"name":"Toby Kebbell","character":"Robert Chartoff"},{"name":"Tracy Letts","character":"Sandy Maddox"},{"name":"Robert Morgan","character":"Burgess Meredith"}]'::jsonb, 'PG-13', null),
(1156621, 'Teenage Mutant Ninja Turtles: Mutant Mayhem 2', 'Aksi', 100, 'NR', 'Donnie, Raph, Leo, and Mikey are back for their next adventure with Master Splinter, the Mutants, April, and a new villain they have to face: The Shredder.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/yukp9qq3JmgatfMSGnxdyn6jtRX.jpg', 'https://image.tmdb.org/t/p/w1280/dYsXhu97sNCQbObZjq3awyrdoaf.jpg', null, null, '2027-08-12', 2.565, 0, 'tt31512072', null, null, null, 'Aksi, Animasi, Komedi, Keluarga, Cerita Fiksi', 'Jeff Rowe', null, 'James Weaver, Ramsay McBean, Evan Goldberg, Seth Rogen', 'Point Grey Pictures, Paramount Pictures, Nickelodeon Movies, Domain Entertainment', '[{"name":"Micah Abbey","character":"Donatello (voice)"},{"name":"Nicolas Cantu","character":"Leonardo (voice)"},{"name":"Brady Noon","character":"Raphael (voice)"},{"name":"Shamon Brown Jr.","character":"Michelangelo (voice)"},{"name":"成龍","character":"Splinter (voice)"},{"name":"Ayo Edebiri","character":"April O''Neil (voice)"}]'::jsonb, null, null),
(1425859, 'Remain', 'Percintaan', 100, 'NR', 'When reclusive architect Tate Gordon moves to small coastal town to complete his latest project, he encounters an alluring young woman who pulls him out of his shell, and into the center of a deadly mystery that hangs over the town.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/5hPNq5h2y8Ux6nPBRMEwZ8npVTp.jpg', 'https://image.tmdb.org/t/p/w1280/tWUizVQOYarekT6JRqPtQogIY3s.jpg', null, null, '2027-02-03', 8.086, 0, 'tt35621542', null, null, null, 'Percintaan, Kengerian, Misteri, Cerita Seru', 'M. Night Shyamalan', 'M. Night Shyamalan, Nicholas Sparks', 'Ashwin Rajan, M. Night Shyamalan, Marc Bienstock, Theresa Park', 'Blinding Edge Pictures', '[{"name":"Jake Gyllenhaal","character":"Tate Gordon"},{"name":"Phoebe Dynevor","character":"Wren"},{"name":"Ashley Walters","character":"Oscar"},{"name":"Julie Hagerty","character":"Louise"},{"name":"Jay O. Sanders","character":"Reece"},{"name":"Tracy Ifeachor","character":"Theresa"},{"name":"Hannah James","character":"Tessa"},{"name":"Caleb Ruminer","character":"Griffin"},{"name":"Kieran Mulcare","character":"Dax"},{"name":"Maria Dizzia","character":"Sydney"}]'::jsonb, null, null),
(1297467, 'The Exorcist: Martyrs', 'Kengerian', 100, 'NR', 'Thirteen years ago, New York City detective Julie Miller ended the terror reign of satanic serial killer Father Sunday. The case made her a hero, and she has thrown herself into her work ever since. Now a new killer scrawls her name in an altar boy''s blood on the walls of a church crypt, dragging her back into the darkness she believed she had buried with him.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/i3kvS445sWWIhuxgXywPuUcsoP0.jpg', 'https://image.tmdb.org/t/p/w1280/ePIY6b8TlIjqFzK1JKANPhxUIPn.jpg', null, 'iIEYfH-jg1Y', '2027-03-10', 12.55, 0, 'tt32492552', null, null, null, 'Kengerian', 'Mike Flanagan', 'Mike Flanagan, William Peter Blatty', 'Mike Flanagan, Jason Blum, David Robinson', 'Red Room Pictures, Morgan Creek Entertainment, Universal Pictures, Blumhouse Atomic Monster', '[{"name":"Scarlett Johansson","character":"Det. Julie Miller"},{"name":"Chiwetel Ejiofor","character":"Father William"},{"name":"Sasha Calle","character":"Det. Gina Restrepo"},{"name":"John Leguizamo","character":"Father Sunday"},{"name":"Laurence Fishburne","character":"Father Nichol"},{"name":"Diane Lane","character":"Mary Miller"},{"name":"Jacobi Jupe","character":"Max Miller"},{"name":"Scoot McNairy","character":"Clay Silver"},{"name":"Gil Bellows","character":"Peter Nicks"},{"name":"Rahul Kohli","character":""}]'::jsonb, null, null),
(1117898, 'The Cat in the Hat', 'Animasi', 114, 'NR', 'Assigned his toughest mission yet, the Cat must cheer up siblings Gabby and Sebastian as they adjust to life in a new town. Known for pushing boundaries, this agent of chaos must prove himself or risk losing his magical hat forever.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/mWN6knIVJ2o7eGwSm7mOgSCwNUc.jpg', 'https://image.tmdb.org/t/p/w1280/9y9o686DsQg0KzPtERzcW7Cf8IE.jpg', null, 'tkZpcypT8Z4', '2026-11-04', 15.071, 0, 'tt2321555', null, null, null, 'Animasi, Komedi, Petualangan, Fantasi, Keluarga', 'Erica Rivinoja, Alessandro Carloni', 'Alessandro Carloni, Erica Rivinoja, Caroline Goddard, Dr. Seuss', 'Daniela Mazzucato', 'DNEG, Dr. Seuss Enterprises, Warner Bros. Pictures Animation, A Stern Talking To', '[{"name":"Bill Hader","character":"The Cat in the Hat (voice)"},{"name":"Xochitl Gomez","character":"Gabby (voice)"},{"name":"Tiago Martinez","character":"Sebastian (voice)"},{"name":"Matt Berry","character":"Waffles the Fish (voice)"},{"name":"Quinta Brunson","character":"Sherri (voice)"},{"name":"Bowen Yang","character":"(voice)"},{"name":"America Ferrera","character":"Carmen (voice)"},{"name":"Paula Pell","character":"(voice)"},{"name":"Tituss Burgess","character":"(voice)"},{"name":"Giancarlo Esposito","character":"Mr. Hoogeboom (voice)"}]'::jsonb, 'PG', null),
(940009, 'Ray Gunn', 'Animasi', 119, 'NR', 'In Metropia, a gigantic city in an alternate future as seen from 1939, private eye Raymond Gunn is drawn into a case involving aliens, murder and a multimedia star named Venus Nova.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/rpP29aOKpHy1FhX8OZQdUICEs2j.jpg', 'https://image.tmdb.org/t/p/w1280/hhBoWDKmq9u8V2qi0Rtm3XGiydn.jpg', null, 'VL-xjzQFWsY', '2026-12-18', 6.989, 0, 'tt18270542', null, null, null, 'Animasi, Cerita Fiksi, Kejahatan, Misteri', 'Brad Bird', 'Brad Bird, Matthew Robbins', 'Brad Bird, John Lasseter, Lisa Beroud, David Ellison', 'Skydance Animation, Netflix Animation Studios', '[{"name":"Sam Rockwell","character":"Raymond Gunn (voice)"},{"name":"Scarlett Johansson","character":"Venus Nova (voice)"},{"name":"Tom Waits","character":"Eye-Ra (voice)"},{"name":"Matt Berry","character":"Francis ''Slugsy'' Xavier (voice)"},{"name":"Kathryn Hunter","character":"Vanzine Kaluta (voice)"},{"name":"Alan Tudyk","character":"Barry Vogel (voice)"},{"name":"Bobby Cannavale","character":"Arnold Dom (voice)"},{"name":"Michelle Rodriguez","character":"Roz Dexler (voice)"},{"name":"Faruq Tauheed","character":"Lou Blevins (voice)"},{"name":"Michael Chernus","character":"Sam Stelfreeze (voice)"}]'::jsonb, 'PG', null),
(1294189, 'The Mongoose', 'Aksi', 99, 'NR', 'A falsely accused war hero with nothing to lose leads police on an epic televised cross-country car chase, helped by members of his former Special Forces Army battalion and closely monitored by a fascinated public rooting for his safe getaway.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/eSS5mvSG84UUuvtbHel5Yu3Wik4.jpg', 'https://image.tmdb.org/t/p/w1280/iRIhPqqoUHiFBxn8oYf3gCQnaKk.jpg', null, 'aHrMFtt40_Q', '2026-10-29', 143.134, 0, 'tt13611778', null, null, null, 'Aksi, Cerita Seru', 'Mark Vanselow', 'Thompson Evans', 'Al Corley, Bart Rosenblatt, Eugene Musso', 'Code Entertainment, The Solution', '[{"name":"Liam Neeson","character":"Ryan ''Fang'' Flanagan"},{"name":"Marisa Tomei","character":"Tara"},{"name":"Ving Rhames","character":"Tanker"},{"name":"Michael Chiklis","character":"Major Walter Pope"},{"name":"Brett Tucker","character":"Todd"},{"name":"Stella Stocker","character":"Helene (voice)"},{"name":"Hamish Michael","character":"Captain Parks"},{"name":"Toby Truslove","character":"Captain McBride"},{"name":"Eddie Baroo","character":"Veteran Seth"},{"name":"Maurice Marvel Meredith","character":"Major James Tilton"}]'::jsonb, 'R', null),
(615121, 'The Thomas Crown Affair', 'Kejahatan', 100, 'NR', 'A debonair, adventuresome man believes he has pulled off the perfect multi-million dollar heist, only to match wits with an insurance investigator who will do anything to get her man.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/sT1TQeAy1PdRfPIb6rrM2DB7DB.jpg', 'https://image.tmdb.org/t/p/w1280/4IwoYgyFdBCELwCr9VmEH1u0wwF.jpg', null, 'gnm4HgIAVmU', '2027-03-04', 8.135, 0, 'tt5500064', null, null, null, 'Kejahatan, Percintaan, Cerita Seru', 'Michael B. Jordan', 'Alan Trustman, Drew Pearce, Jason Hall', 'Michael B. Jordan, Elizabeth Raposo, Patrick McCormick, Marc Toberoff', 'Outlier Society, AGBO, Atlas Entertainment, Amazon MGM Studios', '[{"name":"Michael B. Jordan","character":"Thomas Crown"},{"name":"Adria Arjona","character":""},{"name":"Kenneth Branagh","character":""},{"name":"Lily Gladstone","character":""},{"name":"Danai Gurira","character":""},{"name":"Pilou Asbæk","character":""},{"name":"Aiysha Hart","character":""}]'::jsonb, null, null)
on conflict (tmdb_id) do update set
  title = excluded.title,
  genre = excluded.genre,
  duration_min = excluded.duration_min,
  synopsis = excluded.synopsis,
  poster_url = excluded.poster_url,
  backdrop_url = excluded.backdrop_url,
  vote_average = excluded.vote_average,
  trailer_key = excluded.trailer_key,
  release_date = excluded.release_date,
  popularity = excluded.popularity,
  vote_count = excluded.vote_count,
  -- data IMDb tidak ditimpa dengan kosong kalau kali ini OMDb tidak dipakai
  imdb_id = coalesce(excluded.imdb_id, movies.imdb_id),
  imdb_rating = coalesce(excluded.imdb_rating, movies.imdb_rating),
  imdb_votes = coalesce(excluded.imdb_votes, movies.imdb_votes),
  age_rated = coalesce(excluded.age_rated, movies.age_rated),
  genres = coalesce(excluded.genres, movies.genres),
  director = coalesce(excluded.director, movies.director),
  writers = coalesce(excluded.writers, movies.writers),
  producers = coalesce(excluded.producers, movies.producers),
  production = coalesce(excluded.production, movies.production),
  cast_members = coalesce(excluded.cast_members, movies.cast_members),
  certification = coalesce(excluded.certification, movies.certification),
  watchers = excluded.watchers;

-- Jadwal 7 hari ke depan di semua bioskop.
-- Fungsi ini dibuat oleh supabase-cinema-auth.sql, jadi file itu harus dijalankan lebih dulu.
select refresh_showtimes(7) as jadwal_baru_dibuat;
